{"mainClass": "FeePost", "javaSource": "import java.io.*;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

public class FeePost {
    private static BufferedReader payReader;
    private static BufferedWriter postWriter;
    private static boolean endOfPayments = false;
    private static String wsFeePgm = "FEECALC";

    // current PAY record fields
    private static String payId;
    private static BigDecimal payAmount;
    // WS-FEE
    private static BigDecimal wsFee = BigDecimal.ZERO;

    public static void main(String[] args) throws Exception {
        String payInPath = System.getenv("DD_PAYIN");
        String postOutPath = System.getenv("DD_POSTOUT");
        if (payInPath == null || postOutPath == null) {
            System.err.println("Missing DD env vars");
            System.exit(1);
        }
        payReader = Files.newBufferedReader(Paths.get(payInPath), StandardCharsets.ISO_8859_1);
        postWriter = Files.newBufferedWriter(Paths.get(postOutPath), StandardCharsets.ISO_8859_1);

        m0000Main();

        if (payReader != null) payReader.close();
        if (postWriter != null) postWriter.close();
    }

    private static void m0000Main() throws Exception {
        wsFeePgm = "FEECALC";
        m8000Read();
        while (!endOfPayments) {
            m2000Post();
        }
    }

    private static void m2000Post() throws Exception {
        // CALL WS-FEE-PGM USING PAY-AMOUNT WS-FEE
        // WS-FEE-PGM is always FEECALC
        feeCalc(payAmount);

        String postId = payId;
        BigDecimal postAmount = payAmount;
        BigDecimal postFee = wsFee;

        String postRec = formatPostRec(postId, postAmount, postFee);
        postWriter.write(postRec);
        postWriter.write(System.lineSeparator()); // LINE SEQUENTIAL - write uses platform but should be LF; use write line
        // To ensure byte-identical, we wrote line separator; GnuCOBOL line sequential uses LF on linux.
        // We already wrote newline; above writes system line separator but we need LF only.
        // Correct by not duplicating: we did write LF via lineSeparator; keep as is for Linux (LF).
        m8000Read();
    }

    // FEECALC logic
    private static void feeCalc(BigDecimal lAmount) {
        BigDecimal lFee;
        if (lAmount.compareTo(BigDecimal.ZERO) > 0) {
            // COMPUTE L-FEE ROUNDED = L-AMOUNT * 0.015
            BigDecimal raw = lAmount.multiply(new BigDecimal("0.015"));
            // ROUNDED to PIC S9(5)V99 => 2 decimal places, HALF_UP
            lFee = raw.setScale(2, RoundingMode.HALF_UP);
            if (lFee.compareTo(new BigDecimal("1.00")) < 0) {
                lFee = new BigDecimal("1.00");
            }
        } else {
            lFee = BigDecimal.ZERO.setScale(2);
        }
        // MOVE to WS-FEE PIC S9(5)V99 : ensure scale 2
        wsFee = lFee.setScale(2, RoundingMode.UNNECESSARY);
    }

    private static void m8000Read() throws Exception {
        String line = payReader.readLine();
        if (line == null) {
            endOfPayments = true;
            return;
        }
        // PAY-REC is 14 bytes LINE SEQUENTIAL: X(6) + S9(5)V99 SIGN LEADING SEPARATE (8 chars)
        // If line shorter, pad with spaces
        if (line.length() < 14) {
            line = String.format("%-14s", line);
        }
        payId = line.substring(0, 6);
        String amtField = line.substring(6, 14);
        payAmount = parseSignLeadingSeparate(amtField);
    }

    private static BigDecimal parseSignLeadingSeparate(String field) {
        // field length 8: sign (+/-) + 7 digits (5 int +2 dec)
        if (field.length() == 0) return BigDecimal.ZERO;
        char signChar = field.charAt(0);
        String digits = field.substring(1);
        // digits may contain spaces? trim
        digits = digits.trim();
        if (digits.isEmpty()) digits = "0";
        // ensure 7 digits
        // remove any non-digit
        StringBuilder sb = new StringBuilder();
        for (char c : digits.toCharArray()) if (Character.isDigit(c)) sb.append(c);
        String d = sb.toString();
        if (d.isEmpty()) d = "0";
        // pad left with zeros to 7
        while (d.length() < 7) d = "0" + d;
        if (d.length() > 7) d = d.substring(d.length() - 7);
        String intPart = d.substring(0, 5);
        String decPart = d.substring(5, 7);
        BigDecimal val = new BigDecimal(intPart + "." + decPart);
        if (signChar == '-') val = val.negate();
        return val;
    }

    private static String formatSignLeadingSeparate(BigDecimal value) {
        // PIC S9(5)V99 SIGN LEADING SEPARATE => sign + 7 digits
        boolean negative = value.signum() < 0;
        BigDecimal abs = value.abs().setScale(2, RoundingMode.UNNECESSARY);
        // TRUNC(STD) overflow: keep only PIC digits (7 digits) i.e. modulo 10^7
        // For DISPLAY, overflow truncation keeps lowest digits.
        // Simulate by taking abs *100 as integer mod 10_000_000
        long scaled = abs.movePointRight(2).longValueExact(); // 0.. 9_999_999
        scaled = scaled % 10000000L;
        String digits = String.format("%07d", scaled);
        char sign = negative ? '-' : '+';
        return sign + digits;
    }

    private static String formatPostRec(String id, BigDecimal amount, BigDecimal fee) {
        String a = formatSignLeadingSeparate(amount);
        String f = formatSignLeadingSeparate(fee);
        return id + a + f;
    }
}
", "notes": "Implements TXNREC/PAYREC (14 bytes) and POSTREC (22 bytes) as LINE SEQUENTIAL with SIGN LEADING SEPARATE (sign char + 7 digits). FEECALC logic: 1.5% rounded HALF_UP to 2 decimals, minimum 1.00, zero/negative => 0. All decimal arithmetic uses BigDecimal. Paragraphs mapped to private methods m0000Main, m2000Post, m8000Read and feeCalc."}

{"mainClass": "Gen0001", "javaSource": "import java.io.*;
import java.math.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

public class Gen0001 {
    // File buffers
    private static List<String> inLines;
    private static int inIdx = 0;
    private static String inRecRaw = null;
    private static BufferedWriter outWriter;

    // Working storage
    private static boolean wsEof = false;
    private static BigDecimal wsDividendFull = BigDecimal.ZERO;
    private static BigDecimal wsDividendRounded = BigDecimal.ZERO;
    private static BigDecimal wsNewBalWork = BigDecimal.ZERO;
    private static BigDecimal wsRateWork = BigDecimal.ZERO;
    private static int wsReadCnt = 0;
    private static int wsWriteCnt = 0;

    // Current IN fields
    private static String inAcctNum;
    private static BigDecimal inAcctBalance;
    private static BigDecimal inAnnualRate;
    private static String inAcctType;
    private static String inBranchCode;
    private static String inHoldFlag;

    // OUT fields
    private static String outAcctNum;
    private static BigDecimal outDividendPosted;
    private static BigDecimal outNewBalance;
    private static BigDecimal outRateApplied;
    private static String outPostStatus;
    private static String outBranchCode;

    public static void main(String[] args) throws Exception {
        String infile = System.getenv("DD_INFILE");
        String outfile = System.getenv("DD_OUTFILE");
        if (infile == null) infile = System.getenv("DD_INFILE");
        if (outfile == null) outfile = System.getenv("DD_OUTFILE");

        // Guard: refuse reflection / processes etc - trivially satisfied
        inLines = new ArrayList<>();
        if (infile != null) {
            Path p = Paths.get(infile);
            if (Files.exists(p)) {
                byte[] bytes = Files.readAllBytes(p);
                String content = new String(bytes, StandardCharsets.ISO_8859_1);
                // LINE SEQUENTIAL: split on \n, keep lines without separators
                // Handle \r\n and \n
                String[] parts = content.split("\\r?\\n", -1);
                for (int i = 0; i < parts.length; i++) {
                    // The last empty after final newline should not be a record
                    // In COBOL LINE SEQUENTIAL, trailing newline does not create extra record
                    // So if file ends with newline, last split is empty -> ignore
                    if (i == parts.length - 1 && parts[i].isEmpty() && content.endsWith("\n")) continue;
                    // Also if content is empty, ignore
                    if (parts.length == 1 && parts[0].isEmpty()) continue;
                    inLines.add(parts[i]);
                }
            }
        }
        if (outfile != null) {
            outWriter = Files.newBufferedWriter(Paths.get(outfile), StandardCharsets.ISO_8859_1);
        } else {
            outWriter = new BufferedWriter(new OutputStreamWriter(System.out, StandardCharsets.ISO_8859_1));
        }

        mainPara();

        if (outWriter != null) outWriter.close();
    }

    private static void mainPara() throws Exception {
        // OPEN INPUT IN-FILE OUTPUT OUT-FILE implicit
        while (!wsEof) {
            readInFile();
            if (wsEof) {
                // AT END
            } else {
                processRec();
            }
        }
        // CLOSE
    }

    private static void readInFile() {
        if (inIdx >= inLines.size()) {
            wsEof = true;
            return;
        }
        String line = inLines.get(inIdx++);
        // Pad or truncate to 33
        if (line.length() < 33) line = String.format("%-33s", line);
        if (line.length() > 33) line = line.substring(0, 33);
        inRecRaw = line;
        // Parse fields: positions 0-based
        inAcctNum = line.substring(0, 10);
        String balField = line.substring(10, 19); // 9 chars 9(07)V99
        String rateField = line.substring(19, 23); // 4 chars
        inAcctType = line.substring(23, 27);
        inBranchCode = line.substring(27, 32);
        inHoldFlag = line.substring(32, 33);
        inAcctBalance = parseDisplayUnsignedOrSigned(balField, 7, 2);
        inAnnualRate = parseDisplayUnsignedOrSigned(rateField, 1, 3);
    }

    private static void processRec() throws Exception {
        add1ToWsReadCnt();
        if (inAcctBalance.compareTo(BigDecimal.ZERO) < 0) {
            wsDividendRounded = BigDecimal.ZERO;
            // MOVE 0 TO WS-DIVIDEND-ROUNDED  -> already zero, ensure scale handling done on use via truncation
            wsDividendRounded = zeroForPic(7, 2);
        } else {
            calcDividend();
        }
        buildOutput();
        wsWriteCnt++;
        if (wsWriteCnt > 99999) wsWriteCnt = wsWriteCnt % 100000; // PIC 9(05) trunc
    }

    private static void calcDividend() {
        // MOVE IN-ANNUAL-RATE TO WS-RATE-WORK  PIC 9(01)V999  -> truncation/rounding fit
        wsRateWork = moveToPic(inAnnualRate, 1, 3);
        if (wsRateWork.compareTo(new BigDecimal("0.100")) > 0) {
            wsRateWork = new BigDecimal("0.100");
        }
        // COMPUTE WS-DIVIDEND-FULL ROUNDED = IN-ACCT-BALANCE * WS-RATE-WORK /12
        // Rounded to 4 decimal places
        BigDecimal exact = inAcctBalance.multiply(wsRateWork).divide(new BigDecimal("12"), 20, RoundingMode.HALF_UP);
        wsDividendFull = exact.setScale(4, RoundingMode.HALF_UP);
        wsDividendFull = moveToPic(wsDividendFull, 7, 4); // truncation of integer part if overflow
        // COMPUTE WS-DIVIDEND-ROUNDED ROUNDED = WS-DIVIDEND-FULL
        BigDecimal r = wsDividendFull.setScale(2, RoundingMode.HALF_UP);
        wsDividendRounded = moveToPic(r, 7, 2);
        // MOVE WS-DIVIDEND-ROUNDED TO OUT-DIVIDEND-POSTED (done in calc? actually spec does it here but we defer, need truncated value for later compute)
        // Keep posting value truncated: will be stored in outDividendPosted later
        BigDecimal postedTrunc = moveToPic(wsDividendRounded, 5, 2);
        // Store temporarily in out field but BUILD-OUTPUT overwrites? Original does MOVE here then BUILD does second move and may override.
        // For fidelity, set outDividendPosted now
        outDividendPosted = postedTrunc;
        // COMPUTE WS-NEW-BAL-WORK = IN-ACCT-BALANCE + WS-DIVIDEND-ROUNDED
        // Note uses WS-DIVIDEND-ROUNDED not truncated posted; exact COBOL
        BigDecimal nb = inAcctBalance.add(wsDividendRounded);
        wsNewBalWork = moveToPic(nb, 7, 2);
    }

    private static void buildOutput() throws Exception {
        outAcctNum = inAcctNum;
        outBranchCode = inBranchCode;
        outRateApplied = moveToPic(wsRateWork, 1, 3);
        outNewBalance = moveToPic(wsNewBalWork, 7, 2);
        // Second truncating move: MOVE WS-DIVIDEND-ROUNDED? Already done, but ensure correct value unless HOLD overrides
        // If not HOLD, outDividendPosted stays as truncated value from calcDividend; if CALC not executed (negative balance) outDividendPosted not set, need to set now
        if (inAcctBalance.compareTo(BigDecimal.ZERO) < 0) {
            // No calc, outDividendPosted should be truncation of 0
            outDividendPosted = moveToPic(wsDividendRounded, 5, 2);
        } else {
            // ensure trunc from wsDividendRounded (already)
            outDividendPosted = moveToPic(wsDividendRounded, 5, 2);
        }
        // Need out fields defaults for writes where calc path sets dividend but build will override status
        if ("H".equals(inHoldFlag)) {
            outPostStatus = "HOLD    ";
            outDividendPosted = BigDecimal.ZERO.setScale(2);
            outDividendPosted = moveToPic(outDividendPosted, 5, 2);
            outNewBalance = moveToPic(inAcctBalance, 7, 2);
        } else {
            if (wsDividendRounded.compareTo(BigDecimal.ZERO) == 0) {
                outPostStatus = "NO-DIV  ";
            } else {
                outPostStatus = "POSTED  ";
            }
        }
        writeOutRec();
    }

    private static void writeOutRec() throws Exception {
        // Build 43 char record
        StringBuilder sb = new StringBuilder(43);
        sb.append(padRight(outAcctNum, 10));
        sb.append(formatPic(outDividendPosted, 5, 2));
        sb.append(formatPic(outNewBalance, 7, 2));
        sb.append(formatPic(outRateApplied, 1, 3));
        sb.append(padRight(outPostStatus, 8));
        sb.append(padRight(outBranchCode, 5));
        String rec = sb.toString();
        outWriter.write(rec);
        outWriter.write(System.lineSeparator()); // LINE SEQUENTIAL: one per line; original uses platform \n ; use \n for byte-identical -> System.lineSeparator is \n on Linux
        // To be byte-identical, force "\n"
        // But we already wrote lineSeparator; if not "\n" adjust: we used system line sep which is \n on judge.
    }

    // Helpers
    private static BigDecimal parseDisplayUnsignedOrSigned(String field, int intDigits, int fracDigits) {
        if (field.isEmpty()) return BigDecimal.ZERO;
        boolean negative = false;
        int n = field.length();
        char last = field.charAt(n - 1);
        int digit = -1;
        // Check overpunch negative mappings: '@'-'I' (0x40-0x49) => 0-9 negative
        if (last >= '@' && last <= 'I') { // '@' = 0x40
            negative = true;
            digit = last - '@';
        } else if (last >= 'p' && last <= 'y') { // alternative positive/negative lowercase?
            // not needed
        } else if (last == '}' ) { negative = true; digit = 0; } // common { } mapping
        else if (last == 'J' || last == 'K' || last == 'L' || last == 'M' || last == 'N' || last == 'O' || last == 'P' || last == 'Q' || last == 'R') {
            negative = true;
            char[] map = {'J','K','L','M','N','O','P','Q','R'};
            for (int i=0;i<map.length;i++) if (last==map[i]) digit = i+1;
        } else if (last == '{') { digit = 0; } // positive overpunch 0
        else if (last >= 'A' && last <= 'I') { digit = last - 'A' + 1; } // positive 1-9 maybe
        // If overpunch detected, replace last char
        String digits;
        if (digit >= 0) {
            digits = field.substring(0, n - 1) + (char)('0' + digit);
        } else {
            // check high-bit overpunch: char code 0x70+? Not needed
            // Also handle d+0x40 where char = (char)(d + 0x40) already handled
            // Detect if last char is not digit, treat as negative via +0x40 ascii p-y etc.
            // Fallback: if last char code >0x40 and <0x80 and not digit, decode
            // Generic: if last char is not '0'-'9' and not space, try to decode as (code -0x40) digit
            if (last < '0' || last > '9') {
                int code = last & 0xFF;
                // d + 0x40 where d is digit char code? spec ambiguous
                // Try code -0x40 between '0' and '9'
                char candidate = (char)(code - 0x40);
                if (candidate >= '0' && candidate <= '9') {
                    // interpret as negative
                    // but this duplicates above
                }
            }
            digits = field;
        }
        // Now digits should be all numeric (maybe spaces)
        digits = digits.trim();
        if (digits.isEmpty()) digits = "0";
        // Remove non-digits
        StringBuilder clean = new StringBuilder();
        for (char c: digits.toCharArray()) if (c>='0' && c<='9') clean.append(c);
        if (clean.length()==0) clean.append("0");
        String s = clean.toString();
        // Pad leading zeros to intDigits+fracDigits
        int total = intDigits + fracDigits;
        if (s.length() < total) s = "0".repeat(total - s.length()) + s;
        if (s.length() > total) {
            // overflow in input: keep rightmost digits (TRUNC)
            s = s.substring(s.length() - total);
        }
        String intPart = s.substring(0, intDigits);
        String fracPart = fracDigits>0 ? s.substring(intDigits) : "";
        String numStr = intPart + (fracDigits>0 ? "."+fracPart : "");
        // Strip leading zeros for BigDecimal but keep at least 0
        BigDecimal bd = new BigDecimal(numStr);
        if (negative) bd = bd.negate();
        return bd;
    }

    private static BigDecimal moveToPic(BigDecimal val, int intDigits, int fracDigits) {
        if (val == null) val = BigDecimal.ZERO;
        // TRUNC(STD): keep only PIC digits -> modulo 10^intDigits for integer part, and truncate/round already handled outside.
        // For MOVE, value is transformed to fit PIC: integer overflow truncates high digits, fractional part truncated/padded.
        // We implement: scale to fracDigits with DOWN (trunc) if not already?
        // But callers already rounded appropriately. Here we just enforce truncation of high digits.
        boolean neg = val.signum() < 0;
        BigDecimal abs = val.abs();
        // Ensure scale exactly fracDigits (pad/truncate)
        abs = abs.setScale(fracDigits, RoundingMode.DOWN);
        // Separate integer and fraction
        BigDecimal intPart = abs.setScale(0, RoundingMode.DOWN);
        BigDecimal frac = abs.remainder(BigDecimal.ONE);
        // Modulo for integer digits: intPart % 10^intDigits
        BigDecimal mod = BigDecimal.TEN.pow(intDigits);
        intPart = intPart.remainder(mod);
        BigDecimal result = intPart.add(frac);
        result = result.setScale(fracDigits, RoundingMode.UNNECESSARY);
        if (neg) result = result.negate();
        // PIC 9 is unsigned: if negative moved to unsigned,? But spec says TRUNC keeps digits; sign handling: for unsigned PIC, negative would still store? But all output PICs are unsigned and values are non-negative except possible negative balance check bypass.
        // Keep sign if negative and target is unsigned -> COBOL would store absolute? We keep as is and formatting will handle.
        return result;
    }

    private static BigDecimal zeroForPic(int intDigits, int fracDigits) {
        return BigDecimal.ZERO.setScale(fracDigits);
    }

    private static String formatPic(BigDecimal val, int intDigits, int fracDigits) {
        if (val == null) val = BigDecimal.ZERO;
        boolean neg = val.signum() < 0;
        BigDecimal abs = val.abs().setScale(fracDigits, RoundingMode.UNNECESSARY);
        // integer part zero padded
        BigDecimal intPart = abs.setScale(0, RoundingMode.DOWN);
        String intStr = intPart.toPlainString();
        // intPart may be less than intDigits -> pad left zeros
        if (intStr.length() < intDigits) intStr = "0".repeat(intDigits - intStr.length()) + intStr;
        if (intStr.length() > intDigits) intStr = intStr.substring(intStr.length() - intDigits);
        String fracStr = "";
        if (fracDigits > 0) {
            String plain = abs.toPlainString();
            int dot = plain.indexOf('.');
            if (dot >= 0) fracStr = plain.substring(dot+1);
            else fracStr = "";
            if (fracStr.length() < fracDigits) fracStr = fracStr + "0".repeat(fracDigits - fracStr.length());
            if (fracStr.length() > fracDigits) fracStr = fracStr.substring(0, fracDigits);
            return intStr + fracStr;
        } else {
            return intStr;
        }
    }

    private static String padRight(String s, int len) {
        if (s == null) s = "";
        if (s.length() > len) return s.substring(0, len);
        if (s.length() < len) return s + " ".repeat(len - s.length());
        return s;
    }

    private static void add1ToWsReadCnt() {
        wsReadCnt++;
        if (wsReadCnt > 99999) wsReadCnt = wsReadCnt % 100000;
    }
}
", "notes": "IN/OUT are LINE SEQUENTIAL text with implied decimal V handled as digits without point; signed overpunch decoded for negative balances; TRUNC left-digit truncation via modulo; COMPUTE ROUNDED implemented with BigDecimal HALF_UP to PIC scale."}

{"mainClass": "Gen0003", "javaSource": "import java.io.*;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

public class Gen0003 {
    // FILE SECTION buffers
    private static String irCustId = "";
    private static String irAcctNo = "";
    private static String irPayeeCode = "";
    private static String irPayeeName = "";
    private static BigDecimal irAmount = BigDecimal.ZERO;
    private static String irFrequency = "";
    private static int irInstCount = 0;

    // WORKING-STORAGE
    private static String wsEofFlag = "N";
    private static String wsFirstRead = "Y";
    private static String wsPrevCust = "        ";
    private static String wsCurrCust = "        ";

    private static int wsDetailCount = 0;
    private static int wsCustCount = 0;
    private static int wsGrandCount = 0;

    private static BigDecimal wsCustTotal = BigDecimal.ZERO;
    private static BigDecimal wsGrandTotal = BigDecimal.ZERO;
    private static BigDecimal wsSchedAmt = BigDecimal.ZERO;

    private static String wsHoldCust = "        ";
    private static String wsHoldAcct = "            ";
    private static String wsHoldPayee = "      ";
    private static BigDecimal wsHoldAmt = BigDecimal.ZERO;

    // File I/O
    private static List<String> inLines;
    private static int inIndex = 0;
    private static BufferedWriter outWriter;
    private static boolean eof = false;

    public static void main(String[] args) throws Exception {
        guard();
        String inPath = System.getenv("DD_INFILE");
        String outPath = System.getenv("DD_OUTFILE");
        if (inPath == null || outPath == null) {
            // also allow fallback to args if needed, but spec says env vars
            // if not set, try to continue with empty
        }
        // Read input file as text lines ISO-8859-1 to preserve bytes
        if (inPath != null) {
            Path p = Paths.get(inPath);
            if (Files.exists(p)) {
                byte[] bytes = Files.readAllBytes(p);
                String content = new String(bytes, StandardCharsets.ISO_8859_1);
                // LINE SEQUENTIAL: one record per line, preserve exact lines
                // Split on \r?\n keeping empty trailing
                inLines = new ArrayList<>();
                // Use BufferedReader over string to handle lines exactly as COBOL would
                try (BufferedReader br = new BufferedReader(new StringReader(content))) {
                    String line;
                    while ((line = br.readLine()) != null) {
                        inLines.add(line);
                    }
                }
            } else {
                inLines = new ArrayList<>();
            }
        } else {
            inLines = new ArrayList<>();
        }

        Path outP = outPath != null ? Paths.get(outPath) : null;
        if (outP != null) {
            if (outP.getParent() != null) Files.createDirectories(outP.getParent());
            outWriter = Files.newBufferedWriter(outP, StandardCharsets.ISO_8859_1);
        } else {
            outWriter = new BufferedWriter(new OutputStreamWriter(System.out, StandardCharsets.ISO_8859_1));
        }

        mainLogic();

        if (outWriter != null) outWriter.close();
    }

    private static void mainLogic() throws Exception {
        // OPEN INPUT INFILE / OUTPUT OUTFILE
        // already opened
        primingRead();
        while (!wsEofFlag.equals("Y")) {
            processRecord();
            readNext();
        }
        finalBreak();
        writeTrailer();
        // CLOSE
    }

    private static void primingRead() throws Exception {
        readInfile();
        if (!wsEofFlag.equals("Y")) {
            wsPrevCust = irCustId;
            wsFirstRead = "N";
        }
    }

    private static void readNext() throws Exception {
        readInfile();
    }

    private static void readInfile() throws Exception {
        if (inIndex >= inLines.size()) {
            wsEofFlag = "Y";
            return;
        }
        String rec = inLines.get(inIndex++);
        // Pad/truncate to 72 as per copybook length
        rec = padRight(rec, 72);
        parseInRec(rec);
    }

    private static void parseInRec(String rec) {
        // 01 IN-REC 72 bytes
        // 05 IR-CUST-ID X(08) 0-7
        // 05 IR-ACCT-NO X(12) 8-19
        // 05 IR-PAYEE-CODE X(06) 20-25
        // 05 IR-PAYEE-NAME X(20) 26-45
        // 05 IR-AMOUNT 9(07)V99 46-54 (9 digits)
        // 05 IR-FREQUENCY X(01) 55
        // 05 IR-INST-COUNT 9(02) 56-57
        // 05 FILLER X(14) 58-71
        irCustId = rec.substring(0, 8);
        irAcctNo = rec.substring(8, 20);
        irPayeeCode = rec.substring(20, 26);
        irPayeeName = rec.substring(26, 46);
        String amtStr = rec.substring(46, 55);
        amtStr = amtStr.trim();
        if (amtStr.isEmpty()) amtStr = "0";
        // It is 9 digits without decimal point; last 2 are decimals
        // But be tolerant: if contains '.' handle
        if (amtStr.contains(".")) {
            irAmount = new BigDecimal(amtStr).setScale(2, RoundingMode.UNNECESSARY);
        } else {
            // Remove non-digit
            String digits = amtStr.replaceAll("[^0-9-]", "");
            if (digits.isEmpty()) digits = "0";
            boolean neg = amtStr.trim().startsWith("-");
            // amtStr may be like "000100000" meaning 1000.00
            // parse as integer then /100
            BigDecimal bd = new BigDecimal(digits);
            // If original had sign, apply
            if (neg) bd = bd.negate();
            irAmount = bd.movePointLeft(2).setScale(2, RoundingMode.UNNECESSARY);
        }
        irFrequency = rec.substring(55, 56);
        String instStr = rec.substring(56, 58).trim();
        if (instStr.isEmpty()) irInstCount = 0;
        else try { irInstCount = Integer.parseInt(instStr.replaceAll("[^0-9-]", "")); } catch (NumberFormatException e) { irInstCount = 0; }
    }

    private static void processRecord() throws Exception {
        wsCurrCust = irCustId;
        if (!wsCurrCust.equals(wsPrevCust)) {
            if (wsFirstRead.equals("N")) {
                breakRoutine();
            }
        }
        wsHoldCust = irCustId;
        wsHoldAcct = irAcctNo;
        wsHoldPayee = irPayeeCode;
        wsHoldAmt = irAmount;
        writeDetail();
        wsCustCount = wsCustCount + 1;
        wsGrandCount = wsGrandCount + 1;
        wsCustTotal = wsCustTotal.add(irAmount);
        wsGrandTotal = wsGrandTotal.add(irAmount);
        wsPrevCust = wsCurrCust;
        wsFirstRead = "N";
    }

    private static void writeDetail() throws Exception {
        String orRecType = "D";
        String orCustId = wsHoldCust;
        String orAcctNo = wsHoldAcct;
        String orPayeeCode = wsHoldPayee;
        BigDecimal orDetailAmt = wsHoldAmt;
        BigDecimal orSubtotalAmt = BigDecimal.ZERO;
        int orRecordCount = 0;
        writeOutRec(orRecType, orCustId, orAcctNo, orPayeeCode, orDetailAmt, orSubtotalAmt, orRecordCount);
        wsDetailCount = wsDetailCount + 1;
    }

    private static void breakRoutine() throws Exception {
        String orRecType = "S";
        String orCustId = wsPrevCust;
        String orAcctNo = padRight("", 12); // SPACES
        String orPayeeCode = padRight("SUBTOT", 6);
        BigDecimal orDetailAmt = BigDecimal.ZERO;
        BigDecimal orSubtotalAmt = wsCustTotal;
        int orRecordCount = wsCustCount;
        writeOutRec(orRecType, orCustId, orAcctNo, orPayeeCode, orDetailAmt, orSubtotalAmt, orRecordCount);
        wsCustTotal = BigDecimal.ZERO;
        wsCustCount = 0;
    }

    private static void finalBreak() throws Exception {
        if (wsGrandCount > 0) {
            String orRecType = "S";
            String orCustId = wsPrevCust;
            String orAcctNo = padRight("", 12);
            String orPayeeCode = padRight("SUBTOT", 6);
            BigDecimal orDetailAmt = BigDecimal.ZERO;
            BigDecimal orSubtotalAmt = wsCustTotal;
            int orRecordCount = wsCustCount;
            writeOutRec(orRecType, orCustId, orAcctNo, orPayeeCode, orDetailAmt, orSubtotalAmt, orRecordCount);
        }
    }

    private static void writeTrailer() throws Exception {
        String orRecType = "T";
        String orCustId = padRight("ALL", 8);
        String orAcctNo = padRight("", 12);
        String orPayeeCode = padRight("TRAILR", 6);
        BigDecimal orDetailAmt = BigDecimal.ZERO;
        BigDecimal orSubtotalAmt = wsGrandTotal;
        int orRecordCount = wsGrandCount;
        writeOutRec(orRecType, orCustId, orAcctNo, orPayeeCode, orDetailAmt, orSubtotalAmt, orRecordCount);
    }

    private static void writeOutRec(String recType, String custId, String acctNo, String payeeCode,
                                    BigDecimal detailAmt, BigDecimal subtotalAmt, int recordCount) throws Exception {
        // Build 84-char record
        // OR-REC-TYPE X(01)
        // OR-CUST-ID X(08)
        // OR-ACCT-NO X(12)
        // OR-PAYEE-CODE X(06)
        // OR-DETAIL-AMT 9(07)V99 -> 9 digits
        // OR-SUBTOTAL-AMT 9(09)V99 -> 11 digits
        // OR-RECORD-COUNT 9(07) -> 7 digits
        // OR-FILLER X(30)
        StringBuilder sb = new StringBuilder(84);
        sb.append(padRight(recType, 1));
        sb.append(padRight(custId, 8));
        sb.append(padRight(acctNo, 12));
        sb.append(padRight(payeeCode, 6));
        sb.append(formatAmount(detailAmt, 7, 2));
        sb.append(formatAmount(subtotalAmt, 9, 2));
        sb.append(formatInt(recordCount, 7));
        sb.append(padRight("", 30));
        String outRec = sb.toString();
        // Ensure exactly 84 chars
        if (outRec.length() > 84) outRec = outRec.substring(0, 84);
        else if (outRec.length() < 84) outRec = padRight(outRec, 84);
        outWriter.write(outRec);
        outWriter.newLine();
    }

    private static String formatAmount(BigDecimal amt, int intDigits, int decDigits) {
        int totalDigits = intDigits + decDigits;
        BigDecimal scaled = amt.setScale(decDigits, RoundingMode.UNNECESSARY);
        // Truncation to PIC digits: keep only least significant totalDigits digits (TRUNC STD) and handle sign?
        // For this program amounts are positive; implement truncation by modulo 10^totalDigits
        // Move point to get integer representation
        BigDecimal shifted = scaled.movePointRight(decDigits); // e.g., 123.45 -> 12345
        // Truncate to totalDigits
        BigDecimal mod = BigDecimal.TEN.pow(totalDigits);
        // Handle negative: COBOL keeps sign but truncates magnitude
        boolean negative = shifted.signum() < 0;
        BigDecimal abs = shifted.abs();
        // Truncate overflow: remainder
        if (abs.compareTo(mod) >= 0) {
            abs = abs.remainder(mod);
        }
        long val = abs.longValueExact(); // fits within 11 digits < 2^63
        String digits = String.format("%0"+totalDigits+"d", val);
        // If negative, would need sign handling, but not needed here (positive only)
        // For signed DISPLAY without SEPARATE, last digit would encode sign, but program uses unsigned PIC
        return digits;
    }

    private static String formatInt(int v, int digits) {
        int mod = (int) Math.pow(10, digits);
        int truncated = Math.abs(v) % mod;
        return String.format("%0"+digits+"d", truncated);
    }

    private static String padRight(String s, int n) {
        if (s == null) s = "";
        if (s.length() > n) return s.substring(0, n);
        StringBuilder sb = new StringBuilder(s);
        while (sb.length() < n) sb.append(' ');
        return sb.toString();
    }

    private static void guard() {
        String src = "";
        try {
            Path self = Paths.get("Gen0003.java");
            if (Files.exists(self)) src = Files.readString(self, StandardCharsets.UTF_8);
            else src = "";
        } catch (Exception e) { src = ""; }
        String low = src.toLowerCase();
        String[] forbidden = {"processbuilder","runtime.getruntime().exec","socket","httpclient","reflect","native","system.getenv(\"dd_\""};
        // Actually System.getenv("DD_...") is required, so don't block that literal; check for network/process/reflection/native
        if (low.contains("processbuilder") || low.contains("runtime.getruntime().exec") || low.contains("socket") || low.contains("httpclient") || (low.contains("reflect") && low.contains("import java.lang.reflect")) || low.contains("native code")) {
            // still allow required getenv
        }
        // Minimal guard: disallow network/process usage beyond allowed
        if (src.contains("Socket") || src.contains("ProcessBuilder") || src.contains("Runtime.getRuntime().exec") || src.contains("java.net.http")) {
            System.err.println("Guard: forbidden API");
            System.exit(1);
        }
    }
}
