{"mainClass": "Gen0007", "javaSource": "import java.io.*;
import java.math.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

public class Gen0007 {
    private BufferedReader inReader;
    private BufferedWriter outWriter;

    private String wsEofFlag = "N";

    private BigDecimal wsVariance = BigDecimal.ZERO;
    private BigDecimal wsExpected = BigDecimal.ZERO;
    private int wsSpaceCnt = 0;
    private int wsAsteriskCnt = 0;
    private String wsCleanedNotes = "                              ";
    private String wsFirstTen = "          ";
    private String wsLastTen = "          ";
    private String wsStatusFlag = "        ";

    // Current input record fields
    private String tellerId;
    private String drawerId;
    private BigDecimal openingBalance;
    private BigDecimal closingCount;
    private BigDecimal transactionTotal;
    private String notesField;

    public static void main(String[] args) throws Exception {
        Gen0007 p = new Gen0007();
        p.run();
    }

    void run() throws Exception {
        String inPath = System.getenv("DD_INFILE");
        String outPath = System.getenv("DD_OUTFILE");
        if (inPath == null) inPath = "INFILE";
        if (outPath == null) outPath = "OUTFILE";
        // guard: no network/processes/reflection
        inReader = Files.newBufferedReader(Paths.get(inPath), StandardCharsets.ISO_8859_1);
        outWriter = Files.newBufferedWriter(Paths.get(outPath), StandardCharsets.ISO_8859_1);
        mainPara();
        inReader.close();
        outWriter.close();
    }

    private void mainPara() throws Exception {
        // OPEN INPUT IN-FILE OUTPUT OUT-FILE
        String line;
        String nextLine = inReader.readLine();
        // PERFORM UNTIL WS-EOF
        while (true) {
            if (nextLine == null) {
                wsEofFlag = "Y";
                break;
            } else {
                parseInRec(nextLine);
                processRec();
                nextLine = inReader.readLine();
            }
        }
    }

    private void parseInRec(String rec) {
        // Ensure length 66, pad with spaces if needed
        if (rec.length() < 66) rec = String.format("%-66s", rec);
        if (rec.length() > 66) rec = rec.substring(0, 66);
        tellerId = rec.substring(0, 5);
        drawerId = rec.substring(5, 9);
        String openingStr = rec.substring(9, 18); // 9 chars unsigned
        String closingStr = rec.substring(18, 27);
        String transStr = rec.substring(27, 36); // signed
        notesField = rec.substring(36, 66); // 30 chars
        openingBalance = parseUnsigned(openingStr, 2);
        closingCount = parseUnsigned(closingStr, 2);
        transactionTotal = parseSigned(transStr, 2);
    }

    private BigDecimal parseUnsigned(String s, int decimals) {
        // s contains digits 0-9, length = n+decimals? Actually 9 chars represent 9 digits with implied decimal
        // For unsigned, just digits.
        // If s contains spaces? treat as zero? But assume digits.
        String digits = s;
        // If any non-digit, try signed decode? For unsigned should be digits only.
        // Trim?
        // Remove any non-digit handling: if contains overpunch, decode anyway
        // Use signed decode logic to be safe: if last char is overpunch, decode
        char last = digits.charAt(digits.length() - 1);
        boolean negative = false;
        if (isOverpunch(last)) {
            int d = decodeOverpunch(last);
            digits = digits.substring(0, digits.length() - 1) + (char)('0' + d);
            negative = true; // shouldn't happen for unsigned but handle
        }
        BigDecimal bd = new BigDecimal(digits);
        bd = bd.movePointLeft(decimals);
        if (negative) bd = bd.negate();
        return bd;
    }

    private BigDecimal parseSigned(String s, int decimals) {
        if (s == null || s.isEmpty()) return BigDecimal.ZERO;
        char last = s.charAt(s.length() - 1);
        boolean negative = false;
        String digits = s;
        if (isOverpunch(last)) {
            int d = decodeOverpunch(last);
            digits = digits.substring(0, digits.length() - 1) + (char)('0' + d);
            negative = true;
        } else if (last == 'p' || last == 'q' || last == 'r' || last == 's' || last == 't' || last == 'u' || last == 'v' || last == 'w' || last == 'x' || last == 'y' // lowercase set
                || last == 'P' || last == 'Q' || last == 'R' || last == 'S' || last == 'T' || last == 'U' || last == 'V' || last == 'W' || last == 'X' || last == 'Y') {
            // already handled? isOverpunch checks lower case p-y
            int d = decodeOverpunch(last);
            digits = digits.substring(0, digits.length() - 1) + (char)('0' + d);
            negative = true;
        }
        // digits should be numeric, may contain spaces? unlikely
        digits = digits.trim();
        if (digits.isEmpty()) digits = "0";
        // Ensure digits are numeric, if contains non-digit, replace?
        BigDecimal bd = new BigDecimal(digits);
        bd = bd.movePointLeft(decimals);
        if (negative) bd = bd.negate();
        return bd;
    }

    private boolean isOverpunch(char c) {
        return (c >= 'p' && c <= 'y') || (c >= 'P' && c <= 'Y');
        // Also the spec says d+0x40: '0'(0x30)->'p'(0x70), so lower case p-y. Include upper for safety.
    }

    private int decodeOverpunch(char c) {
        if (c >= 'p' && c <= 'y') return c - 'p'; // p=0 ... y=9
        if (c >= 'P' && c <= 'Y') return c - 'P';
        // generic d+0x40: c - 0x40 - '0'
        return (c - 0x40) - '0';
    }

    private char encodeOverpunch(int digit) {
        // negative digit d written as character d + 0x40 where d is character '0'+digit
        // So '0'+digit +0x40 = digit + 0x70 = 'p'+digit
        return (char)('p' + digit);
    }

    private String formatSigned(BigDecimal value, int totalDigits, int decimals) {
        // PIC S9(07)V99 => totalDigits=9 (7+2), decimals=2, but 9 chars output (V not stored)
        // Need to handle TRUNC(STD): keep only PIC digits (truncate high order). For simplicity, apply modulo 10^totalDigits
        boolean negative = value.signum() < 0;
        BigDecimal abs = value.abs();
        // scale to handle decimals
        // Move point right by decimals to get integer representation
        BigDecimal scaled = abs.movePointRight(decimals);
        // Truncate to totalDigits (mod)
        // Use BigDecimal with truncation (floor)
        scaled = scaled.setScale(0, RoundingMode.DOWN);
        BigDecimal mod = BigDecimal.TEN.pow(totalDigits);
        scaled = scaled.remainder(mod); // keeps only low order digits
        // Now format as zero padded string of length totalDigits
        String s = scaled.toPlainString();
        // remove decimal part if any
        if (s.contains(".")) s = s.substring(0, s.indexOf('.'));
        s = String.format("%" + totalDigits + "s", s).replace(' ', '0');
        if (s.length() > totalDigits) s = s.substring(s.length() - totalDigits);
        if (negative) {
            int lastDigit = s.charAt(s.length() - 1) - '0';
            char enc = encodeOverpunch(lastDigit);
            s = s.substring(0, s.length() - 1) + enc;
        }
        return s;
    }

    private String formatUnsignedInt(int value, int len) {
        String s = Integer.toString(value);
        if (s.length() > len) s = s.substring(s.length() - len);
        return String.format("%" + len + "s", s).replace(' ', '0');
    }

    private void processRec() throws Exception {
        // MOVE SPACES TO WS-CLEANED-NOTES
        // MOVE NOTES-FIELD TO WS-CLEANED-NOTES
        wsCleanedNotes = padRight(notesField, 30);
        wsSpaceCnt = 0;
        wsAsteriskCnt = 0;
        // INSPECT WS-CLEANED-NOTES TALLYING ... REPLACING
        // Tally before replacing
        for (int i = 0; i < wsCleanedNotes.length(); i++) {
            char c = wsCleanedNotes.charAt(i);
            if (c == ' ') wsSpaceCnt++;
            if (c == '*') wsAsteriskCnt++;
        }
        // REPLACING ALL '*' BY '-'
        wsCleanedNotes = wsCleanedNotes.replace('*', '-');
        // REFERENCE MODIFICATION
        wsFirstTen = substringCobol(wsCleanedNotes, 1, 10);
        wsLastTen = substringCobol(wsCleanedNotes, 21, 10);
        if (charAtCobol(wsCleanedNotes, 1) == ' ') {
            // MOVE WS-CLEANED-NOTES(2:) TO WS-CLEANED-NOTES
            String src = substringCobol(wsCleanedNotes, 2, wsCleanedNotes.length() - 1); // from 2 to end
            wsCleanedNotes = padRight(src, 30);
        }
        char lastChar = charAtCobol(wsCleanedNotes, 30);
        if (lastChar == '-' || lastChar == '*') {
            // MOVE SPACES TO WS-CLEANED-NOTES(30:1)
            wsCleanedNotes = wsCleanedNotes.substring(0, 29) + " ";
        }
        // CALCULATE EXPECTED AND VARIANCE
        wsExpected = openingBalance.add(transactionTotal);
        // Simulate PIC S9(07)V99 truncation? TRUNC(STD) keeps only PIC digits
        wsExpected = truncToPic(wsExpected, 7, 2);
        wsVariance = closingCount.subtract(wsExpected);
        wsVariance = truncToPic(wsVariance, 7, 2);
        if (wsVariance.compareTo(BigDecimal.ZERO) == 0) {
            wsStatusFlag = "BALANCED";
        } else {
            if (wsVariance.compareTo(BigDecimal.ZERO) > 0) {
                wsStatusFlag = "OVERAGE ";
            } else {
                wsStatusFlag = "SHORTAGE";
            }
        }
        writeOut();
        if (wsAsteriskCnt > 0) {
            wsStatusFlag = "REVIEW  ";
            writeOut();
        }
    }

    private BigDecimal truncToPic(BigDecimal v, int intDigits, int decDigits) {
        // Keep only PIC digits: totalDigits = intDigits+decDigits
        // TRUNC(STD) low-order truncation. For magnitude, modulo 10^totalDigits /10^decDigits
        // Preserve sign
        boolean neg = v.signum() < 0;
        BigDecimal abs = v.abs();
        // Truncate (not round) to decDigits? Actually PIC has exactly decDigits, so we truncate extra decimals?
        // Use DOWN
        abs = abs.setScale(decDigits, RoundingMode.DOWN);
        BigDecimal scaled = abs.movePointRight(decDigits);
        BigDecimal mod = BigDecimal.TEN.pow(intDigits + decDigits);
        scaled = scaled.remainder(mod);
        BigDecimal result = scaled.movePointLeft(decDigits).setScale(decDigits, RoundingMode.UNNECESSARY);
        if (neg) result = result.negate();
        return result;
    }

    private void writeOut() throws Exception {
        String oTellerId = padRight(tellerId, 5);
        String oDrawerId = padRight(drawerId, 4);
        String oVariance = formatSigned(wsVariance, 9, 2);
        String oCleanedNotes = padRight(wsCleanedNotes, 30);
        String oStatusFlag = padRight(wsStatusFlag, 8);
        String oSpaceCount = formatUnsignedInt(wsSpaceCnt, 3);
        String outRec = oTellerId + oDrawerId + oVariance + oCleanedNotes + oStatusFlag + oSpaceCount;
        outWriter.write(outRec);
        outWriter.write(System.lineSeparator());
    }

    private String padRight(String s, int len) {
        if (s == null) s = "";
        if (s.length() > len) return s.substring(0, len);
        if (s.length() == len) return s;
        StringBuilder sb = new StringBuilder(s);
        while (sb.length() < len) sb.append(' ');
        return sb.toString();
    }

    private String substringCobol(String s, int startPos, int length) {
        // COBOL 1-indexed
        int startIdx = startPos - 1;
        if (startIdx >= s.length()) return padRight("", length);
        int endIdx = Math.min(s.length(), startIdx + length);
        String sub = s.substring(startIdx, endIdx);
        if (sub.length() < length) sub = padRight(sub, length);
        return sub;
    }

    private char charAtCobol(String s, int pos) {
        int idx = pos - 1;
        if (idx < 0 || idx >= s.length()) return ' ';
        return s.charAt(idx);
    }
}
