{"mainClass": "Gen0008", "javaSource": "import java.io.*;
import java.math.*;
import java.nio.charset.Charset;
import java.nio.file.*;
import java.util.*;

public class Gen0008 {
    static final Charset ISO = Charset.forName("ISO-8859-1");
    static BufferedReader in;
    static BufferedWriter out;

    // Working storage
    static boolean wsEof = false;
    static int wsReadCount = 0;
    static int wsWriteCount = 0;
    static BigDecimal wsNetPay = BigDecimal.ZERO;
    static BigDecimal wsPostedAmt = BigDecimal.ZERO;
    static String wsStatus = " ";

    // Current records - raw strings
    static String inRecordType;
    static String inRawData; // 39 chars
    // OUT fields
    static String outEmpId;
    static String outDeptCode;
    static String outPayPeriod; // 6 digits
    static String outDedCode;
    static String outGrossPayStr; // 9 digits
    static String outDedAmtStr; // signed 9
    static String outNetPayStr; // 9
    static String outRecordSrc;
    static String outStatusFlag;

    public static void main(String[] args) throws Exception {
        String inPath = System.getenv("DD_INFILE");
        String outPath = System.getenv("DD_OUTFILE");
        if (inPath == null || outPath == null) {
            System.err.println("DD env not set");
            System.exit(1);
        }
        in = Files.newBufferedReader(Paths.get(inPath), ISO);
        out = Files.newBufferedWriter(Paths.get(outPath), ISO, StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING);
        mainLogic();
        out.close();
        in.close();
    }

    static void mainLogic() throws Exception {
        // OPEN already done
        while (!wsEof) {
            String line = in.readLine();
            if (line == null) {
                wsEof = true;
            } else {
                // Ensure length 40: pad/truncate as COBOL LINE SEQUENTIAL - keep as is, pad with spaces
                if (line.length() < 40) line = String.format("%-40s", line);
                if (line.length() > 40) line = line.substring(0,40);
                inRecordType = line.substring(0,1);
                inRawData = line.substring(1,40); // 39 chars (actually 39, but line 40 -> 39 left)
                // line length 40 => substring(1) length 39 correct. If padded to 40, same.
                // However spec says IN-RAW-DATA X(39) so total 40. Good.
                wsReadCount++;
                processRecord();
            }
        }
        // CLOSE handled
    }

    static void processRecord() throws Exception {
        // MOVE SPACE TO PAYROLL-OUT-REC
        outEmpId = "      ";
        outDeptCode = "    ";
        outPayPeriod = "000000";
        outDedCode = "    ";
        outGrossPayStr = "000000000";
        outDedAmtStr = "000000000"; // positive signed display = digits
        outNetPayStr = "000000000";
        outRecordSrc = " ";
        outStatusFlag = " ";
        // EVALUATE
        if ("D".equals(inRecordType)) postDeduction();
        else if ("A".equals(inRecordType)) postAdjustment();
        else postErrorRecord();
    }

    // Helpers for DISPLAY numeric conversion
    static BigDecimal parseUnsigned(String s, int decimals) {
        // s is digits length n+decimals, e.g. 9 chars
        if (s==null) s="";
        s=s.trim();
        if (s.isEmpty()) return BigDecimal.ZERO;
        // s should be all digits; if contains overpunch not expected for unsigned
        String digits = s;
        // remove any non-digit? Assume digits
        BigDecimal v = new BigDecimal(new BigInteger(digits));
        return v.movePointLeft(decimals);
    }
    static BigDecimal parseSignedDisplay(String s, int decimals) {
        if (s==null||s.isEmpty()) return BigDecimal.ZERO;
        // last char may be overpunched for negative
        char last = s.charAt(s.length()-1);
        int sign = 1;
        String digits = s;
        if (last >= 'p' && last <= 'y') { // negative 0-9 as p-y per spec d+0x40
            sign = -1;
            int d = last - 'p'; // 0..9
            digits = s.substring(0, s.length()-1) + (char)('0'+d);
        } else if (last=='}' || (last>='J' && last<='R')) {
            // alternative EBCDIC mapping support for reading legacy files, treat as negative too
            sign=-1;
            int d;
            if (last=='}') d=0; else d= (last - 'J' +1);
            digits = s.substring(0, s.length()-1) + (char)('0'+d);
        } else {
            // positive digit stays
        }
        // digits should be numeric
        if (digits.isEmpty()) return BigDecimal.ZERO;
        // strip leading spaces
        digits=digits.trim();
        if (digits.isEmpty()) return BigDecimal.ZERO;
        BigDecimal v = new BigDecimal(new BigInteger(digits));
        v=v.movePointLeft(decimals);
        if (sign<0) v=v.negate();
        return v;
    }
    static String formatUnsigned(BigDecimal v, int totalDigits, int decimals) {
        // PIC 9(n)V99 => totalDigits = n+decimals, e.g. 9
        // truncate/overflow: keep only PIC digits (TRUNC STD) - take modulo 10^totalDigits
        // and display absolute value?
        BigDecimal scaled = v.setScale(decimals, RoundingMode.DOWN);
        // overflow handling: keep only last totalDigits digits
        BigInteger bi = scaled.movePointRight(decimals).toBigInteger(); // may be negative
        if (bi.signum()<0) bi=bi.negate(); // unsigned shows absolute? but callers move 0
        BigInteger mod = BigInteger.TEN.pow(totalDigits);
        bi = bi.mod(mod);
        String s = bi.toString();
        while (s.length()<totalDigits) s="0"+s;
        if (s.length()>totalDigits) s=s.substring(s.length()-totalDigits);
        return s;
    }
    static String formatSigned(BigDecimal v, int totalDigits, int decimals) {
        BigDecimal scaled = v.setScale(decimals, RoundingMode.DOWN);
        int sign = scaled.signum();
        BigInteger bi = scaled.movePointRight(decimals).toBigInteger().abs();
        BigInteger mod = BigInteger.TEN.pow(totalDigits);
        bi = bi.mod(mod);
        String s = bi.toString();
        while (s.length()<totalDigits) s="0"+s;
        if (s.length()>totalDigits) s=s.substring(s.length()-totalDigits);
        if (sign<0) {
            int lastDigit = s.charAt(s.length()-1)-'0';
            char over = (char)('p' + lastDigit); // spec d+0x40 => p-y
            s = s.substring(0,s.length()-1)+over;
        }
        return s;
    }

    // Copybook field extraction (DISPLAY)
    static String dedEmpId() { return substringRaw(0,6); }
    static String dedDeptCode() { return substringRaw(6,4); }
    static String dedCode() { return substringRaw(10,4); }
    static String dedGrossPayRaw() { return substringRaw(14,9); }
    static String dedAmountRaw() { return substringRaw(23,7); }
    static String dedPayPeriodRaw() { return substringRaw(30,6); }

    static String adjEmpId() { return substringRaw(0,6); }
    static String adjDeptCode() { return substringRaw(6,4); }
    static String adjReasonCode() { return substringRaw(10,4); }
    static String adjGrossPayRaw() { return substringRaw(14,9); }
    static String adjAdjustAmtRaw() { return substringRaw(23,7); }
    static String adjPayPeriodRaw() { return substringRaw(30,6); }

    static String substringRaw(int off, int len) {
        if (inRawData==null) return String.format("%"+len+"s","");
        if (off>=inRawData.length()) return String.format("%"+len+"s","");
        int end=Math.min(off+len,inRawData.length());
        String s=inRawData.substring(off,end);
        if (s.length()<len) s=String.format("%-"+len+"s",s);
        return s;
    }

    static void postDeduction() throws Exception {
        outEmpId = dedEmpId();
        outDeptCode = dedDeptCode();
        outPayPeriod = dedPayPeriodRaw();
        outDedCode = dedCode();
        outGrossPayStr = dedGrossPayRaw(); // MOVE DED-GROSS-PAY TO OUT-GROSS-PAY (both 9(7)V99)
        BigDecimal dedGross = parseUnsigned(dedGrossPayRaw(),2);
        BigDecimal dedAmt = parseUnsigned(dedAmountRaw(),2);
        wsPostedAmt = dedAmt;
        if (dedAmt.compareTo(dedGross) > 0) {
            wsStatus = "E";
            wsNetPay = BigDecimal.ZERO;
        } else {
            wsStatus = "P";
            wsNetPay = dedGross.subtract(dedAmt);
        }
        outDedAmtStr = formatSigned(wsPostedAmt,9,2);
        outNetPayStr = formatUnsigned(wsNetPay,9,2);
        outRecordSrc = "D";
        outStatusFlag = wsStatus;
        writePayrollOutRec();
        wsWriteCount++;
    }

    static void postAdjustment() throws Exception {
        outEmpId = adjEmpId();
        outDeptCode = adjDeptCode();
        outPayPeriod = adjPayPeriodRaw();
        outDedCode = adjReasonCode();
        outGrossPayStr = adjGrossPayRaw();
        BigDecimal adjGross = parseUnsigned(adjGrossPayRaw(),2);
        BigDecimal adjAmt = parseSignedDisplay(adjAdjustAmtRaw(),2);
        wsPostedAmt = adjAmt;
        outRecordSrc = "A";
        wsNetPay = adjGross.add(adjAmt);
        if (wsNetPay.compareTo(BigDecimal.ZERO) < 0) {
            wsNetPay = BigDecimal.ZERO;
            wsStatus = "E";
        } else {
            wsStatus = "P";
        }
        outDedAmtStr = formatSigned(wsPostedAmt,9,2);
        outNetPayStr = formatUnsigned(wsNetPay,9,2);
        outStatusFlag = wsStatus;
        writePayrollOutRec();
        wsWriteCount++;
        if (adjAmt.compareTo(BigDecimal.ZERO) < 0) {
            writeAuditTrail();
        }
    }

    static void writeAuditTrail() throws Exception {
        outRecordSrc = "R";
        outStatusFlag = "A";
        outDedCode = "REVK";
        writePayrollOutRec();
        wsWriteCount++;
    }

    static void postErrorRecord() throws Exception {
        outEmpId = "999999";
        outDeptCode = "    ";
        outPayPeriod = "000000";
        outDedCode = "ERR ";
        outGrossPayStr = "000000000";
        outDedAmtStr = formatSigned(BigDecimal.ZERO,9,2);
        outNetPayStr = "000000000";
        outRecordSrc = inRecordType;
        outStatusFlag = "E";
        writePayrollOutRec();
        wsWriteCount++;
    }

    static void writePayrollOutRec() throws Exception {
        // Fixed 54 bytes: 6+4+6+4+9+9+9+1+1+5 filler spaces
        String rec = outEmpId + outDeptCode + outPayPeriod + outDedCode + outGrossPayStr + outDedAmtStr + outNetPayStr + outRecordSrc + outStatusFlag + "     ";
        if (rec.length() < 54) rec = String.format("%-54s", rec);
        if (rec.length() > 54) rec = rec.substring(0,54);
        out.write(rec);
        out.write(System.lineSeparator());
    }
}
", "notes": "GEN0008: LINE SEQUENTIAL text IN/OUT (40->54 bytes per record, DISPLAY numerics implied 2 decimals, S9 fields use overpunch p-y for negative last digit); TRUNC handling via BigDecimal move semantics; audit trail duplicate write on negative ADJ-AMT."}

{"mainClass": "Gen0012", "javaSource": "import java.io.*;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

public class Gen0012 {
    private static BufferedReader inReader;
    private static BufferedWriter outWriter;

    private static String wsEofFlag = "N";
    private static int wsCtr = 0;
    private static int wsIdx = 0;
    private static String wsFoundFlag = "N";
    private static BigDecimal wsCalcAmt = BigDecimal.ZERO;
    private static BigDecimal wsRateToUse = BigDecimal.ZERO;
    private static String wsTableInitDone = "N";

    private static final String[] tbSizeCd = new String[11];
    private static final BigDecimal[] tbRate = new BigDecimal[11];
    private static final String[] tbDesc = new String[11];

    // current record fields
    private static String inBoxId;
    private static String inCustId;
    private static String inBoxSizeCd;
    private static int inMonthsDue;
    private static BigDecimal inMonthlyRate;
    private static String inStatusFlag;

    private static String outBoxId;
    private static String outCustId;
    private static BigDecimal outBillAmt;
    private static BigDecimal outRateUsed;
    private static String outBillDesc;
    private static String outFlagOut;

    public static void main(String[] args) throws Exception {
        String inPath = System.getenv("DD_INFILE");
        String outPath = System.getenv("DD_OUTFILE");
        // Fallbacks to allow local test (not used in evaluation)
        if (inPath == null) inPath = System.getenv("DD_INFILE");
        if (outPath == null) outPath = System.getenv("DD_OUTFILE");

        mainLogic(inPath, outPath);
    }

    private static void mainLogic(String inPath, String outPath) throws Exception {
        initTable();
        // OPEN INPUT IN-FILE / OUTPUT OUT-FILE
        Path ip = inPath != null ? Paths.get(inPath) : null;
        Path op = outPath != null ? Paths.get(outPath) : null;

        if (ip != null && Files.exists(ip)) {
            inReader = Files.newBufferedReader(ip, StandardCharsets.ISO_8859_1);
        } else {
            // if no file, treat as empty
            inReader = new BufferedReader(new StringReader(""));
        }
        if (op != null) {
            // ensure parent exists
            if (op.getParent() != null) Files.createDirectories(op.getParent());
            outWriter = Files.newBufferedWriter(op, StandardCharsets.ISO_8859_1);
        } else {
            outWriter = new BufferedWriter(new OutputStreamWriter(System.out, StandardCharsets.ISO_8859_1));
        }

        wsEofFlag = "N";
        while (!wsEofFlag.equals("Y")) {
            String line = inReader.readLine();
            if (line == null) {
                wsEofFlag = "Y";
            } else {
                parseInRec(line);
                processOne();
            }
        }
        inReader.close();
        outWriter.close();
    }

    private static void initTable() {
        wsTableInitDone = "N";
        // Initialize all to defaults
        for (int i=1;i<=10;i++){tbSizeCd[i]="";tbRate[i]=BigDecimal.ZERO;tbDesc[i]="";}
        tbSizeCd[1]="S1"; tbRate[1]=toRate(1500); tbDesc[1]=padRight("SMALL BOX",20);
        tbSizeCd[2]="S2"; tbRate[2]=toRate(2500); tbDesc[2]=padRight("MEDIUM SMALL",20);
        tbSizeCd[3]="M1"; tbRate[3]=toRate(3500); tbDesc[3]=padRight("MEDIUM BOX",20);
        tbSizeCd[4]="M2"; tbRate[4]=toRate(4500); tbDesc[4]=padRight("MEDIUM LARGE",20);
        tbSizeCd[5]="L1"; tbRate[5]=toRate(5500); tbDesc[5]=padRight("LARGE BOX",20);
        tbSizeCd[6]="L2"; tbRate[6]=toRate(7500); tbDesc[6]=padRight("EXTRA LARGE",20);
        tbSizeCd[7]="XL"; tbRate[7]=toRate(9500); tbDesc[7]=padRight("JUMBO BOX",20);
        tbSizeCd[8]="S0"; tbRate[8]=toRate(1000); tbDesc[8]=padRight("MINI BOX",20);
        tbSizeCd[9]="L0"; tbRate[9]=toRate(6000); tbDesc[9]=padRight("LARGE PLUS",20);
        tbSizeCd[10]="XX"; tbRate[10]=toRate(2000); tbDesc[10]=padRight("STANDARD BOX",20);
        wsTableInitDone="Y";
    }

    private static BigDecimal toRate(int moveVal){
        // MOVE 01500 to PIC 9(4)V99 => 01500 interpreted as 15.00 i.e. 1500/100
        // General: move integer literal n => BigDecimal n /100
        return BigDecimal.valueOf(moveVal).movePointLeft(2);
    }

    private static void processOne() throws Exception {
        wsCtr = wsCtr + 1;
        wsFoundFlag = "N";
        wsCalcAmt = BigDecimal.ZERO;
        wsRateToUse = BigDecimal.ZERO;
        for (wsIdx=1; wsIdx<=10; wsIdx++) {
            if (tbSizeCd[wsIdx].equals(inBoxSizeCd)) {
                wsRateToUse = tbRate[wsIdx];
                wsFoundFlag = "Y";
                outBillDesc = tbDesc[wsIdx];
                break;
            }
        }
        if (wsFoundFlag.equals("N")) {
            wsRateToUse = inMonthlyRate;
            outBillDesc = padRight("UNLISTED SIZE",20);
        }
        // COMPUTE WS-CALC-AMT = WS-RATE-TO-USE * IN-MONTHS-DUE
        wsCalcAmt = wsRateToUse.multiply(BigDecimal.valueOf(inMonthsDue));

        outBoxId = inBoxId;
        outCustId = inCustId;
        outBillAmt = wsCalcAmt;
        outRateUsed = wsRateToUse;
        outFlagOut = inStatusFlag;
        writeOutRec();
        if (inMonthsDue > 12) {
            outBillAmt = wsCalcAmt; // MOVE again (no change)
            outBillDesc = padRight("ANNUAL DISCOUNT NOTE",20);
            writeOutRec();
        }
    }

    private static void parseInRec(String line){
        // Record length 30: pad with spaces if short
        String rec = padRight(line,30);
        // If longer, truncate to 30 (keep first 30)
        if (rec.length()>30) rec = rec.substring(0,30);
        inBoxId = rec.substring(0,10);
        inCustId = rec.substring(10,18);
        inBoxSizeCd = rec.substring(18,20);
        String sMonths = rec.substring(20,23);
        String sRate = rec.substring(23,29);
        inStatusFlag = rec.substring(29,30);
        // parse numeric fields: if contains non-digit, treat as 0 where spaces
        inMonthsDue = parseIntDigits(sMonths, 3);
        inMonthlyRate = parsePic9V99(sRate, 4, 2);
    }

    private static int parseIntDigits(String s, int n){
        s=s.trim();
        if(s.isEmpty()) return 0;
        // keep digits, ignore sign? For this program unsigned
        StringBuilder sb=new StringBuilder();
        for(char c: s.toCharArray()) if(c>='0'&&c<='9') sb.append(c);
        if(sb.length()==0) return 0;
        try{return Integer.parseInt(sb.toString());}catch(Exception e){return 0;}
    }

    private static BigDecimal parsePic9V99(String s, int intDigits, int fracDigits){
        // s length intDigits+fracDigits digits, implied decimal
        // s may contain spaces; treat spaces as 0? COBOL would have digits.
        // We extract digits
        StringBuilder digits=new StringBuilder();
        for(char c: s.toCharArray()){
            if(c>='0'&&c<='9') digits.append(c);
            else if(c==' ' ) digits.append('0');
            // ignore others
        }
        // pad/truncate to required length
        int total=intDigits+fracDigits;
        while(digits.length()<total) digits.insert(0,"0");
        if(digits.length()>total) digits = new StringBuilder(digits.substring(digits.length()-total));
        BigDecimal bd = new BigDecimal(digits.toString());
        bd = bd.movePointLeft(fracDigits);
        return bd;
    }

    private static void writeOutRec() throws Exception {
        // Build 53-char line: X10 X8 9(6)V99 9(4)V99 X20 X1
        StringBuilder sb=new StringBuilder();
        sb.append(padRight(outBoxId,10).substring(0,10));
        sb.append(padRight(outCustId,8).substring(0,8));
        sb.append(formatPic9V99(outBillAmt,6,2));
        sb.append(formatPic9V99(outRateUsed,4,2));
        sb.append(padRight(outBillDesc,20).substring(0,20));
        String flag = outFlagOut==null?" ":outFlagOut;
        if(flag.length()>1) flag=flag.substring(0,1);
        if(flag.isEmpty()) flag=" ";
        sb.append(flag);
        outWriter.write(sb.toString());
        outWriter.newLine();
    }

    private static String formatPic9V99(BigDecimal val, int intDigits, int fracDigits){
        if(val==null) val=BigDecimal.ZERO;
        boolean negative = val.signum()<0;
        val = val.abs();
        // TRUNC(STD): keep only PIC digits -> truncated = val mod 10^intDigits (integer part) plus fractional
        // Equivalent to total digits modulo 10^(total)
        int total=intDigits+fracDigits;
        BigDecimal scaled = val.movePointRight(fracDigits); // integer representation
        // truncate to total digits: scaled mod 10^total
        BigDecimal mod = BigDecimal.TEN.pow(total);
        // Use remainder positive
        BigDecimal[] divRem = scaled.divideAndRemainder(mod);
        BigDecimal truncatedScaled = divRem[1];
        // handle negative? COBOL would preserve sign on stored but DISPLAY shows?
        // For this program all positive.
        // Format as zero-padded digits length total
        // BigDecimal remainder may have fractional part due to original having more decimals; we need to truncate (not round)
        truncatedScaled = truncatedScaled.setScale(0, java.math.RoundingMode.DOWN);
        String digits = truncatedScaled.toPlainString();
        // ensure no decimal point
        digits = digits.replace(".","");
        // pad left zeros
        while(digits.length()<total) digits = "0"+digits;
        if(digits.length()>total) digits = digits.substring(digits.length()-total);
        // negative handling would require sign overpunch, but not needed here
        return digits;
    }

    private static String padRight(String s,int len){
        if(s==null) s="";
        if(s.length()>=len) return s;
        StringBuilder sb=new StringBuilder(s);
        while(sb.length()<len) sb.append(' ');
        return sb.toString();
    }
}
