{"mainClass": "Gen0016", "javaSource": "import java.io.*;
import java.math.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

public class Gen0016 {
    public static void main(String[] args) throws Exception {
        String inPath = System.getenv("DD_INFILE");
        String outPath = System.getenv("DD_OUTFILE");
        if (inPath == null) inPath = System.getenv("DD_INFILE");
        if (outPath == null) outPath = System.getenv("DD_OUTFILE");
        Gen0016 p = new Gen0016();
        p.run(inPath, outPath);
    }

    // working storage
    boolean wsEof = false;
    int wsReadCnt = 0;
    int wsWriteCnt = 0;

    BigDecimal wsBalance = BigDecimal.ZERO;
    BigDecimal wsRate = BigDecimal.ZERO;
    BigDecimal wsBonus = BigDecimal.ZERO;
    BigDecimal wsDividend = BigDecimal.ZERO;
    BigDecimal wsNewBal = BigDecimal.ZERO;

    List<String> inLines;
    BufferedWriter outWriter;

    void run(String inPath, String outPath) throws Exception {
        mainPara(inPath, outPath);
    }

    void mainPara(String inPath, String outPath) throws Exception {
        // OPEN INPUT IN-FILE OUTPUT OUT-FILE
        List<String> lines = new ArrayList<>();
        if (inPath != null && !inPath.isEmpty()) {
            Path p = Paths.get(inPath);
            if (Files.exists(p)) {
                // LINE SEQUENTIAL: read as text ISO-8859-1, one record per line
                byte[] all = Files.readAllBytes(p);
                // Need to split on line separators \r\n, \n, \r
                // Use BufferedReader on ISO-8859-1
                try (BufferedReader br = Files.newBufferedReader(p, StandardCharsets.ISO_8859_1)) {
                    String line;
                    while ((line = br.readLine()) != null) {
                        lines.add(line);
                    }
                }
            }
        }
        inLines = lines;
        int readIdx = 0;

        Path outP = null;
        if (outPath != null && !outPath.isEmpty()) {
            outP = Paths.get(outPath);
            if (outP.getParent() != null) Files.createDirectories(outP.getParent());
        }
        // Open output writer ISO-8859-1, LINE SEQUENTIAL
        BufferedWriter bw = null;
        if (outP != null) {
            bw = Files.newBufferedWriter(outP, StandardCharsets.ISO_8859_1);
        } else {
            bw = null;
        }
        outWriter = bw;

        wsEof = false;
        // PERFORM UNTIL WS-EOF
        while (!wsEof) {
            if (readIdx >= inLines.size()) {
                wsEof = true;
            } else {
                String rec = inLines.get(readIdx++);
                wsReadCnt++;
                processRec(rec);
            }
        }
        if (outWriter != null) {
            outWriter.flush();
            outWriter.close();
        }
        // GOBACK -> exit 0
    }

    void processRec(String rawLine) throws Exception {
        wsDividend = BigDecimal.ZERO;
        wsNewBal = BigDecimal.ZERO;

        // Pad line to at least 31 with spaces if shorter
        String line = rawLine;
        if (line.length() < 31) {
            line = String.format("%-31s", line);
        }
        // IN-REC-TYPE is first char
        String inRecType = line.length() >= 1 ? line.substring(0,1) : " ";
        // IN-REC-BODY is next 30 chars (offset 1, len 30)
        String body = "";
        if (line.length() >= 1) {
            int end = Math.min(line.length(), 31);
            body = line.substring(1, end);
            if (body.length() < 30) body = String.format("%-30s", body);
        } else {
            body = String.format("%-30s", "");
        }

        String outAcctNo = "";
        String outRecType = inRecType;
        BigDecimal outPrevBal = BigDecimal.ZERO;
        BigDecimal outDividend = BigDecimal.ZERO;
        BigDecimal outNewBal = BigDecimal.ZERO;
        String outPostedFlag = "";

        if (inRecType.equals("A")) {
            // Type A mapping within body (30 bytes)
            String inAAcctNo = safeSubstring(body, 0, 8);
            String inABalanceStr = safeSubstring(body, 8, 9);
            String inARateStr = safeSubstring(body, 17, 4);
            // cust name not used
            wsBalance = parsePic9V99(inABalanceStr, 7, 2);
            wsRate = parsePic9V99(inARateStr, 2, 2);
            // COMPUTE WS-DIVIDEND = WS-BALANCE * WS-RATE / 100
            BigDecimal comp = wsBalance.multiply(wsRate).divide(BigDecimal.valueOf(100), 10, RoundingMode.HALF_UP);
            wsDividend = truncateToPic(comp, 7, 2);
            BigDecimal comp2 = wsBalance.add(wsDividend);
            wsNewBal = truncateToPic(comp2, 7, 2);

            outAcctNo = inAAcctNo;
            outPrevBal = wsBalance;
            outDividend = wsDividend;
            outNewBal = wsNewBal;
            outPostedFlag = "POST";
            writeOutRec(outAcctNo, outRecType, outPrevBal, outDividend, outNewBal, outPostedFlag);
        } else if (inRecType.equals("B")) {
            String inBAcctNo = safeSubstring(body, 0, 8);
            String inBBonusStr = safeSubstring(body, 8, 4);
            String inBBalanceStr = safeSubstring(body, 12, 9);
            String inBStatus = safeSubstring(body, 21, 9); // body only 30 so 21+9=30, but PIC X(10) -> we take available plus maybe extra char from line
            // If original line longer than 31, status may extend
            // Try to get full 10 chars if line length allows
            // body was truncated to 30 but actual status could be 10 chars requiring line length 32 (1+8+4+9+10=32)
            // So attempt to extract from original rawLine
            if (rawLine.length() >= 32) {
                // status starts at offset 1+8+4+9 =22 zero-based in full line
                int statusStart = 1 + 8 + 4 + 9;
                int statusEnd = statusStart + 10;
                if (rawLine.length() >= statusEnd) inBStatus = rawLine.substring(statusStart, statusEnd);
                else if (rawLine.length() > statusStart) {
                    inBStatus = rawLine.substring(statusStart);
                    inBStatus = String.format("%-10s", inBStatus);
                }
            } else {
                // pad to 10 for comparison
                inBStatus = String.format("%-10s", inBStatus);
            }

            wsBalance = parsePic9V99(inBBalanceStr, 7, 2);
            wsBonus = parsePic9V99(inBBonusStr, 2, 2);
            BigDecimal comp = wsBalance.multiply(wsBonus).divide(BigDecimal.valueOf(100), 10, RoundingMode.HALF_UP);
            wsDividend = truncateToPic(comp, 7, 2);
            BigDecimal comp2 = wsBalance.add(wsDividend);
            wsNewBal = truncateToPic(comp2, 7, 2);

            outAcctNo = inBAcctNo;
            outPrevBal = wsBalance;
            outDividend = wsDividend;
            outNewBal = wsNewBal;
            String trimmedStatus = inBStatus.trim();
            // Comparison: alphanumeric comparisons follow EBCDIC if env set? For equality "ACTIVE" ASCII==EBCDIC bytes same letters, so direct compare is fine
            // Use trimmed compare as COBOL would compare full 10-char field padded spaces: "ACTIVE    " equals "ACTIVE" trimmed? Better pad.
            String statusPadded = String.format("%-10s", trimmedStatus.isEmpty()?"":trimmedStatus);
            // COBOL IF IN-B-STATUS = "ACTIVE" : literal "ACTIVE" is 6 chars, but field is 10 chars; COBOL pads literal with spaces to field length
            // So we compare trimmed equality to ACTIVE
            if (trimmedStatus.equals("ACTIVE")) {
                outPostedFlag = "POST";
            } else {
                outPostedFlag = "HOLD";
            }
            writeOutRec(outAcctNo, outRecType, outPrevBal, outDividend, outNewBal, outPostedFlag);
        } else {
            // WHEN OTHER
            String inAAcctNo = safeSubstring(body, 0, 8);
            outAcctNo = inAAcctNo;
            outPrevBal = BigDecimal.ZERO;
            outDividend = BigDecimal.ZERO;
            outNewBal = BigDecimal.ZERO;
            outPostedFlag = "ERR ";
            writeOutRec(outAcctNo, outRecType, outPrevBal, outDividend, outNewBal, outPostedFlag);
        }
    }

    String safeSubstring(String s, int off, int len) {
        if (off >= s.length()) return String.format("%"+len+"s", "").replace(' ', ' ');
        int end = Math.min(s.length(), off+len);
        String sub = s.substring(off, end);
        if (sub.length() < len) sub = String.format("%-"+len+"s", sub);
        return sub;
    }

    BigDecimal parsePic9V99(String s, int intDigits, int decDigits) {
        // PIC 9(n)V99 stored as n+dec digits without decimal point, display as digits
        // s length should be intDigits+decDigits, may contain spaces? Treat spaces as 0? But per COBOL numeric DISPLAY, should be 0-9
        // Remove any non-digit? Interpret as 0
        String t = s;
        if (t == null) t = "";
        t = t.trim();
        // If field was spaces, treat as 0
        if (t.isEmpty()) return BigDecimal.ZERO.setScale(decDigits);
        // Keep only digits, but if contains sign? Not needed
        StringBuilder digits = new StringBuilder();
        for (char c: t.toCharArray()) if (Character.isDigit(c)) digits.append(c);
        // If original had fewer digits due to spaces, pad left with zeros to total length
        int total = intDigits+decDigits;
        String d = digits.toString();
        if (d.length() < total) {
            // left pad zeros
            d = "0".repeat(total - d.length()) + d;
        } else if (d.length() > total) {
            d = d.substring(d.length()-total);
        }
        BigDecimal bd = new BigDecimal(d);
        bd = bd.movePointLeft(decDigits);
        // Truncate to PIC digits (in case of overflow TRUNC(STD) keeps only low-order digits)
        // For input parsing we keep as is
        return bd;
    }

    BigDecimal truncateToPic(BigDecimal val, int intDigits, int decDigits) {
        // TRUNC(STD): keep only PIC digits, overflow truncated
        // First scale truncate (no rounding) to decDigits
        BigDecimal truncated = val.setScale(decDigits, RoundingMode.DOWN);
        // Check overflow: max = 10^intDigits - 10^-decDigits
        // If overflow, keep only low-order intDigits (mod 10^intDigits)
        BigDecimal intPart = truncated.setScale(0, RoundingMode.DOWN);
        // For negative not needed here (all positive)
        BigDecimal modulus = BigDecimal.TEN.pow(intDigits);
        // Handle overflow by modulo
        if (truncated.abs().compareTo(modulus) >= 0) {
            // keep low order digits: truncated mod 10^intDigits preserving decimal part
            // Example: 10000000.00 with 7 int digits -> 0000000.00
            BigDecimal sign = truncated.signum() >=0 ? BigDecimal.ONE : BigDecimal.ONE.negate();
            BigDecimal abs = truncated.abs();
            // split int and frac
            BigDecimal frac = abs.remainder(BigDecimal.ONE); // 0.xx
            BigDecimal intAbs = abs.setScale(0, RoundingMode.DOWN);
            BigDecimal intMod = intAbs.remainder(modulus);
            BigDecimal result = intMod.add(frac);
            if (sign.signum() <0) result = result.negate();
            result = result.setScale(decDigits, RoundingMode.DOWN);
            return result;
        }
        return truncated;
    }

    String formatPic9V99(BigDecimal val, int intDigits, int decDigits) {
        BigDecimal v = truncateToPic(val, intDigits, decDigits);
        v = v.setScale(decDigits, RoundingMode.DOWN);
        // Format as zero-padded digits without decimal point
        boolean negative = v.signum() <0;
        BigDecimal abs = v.abs();
        // Move point right decDigits to get integer digits
        BigDecimal scaled = abs.movePointRight(decDigits);
        // scaled should be integer
        String s = scaled.toPlainString();
        // Remove decimal if any (should not)
        if (s.contains(".")) s = s.substring(0, s.indexOf('.'));
        int total = intDigits+decDigits;
        if (s.length() < total) s = "0".repeat(total - s.length()) + s;
        else if (s.length() > total) s = s.substring(s.length()-total);
        // For signed DISPLAY without SEPARATE, negative would need last digit encoding, but here fields are unsigned 9(7)V99 so no sign
        return s;
    }

    void writeOutRec(String acctNo, String recType, BigDecimal prevBal, BigDecimal dividend, BigDecimal newBal, String postedFlag) throws Exception {
        String a = padRight(acctNo, 8);
        String t = recType != null && recType.length()>=1 ? recType.substring(0,1) : " ";
        String pb = formatPic9V99(prevBal, 7, 2);
        String dv = formatPic9V99(dividend, 7, 2);
        String nb = formatPic9V99(newBal, 7, 2);
        String pf = padRight(postedFlag, 4);
        String outRec = a + t + pb + dv + nb + pf;
        // OUT-REC length 40
        if (outWriter != null) {
            outWriter.write(outRec);
            outWriter.write(System.lineSeparator());
        }
        wsWriteCnt++;
    }

    String padRight(String s, int len) {
        if (s == null) s="";
        if (s.length() > len) return s.substring(0,len);
        if (s.length() < len) return s + " ".repeat(len - s.length());
        return s;
    }
}
