{"mainClass": "Gen0020", "javaSource": "import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.math.*;
import java.util.*;

public class Gen0020 {
    // Files
    private static BufferedReader inReader;
    private static BufferedWriter outWriter;

    // EOF flag
    private static boolean wsEof = false;

    // Working storage
    private static BigDecimal wsOdAmount = BigDecimal.ZERO;
    private static BigDecimal wsInterest = BigDecimal.ZERO;
    private static BigDecimal wsRate = BigDecimal.ZERO;
    private static BigDecimal wsDailyRate = BigDecimal.ZERO;
    private static String wsChargeCode = "    ";
    private static int wsI = 0;
    private static final int WS_TABLE_SIZE = 5;

    // Table
    private static final BigDecimal[] tMaxOd = new BigDecimal[6];
    private static final int[] tMaxDays = new int[6];
    private static final BigDecimal[] tRate = new BigDecimal[6];
    private static final String[] tCode = new String[6];

    // Current input record fields
    private static String inAccountNo;
    private static String inCustName;
    private static BigDecimal inBalance;
    private static BigDecimal inOdLimit;
    private static int inDaysOd;
    private static String inAcctType;

    // Lengths from copybooks (characters, LINE SEQUENTIAL text)
    // IN-REC: X10 + X20 + S9(7)V99(9) + 9(7)V99(9) + 9(3)(3) + X4 = 55
    private static final int IN_LEN = 55;
    // OUT-REC: X10+X20+S9(7)V99(9)+9(7)V99(9)+9(3)(3)+9(2)V999(5)+9(7)V99(9)+X4 = 69
    private static final int OUT_LEN = 69;

    public static void main(String[] args) throws Exception {
        String infile = System.getenv("DD_INFILE");
        String outfile = System.getenv("DD_OUTFILE");
        if (infile == null || outfile == null) {
            System.err.println("DD_INFILE / DD_OUTFILE not set");
            System.exit(1);
        }
        // Guard: no network/process/reflection/native - nothing to do

        initTable();

        Path inPath = Paths.get(infile);
        Path outPath = Paths.get(outfile);

        inReader = Files.newBufferedReader(inPath, StandardCharsets.ISO_8859_1);
        outWriter = Files.newBufferedWriter(outPath, StandardCharsets.ISO_8859_1);

        String line;
        // PERFORM UNTIL WS-EOF
        // COBOL READ loop: read first then process
        while (true) {
            line = inReader.readLine();
            if (line == null) {
                wsEof = true;
                break;
            }
            // If line shorter than expected, pad with spaces; if longer truncate
            if (line.length() < IN_LEN) line = String.format("%-" + IN_LEN + "s", line);
            parseInRec(line);
            processOne();
        }
        inReader.close();
        outWriter.close();
    }

    private static void initTable() {
        // MOVE literals to PIC 9(7)V99 etc. - exact values
        tMaxOd[1] = new BigDecimal("50000.00");
        tMaxDays[1] = 30;
        tRate[1] = new BigDecimal("0.015");
        tCode[1] = "OD01";
        tMaxOd[2] = new BigDecimal("200000.00");
        tMaxDays[2] = 30;
        tRate[2] = new BigDecimal("0.022");
        tCode[2] = "OD02";
        tMaxOd[3] = new BigDecimal("500000.00");
        tMaxDays[3] = 60;
        tRate[3] = new BigDecimal("0.035");
        tCode[3] = "OD03";
        tMaxOd[4] = new BigDecimal("9999999.00");
        tMaxDays[4] = 60;
        tRate[4] = new BigDecimal("0.048");
        tCode[4] = "OD04";
        tMaxOd[5] = new BigDecimal("9999999.00");
        tMaxDays[5] = 999;
        tRate[5] = new BigDecimal("0.065");
        tCode[5] = "OD05";
    }

    private static void parseInRec(String rec) {
        // Offsets 0-based
        inAccountNo = rec.substring(0, 10);
        inCustName = rec.substring(10, 30);
        String sBalance = rec.substring(30, 39); // 9 chars signed display
        String sOdLimit = rec.substring(39, 48); // 9 chars unsigned
        String sDays = rec.substring(48, 51);
        inAcctType = rec.substring(51, 55);
        inBalance = parseSignedDisplay(sBalance, 2);
        inOdLimit = parseUnsignedDisplay(sOdLimit, 2);
        inDaysOd = parseUnsignedInt(sDays);
    }

    private static void processOne() throws IOException {
        wsOdAmount = BigDecimal.ZERO;
        wsInterest = BigDecimal.ZERO;
        wsRate = BigDecimal.ZERO;
        wsChargeCode = "    ";
        if (inBalance.compareTo(BigDecimal.ZERO) < 0) {
            wsOdAmount = BigDecimal.ZERO.subtract(inBalance);
            wsOdAmount = quantize(wsOdAmount, 2);
        } else {
            wsOdAmount = BigDecimal.ZERO.setScale(2);
        }
        if (wsOdAmount.compareTo(BigDecimal.ZERO) == 0) {
            wsRate = BigDecimal.ZERO.setScale(3);
            wsChargeCode = "NOOD";
        } else {
            findRate();
        }
        if (wsOdAmount.compareTo(BigDecimal.ZERO) > 0 && inDaysOd > 0) {
            // COMPUTE WS-DAILY-RATE = WS-RATE / 365
            // PIC 9(2)V9999 => scale 4 truncated
            BigDecimal daily = wsRate.divide(new BigDecimal("365"), 10, RoundingMode.DOWN);
            wsDailyRate = trunc(daily, 4);
            // COMPUTE WS-INTEREST = WS-OD-AMOUNT * WS-DAILY-RATE * IN-DAYS-OD
            BigDecimal interestRaw = wsOdAmount.multiply(wsDailyRate).multiply(BigDecimal.valueOf(inDaysOd));
            wsInterest = trunc(interestRaw, 2);
        } else {
            wsInterest = BigDecimal.ZERO.setScale(2);
        }
        writeOut();
        if (wsInterest.compareTo(new BigDecimal("1000.00")) > 0) {
            writeFeeRec();
        }
    }

    private static void findRate() {
        // MOVE T-RATE(5) etc as default
        wsRate = tRate[5];
        wsChargeCode = tCode[5];
        for (wsI = 1; wsI <= WS_TABLE_SIZE; wsI++) {
            if (wsOdAmount.compareTo(tMaxOd[wsI]) <= 0 && inDaysOd <= tMaxDays[wsI]) {
                wsRate = tRate[wsI];
                wsChargeCode = tCode[wsI];
                break; // EXIT PERFORM
            }
        }
    }

    private static void writeOut() throws IOException {
        String outRec = buildOutRec(wsInterest, wsChargeCode);
        outWriter.write(outRec);
        outWriter.newLine();
    }

    private static void writeFeeRec() throws IOException {
        BigDecimal feeInterestRaw = wsInterest.add(new BigDecimal("25"));
        BigDecimal feeInterest = trunc(feeInterestRaw, 2);
        String outRec = buildOutRec(feeInterest, "FEES");
        outWriter.write(outRec);
        outWriter.newLine();
    }

    private static String buildOutRec(BigDecimal interestDue, String chargeCode) {
        StringBuilder sb = new StringBuilder(OUT_LEN);
        sb.append(padRight(inAccountNo, 10));
        sb.append(padRight(inCustName, 20));
        sb.append(formatSignedDisplay(inBalance, 7, 2));
        sb.append(formatUnsignedDisplay(wsOdAmount, 7, 2));
        sb.append(formatUnsignedInt(inDaysOd, 3));
        sb.append(formatUnsignedDisplay(wsRate, 2, 3));
        sb.append(formatUnsignedDisplay(interestDue, 7, 2));
        sb.append(padRight(chargeCode, 4));
        return sb.toString();
    }

    // Helpers for PIC DISPLAY handling
    private static BigDecimal parseUnsignedDisplay(String s, int scale) {
        s = s.trim();
        if (s.isEmpty()) return BigDecimal.ZERO.setScale(scale);
        // stored as zero-padded digits without decimal point
        // may contain spaces; remove
        String digits = s.replaceAll("[^0-9]", "");
        if (digits.isEmpty()) digits = "0";
        BigDecimal v = new BigDecimal(digits);
        v = v.movePointLeft(scale);
        return v.setScale(scale, RoundingMode.DOWN);
    }

    private static int parseUnsignedInt(String s) {
        s = s.trim();
        if (s.isEmpty()) return 0;
        String digits = s.replaceAll("[^0-9]", "");
        if (digits.isEmpty()) return 0;
        return Integer.parseInt(digits);
    }

    private static BigDecimal parseSignedDisplay(String s, int scale) {
        if (s == null || s.isEmpty()) return BigDecimal.ZERO.setScale(scale);
        // Last char may be overpunched: positive 0-9 as '0'-'9', negative as char code d+0x40
        // Also handle separate sign char? For now overpunch detection.
        char last = s.charAt(s.length() - 1);
        boolean negative = false;
        String digits = s;
        int lastDigit = -1;
        if (last >= 0x40 && last <= 0x49) { // unlikely in ISO-8859-1 text for GnuCOBOL? but per spec
            // Actually GnuCOBOL writes overpunch as special? We'll map
            // For ISO-8859-1, negative digits are typically '{','J'..'R' etc? But spec says d+0x40.
        }
        // Classic COBOL overpunch mapping for ASCII: positive {A-I for +1..+9? Need handle both.
        // We'll detect common GnuCOBOL -std=ibm display: uses { J-R for negative, A-I for positive overpunch? Or just char value.
        // Spec explicitly: negative digit d written as character d + 0x40. So e.g., '0' (0x30) negative 0 would be 0x70 'p'?
        // Let's implement that mapping plus fallback to standard EBCDIC overpunch mapping.
        if (last >= 'p' && last <= 'y') { // 0x70-0x79 => d+0x40 where d='0'..'9' (0x30)
            lastDigit = last - 0x40 - '0';
            negative = true;
            digits = s.substring(0, s.length() - 1) + (char)('0' + lastDigit);
        } else if (last == '{' || (last >= 'A' && last <= 'I')) {
            // Alternative GnuCOBOL mapping for -std=ibm signed DISPLAY: { for +0/-0 etc.
            // We'll decode: '{'=0+, 'A'-'I'=1-9+, '}'=0-, 'J'-'R'=1-9-
            if (last == '{') { lastDigit = 0; negative = false; }
            else if (last >= 'A' && last <= 'I') { lastDigit = last - 'A' + 1; negative = false; }
            digits = s.substring(0, s.length() - 1) + lastDigit;
        } else if (last == '}' || (last >= 'J' && last <= 'R')) {
            if (last == '}') lastDigit = 0; else lastDigit = last - 'J' + 1;
            negative = true;
            digits = s.substring(0, s.length() - 1) + lastDigit;
        } else if (last == '+' || last == '-') {
            // sign separate at end?
            negative = (last == '-');
            digits = s.substring(0, s.length() - 1);
        } else {
            // check raw 0x40 offset range: if char code between 0x40 and 0x49 ( '@'..'I' ) in ISO-8859-1, could be negative
            int code = last & 0xFF;
            if (code >= 0x70 && code <= 0x79) { // already handled p-y
            } else if (code >= 0x40 && code <= 0x49) {
                // '@' is negative 0? '@'=0x40 => d=0
                lastDigit = code - 0x40;
                negative = true;
                digits = s.substring(0, s.length() - 1) + lastDigit;
            }
        }
        // Now digits should be all numeric
        String clean = digits.replaceAll("[^0-9]", "");
        if (clean.isEmpty()) clean = "0";
        BigDecimal v = new BigDecimal(clean).movePointLeft(scale).setScale(scale, RoundingMode.DOWN);
        if (negative) v = v.negate();
        return v;
    }

    private static String formatUnsignedDisplay(BigDecimal val, int intDigits, int scale) {
        BigDecimal q = trunc(val.abs(), scale);
        String digits = q.movePointRight(scale).toPlainString().replaceAll("[^0-9]", "");
        // digits may contain leading zeros removed by BigDecimal; pad to intDigits+scale
        int total = intDigits + scale;
        digits = leftPadZeros(digits, total);
        if (digits.length() > total) digits = digits.substring(digits.length() - total);
        return digits;
    }

    private static String formatSignedDisplay(BigDecimal val, int intDigits, int scale) {
        boolean negative = val.signum() < 0;
        BigDecimal q = trunc(val.abs(), scale);
        int total = intDigits + scale;
        String digits = q.movePointRight(scale).toPlainString().replaceAll("[^0-9]", "");
        digits = leftPadZeros(digits, total);
        if (digits.length() > total) digits = digits.substring(digits.length() - total);
        if (!negative) {
            return digits;
        } else {
            // Overpunch last digit: d -> char(d + 0x40)
            int lastDigit = digits.charAt(digits.length() - 1) - '0';
            char over = (char)(lastDigit + '0' + 0x40);
            return digits.substring(0, digits.length() - 1) + over;
        }
    }

    private static String formatUnsignedInt(int val, int width) {
        String s = String.valueOf(val);
        s = leftPadZeros(s, width);
        if (s.length() > width) s = s.substring(s.length() - width);
        return s;
    }

    private static BigDecimal trunc(BigDecimal v, int scale) {
        return v.setScale(scale, RoundingMode.DOWN);
    }

    private static BigDecimal quantize(BigDecimal v, int scale) {
        return v.setScale(scale, RoundingMode.DOWN);
    }

    private static String leftPadZeros(String s, int len) {
        if (s.length() >= len) return s;
        StringBuilder b = new StringBuilder(len);
        for (int i = s.length(); i < len; i++) b.append('0');
        b.append(s);
        return b.toString();
    }

    private static String padRight(String s, int len) {
        if (s == null) s = "";
        if (s.length() > len) return s.substring(0, len);
        if (s.length() == len) return s;
        StringBuilder b = new StringBuilder(len);
        b.append(s);
        for (int i = s.length(); i < len; i++) b.append(' ');
        return b.toString();
    }
}
