{"mainClass": "Gen0027", "javaSource": "import java.io.*;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

public class Gen0027 {
    // IN record layout (LINE SEQUENTIAL, DISPLAY, V implies no char)
    private static final int IN_LEN = 44;
    private static final int IN_BRANCH_LEN = 4;
    private static final int IN_BOX_LEN = 6;
    private static final int IN_SIZE_LEN = 1;
    private static final int IN_FEE_LEN = 6; // 9(4)V99 -> 6 digits
    private static final int IN_MONTHS_LEN = 2; // 9(02)
    private static final int IN_LATE_LEN = 5; // 9(3)V99
    private static final int IN_NAME_LEN = 20;

    // OUT layout totals 56
    private static final int OUT_BRANCH_LEN = 4;
    private static final int OUT_TYPE_LEN = 1;
    private static final int OUT_BOX_LEN = 6;
    private static final int OUT_SIZE_LEN = 1;
    private static final int OUT_BILL_LEN = 8; // 9(6)V99
    private static final int OUT_BRANCH_TOT_LEN = 10; // 9(8)V99
    private static final int OUT_GRAND_TOT_LEN = 11; // 9(9)V99
    private static final int OUT_COUNT_LEN = 5;
    private static final int OUT_FILLER_LEN = 10;

    // Working-storage
    private String wsEofFlag = "N";
    private String wsPrevBranch = "    ";
    private String wsFirstRec = "Y";
    private BigDecimal wsBranchTotal = BigDecimal.ZERO.setScale(2);
    private int wsBranchCount = 0;
    private BigDecimal wsGrandTotal = BigDecimal.ZERO.setScale(2);
    private int wsGrandCount = 0;
    private BigDecimal wsCurrBill = BigDecimal.ZERO.setScale(2);

    private String wsHoldBranch = "    ";
    private String wsHoldBox = "      ";
    private String wsHoldSize = " ";
    private BigDecimal wsHoldFee = BigDecimal.ZERO.setScale(2);
    private int wsHoldMonths = 0;
    private BigDecimal wsHoldLate = BigDecimal.ZERO.setScale(2);
    private String wsHoldName = "                    ";

    private List<String> inLines;
    private int inIndex = 0;
    private BufferedWriter outWriter;
    private boolean ebcdicCollation = false;

    private boolean isWsEof() { return "Y".equals(wsEofFlag); }
    private boolean isWsIsFirst() { return "Y".equals(wsFirstRec); }
    private boolean isWsNotFirst() { return "N".equals(wsFirstRec); }

    public static void main(String[] args) throws Exception {
        Gen0027 p = new Gen0027();
        p.run();
    }

    private void run() throws Exception {
        String coll = System.getenv("DIOCLE_COLLATION");
        ebcdicCollation = "EBCDIC".equalsIgnoreCase(coll);

        String inPath = System.getenv("DD_INFILE");
        String outPath = System.getenv("DD_OUTFILE");
        if (inPath == null) inPath = System.getenv("DD_INFILE");
        if (outPath == null) outPath = System.getenv("DD_OUTFILE");

        // Read INFILE if exists, else empty
        inLines = new ArrayList<>();
        if (inPath != null) {
            Path p = Paths.get(inPath);
            if (Files.exists(p)) {
                // LINE SEQUENTIAL: one record per line, read as bytes ISO-8859-1
                // Preserve spaces; do not trim. Each line is a record.
                List<String> raw = Files.readAllLines(p, StandardCharsets.ISO_8859_1);
                inLines.addAll(raw);
            }
        }
        Path outP = outPath != null ? Paths.get(outPath) : null;
        if (outP != null) {
            // Ensure parent dirs
            if (outP.getParent() != null) Files.createDirectories(outP.getParent());
            outWriter = Files.newBufferedWriter(outP, StandardCharsets.ISO_8859_1,
                    StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING, StandardOpenOption.WRITE);
        } else {
            outWriter = new BufferedWriter(new OutputStreamWriter(System.out, StandardCharsets.ISO_8859_1));
        }

        mainLogic();

        outWriter.flush();
        outWriter.close();
    }

    // Paragraphs
    private void mainLogic() throws Exception {
        // OPEN INPUT IN-FILE OUTPUT OUT-FILE already handled
        readNext();
        while (!isWsEof()) {
            checkBreak();
            processDetail();
            readNext();
        }
        writeFinalSubtotal();
        writeTrailer();
        // CLOSE handled in run()
    }

    private void readNext() {
        if (inIndex >= inLines.size()) {
            wsEofFlag = "Y";
            return;
        }
        String rec = inLines.get(inIndex++);
        // Pad/truncate to IN_LEN with spaces
        rec = padRight(rec, IN_LEN);
        int pos = 0;
        String inBranchId = rec.substring(pos, pos + IN_BRANCH_LEN); pos += IN_BRANCH_LEN;
        String inBoxNumber = rec.substring(pos, pos + IN_BOX_LEN); pos += IN_BOX_LEN;
        String inBoxSizeType = rec.substring(pos, pos + IN_SIZE_LEN); pos += IN_SIZE_LEN;
        String inMonthlyFeeStr = rec.substring(pos, pos + IN_FEE_LEN); pos += IN_FEE_LEN;
        String inRentalMonthsStr = rec.substring(pos, pos + IN_MONTHS_LEN); pos += IN_MONTHS_LEN;
        String inLateFeeStr = rec.substring(pos, pos + IN_LATE_LEN); pos += IN_LATE_LEN;
        String inCustomerName = rec.substring(pos, pos + IN_NAME_LEN); pos += IN_NAME_LEN;

        wsHoldBranch = inBranchId;
        wsHoldBox = inBoxNumber;
        wsHoldSize = inBoxSizeType;
        wsHoldFee = parseImplied(inMonthlyFeeStr, 2);
        wsHoldMonths = parseUnsignedInt(inRentalMonthsStr);
        wsHoldLate = parseImplied(inLateFeeStr, 2);
        wsHoldName = inCustomerName;
    }

    private void checkBreak() throws Exception {
        if (isWsIsFirst()) {
            wsPrevBranch = wsHoldBranch;
            wsFirstRec = "N";
        } else {
            if (!equalsCollation(wsHoldBranch, wsPrevBranch)) {
                writeSubtotal();
                wsPrevBranch = wsHoldBranch;
            }
        }
    }

    private void processDetail() throws Exception {
        // COMPUTE WS-CURR-BILL = WS-HOLD-FEE * WS-HOLD-MONTHS + WS-HOLD-LATE
        // COBOL semantics with BigDecimal exact
        BigDecimal months = BigDecimal.valueOf(wsHoldMonths);
        wsCurrBill = wsHoldFee.multiply(months).add(wsHoldLate);
        wsCurrBill = wsCurrBill.setScale(2, RoundingMode.UNNECESSARY);

        wsBranchTotal = wsBranchTotal.add(wsCurrBill);
        wsBranchCount += 1;
        wsGrandTotal = wsGrandTotal.add(wsCurrBill);
        wsGrandCount += 1;

        String outBranchId = wsHoldBranch;
        String outRecordType = "D";
        String outBoxNumber = wsHoldBox;
        String outBoxSizeType = wsHoldSize;
        BigDecimal outBillAmount = wsCurrBill;
        BigDecimal outBranchTotal = wsBranchTotal;
        BigDecimal outGrandTotal = wsGrandTotal;
        int outRecCount = wsBranchCount;
        String outFiller = padRight("", OUT_FILLER_LEN);

        writeOutRec(outBranchId, outRecordType, outBoxNumber, outBoxSizeType, outBillAmount, outBranchTotal, outGrandTotal, outRecCount, outFiller);
    }

    private void writeSubtotal() throws Exception {
        String outBranchId = wsPrevBranch;
        String outRecordType = "S";
        String outBoxNumber = padRight("", OUT_BOX_LEN);
        String outBoxSizeType = " ";
        BigDecimal outBillAmount = BigDecimal.ZERO.setScale(2);
        BigDecimal outBranchTotal = wsBranchTotal;
        BigDecimal outGrandTotal = wsGrandTotal;
        int outRecCount = wsBranchCount;
        String outFiller = padRight("SUBTOTAL  ", OUT_FILLER_LEN);

        writeOutRec(outBranchId, outRecordType, outBoxNumber, outBoxSizeType, outBillAmount, outBranchTotal, outGrandTotal, outRecCount, outFiller);
        wsBranchTotal = BigDecimal.ZERO.setScale(2);
        wsBranchCount = 0;
    }

    private void writeFinalSubtotal() throws Exception {
        if (isWsNotFirst()) {
            writeSubtotal();
        }
    }

    private void writeTrailer() throws Exception {
        String outBranchId = padRight("", OUT_BRANCH_LEN);
        String outRecordType = "T";
        String outBoxNumber = padRight("", OUT_BOX_LEN);
        String outBoxSizeType = " ";
        BigDecimal outBillAmount = BigDecimal.ZERO.setScale(2);
        BigDecimal outBranchTotal = BigDecimal.ZERO.setScale(2);
        BigDecimal outGrandTotal = wsGrandTotal;
        int outRecCount = wsGrandCount;
        String outFiller = padRight("TRAILER   ", OUT_FILLER_LEN);
        writeOutRec(outBranchId, outRecordType, outBoxNumber, outBoxSizeType, outBillAmount, outBranchTotal, outGrandTotal, outRecCount, outFiller);
    }

    private void writeOutRec(String branchId, String recType, String boxNum, String sizeType,
                             BigDecimal billAmt, BigDecimal branchTot, BigDecimal grandTot,
                             int recCount, String filler) throws Exception {
        // Build fixed width line 56 chars: DISPLAY numeric fields are zero-padded digits with implied decimal
        String bId = padRight(branchId, OUT_BRANCH_LEN);
        String rType = padRight(recType, OUT_TYPE_LEN);
        String bNum = padRight(boxNum, OUT_BOX_LEN);
        String sType = padRight(sizeType, OUT_SIZE_LEN);
        String billStr = formatImplied(billAmt, 8, 2); // 9(6)V99 -> 8 digits
        String branchStr = formatImplied(branchTot, 10, 2);
        String grandStr = formatImplied(grandTot, 11, 2);
        String countStr = formatInteger(recCount, OUT_COUNT_LEN);
        String fill = padRight(filler, OUT_FILLER_LEN);
        String line = bId + rType + bNum + sType + billStr + branchStr + grandStr + countStr + fill;
        outWriter.write(line);
        outWriter.newLine();
    }

    // Helpers
    private static String padRight(String s, int len) {
        if (s == null) s = "";
        if (s.length() > len) return s.substring(0, len);
        if (s.length() == len) return s;
        StringBuilder sb = new StringBuilder(s);
        while (sb.length() < len) sb.append(' ');
        return sb.toString();
    }

    private static BigDecimal parseImplied(String s, int scale) {
        s = s.trim();
        if (s.isEmpty()) return BigDecimal.ZERO.setScale(scale);
        // s should be digits, possibly with sign? For DISPLAY unsigned, just digits. Handle spaces.
        // Keep only digits and minus
        String t = s.replaceAll("[^0-9-]", "");
        if (t.isEmpty() || t.equals("-")) return BigDecimal.ZERO.setScale(scale);
        boolean neg = t.startsWith("-");
        if (neg) t = t.substring(1);
        t = t.replaceAll("^0+", "");
        if (t.isEmpty()) t = "0";
        BigDecimal v = new BigDecimal(t);
        if (neg) v = v.negate();
        v = v.movePointLeft(scale);
        v = v.setScale(scale, RoundingMode.UNNECESSARY);
        return v;
    }

    private static int parseUnsignedInt(String s) {
        s = s.trim();
        if (s.isEmpty()) return 0;
        s = s.replaceAll("[^0-9]", "");
        if (s.isEmpty()) return 0;
        try { return Integer.parseInt(s); } catch (NumberFormatException e) { return 0; }
    }

    private static String formatImplied(BigDecimal v, int totalDigits, int scale) {
        // PIC 9(n)V99 style: totalDigits = n+scale, zero padded, no decimal point, truncate/overflow as TRUNC(STD) keep only PIC digits
        // For positive values only in this program, but handle sign by keeping digits
        v = v.setScale(scale, RoundingMode.UNNECESSARY);
        BigDecimal scaled = v.movePointRight(scale); // integer representation
        // Truncate to PIC digits (keep least significant digits) emulating overflow truncation
        // Use absolute value digits? DISPLAY of negative would have sign overpunch - not needed here.
        boolean neg = scaled.signum() < 0;
        scaled = scaled.abs();
        String digits = scaled.toPlainString().replaceAll("[^0-9]", "");
        // Remove decimal if any (should not)
        if (digits.length() > totalDigits) {
            digits = digits.substring(digits.length() - totalDigits);
        }
        digits = String.format("%" + totalDigits + "s", digits).replace(' ', '0');
        // For negative, COBOL would show sign overpunch, but not needed for these PICs (unsigned)
        if (neg) {
            // Not expected; fallback to zero-padded with minus not used. Just return digits.
        }
        return digits;
    }

    private static String formatInteger(int v, int len) {
        String s = Integer.toString(v);
        if (s.length() > len) s = s.substring(s.length() - len);
        return String.format("%" + len + "s", s).replace(' ', '0');
    }

    private boolean equalsCollation(String a, String b) {
        if (!ebcdicCollation) return a.equals(b);
        return toEbcdicBytes(a).equals(toEbcdicBytes(b));
    }

    private static String toEbcdicBytes(String s) {
        try {
            byte[] b = s.getBytes("Cp037");
            return new String(b, StandardCharsets.ISO_8859_1);
        } catch (Exception e) { return s; }
    }
}
