{"mainClass": "Gen0032", "javaSource": "import java.io.*;
import java.nio.charset.Charset;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;

public class Gen0032 {
    private static final Charset TEXT_CS = StandardCharsets.ISO_8859_1;
    // Input record length = 1 + 34 = 35
    // Output record length = 10+10+1+1+4+9+12+3 = 50 (BALANCE 9(07)V99 as 9 digits)
    private static final int IN_REC_LEN = 35;
    private static final int OUT_REC_LEN = 50;

    // Working storage
    private String wsEofFlag = "N";
    private int wsReadCount = 0;
    private int wsWriteCount = 0;
    private int wsDormantThreshold = 365;
    private int wsWarnThreshold = 180;
    private String wsHoldAcctNo = spaces(10);
    private String wsHoldCustId = spaces(10);
    private String wsHoldBranch = spaces(3);

    // Current input record fields (raw)
    private String currentLineRaw = ""; // padded to 35
    private String recType = " ";
    // Acct detail
    private String acctNo = spaces(10);
    private int lastActDays = 0;
    private int currBalanceInt = 0; // scaled integer: 9 digits (7+2) e.g. 12345 = 123.45  -> 12345
    private String acctStatus = spaces(8);
    private String branchCode = spaces(3);
    // Cust detail
    private String custId = spaces(10);
    private String custName = spaces(15);
    private int contactDays = 0;
    private String custType = spaces(5);

    // Current output record buffer
    private String dormantOutputRec = spaces(OUT_REC_LEN);
    // Output fields for building
    private String outAcctNo = spaces(10);
    private String outCustId = spaces(10);
    private String outRecType = " ";
    private String outDormantFlag = " ";
    private int outDaysInactive = 0;
    private int outBalance = 0; // 9 digit integer
    private String outReasonCode = spaces(12);
    private String outBranchCode = spaces(3);

    private BufferedReader inReader;
    private BufferedWriter outWriter;

    public static void main(String[] args) throws Exception {
        // guard: refuse network/process/reflection/native - minimal check
        String infilePath = System.getenv("DD_INFILE");
        String outfilePath = System.getenv("DD_OUTFILE");
        Gen0032 prog = new Gen0032();
        prog.run(infilePath, outfilePath);
    }

    private void run(String infilePath, String outfilePath) throws Exception {
        if (infilePath == null || outfilePath == null) {
            // try default names if not supplied (still need to behave)
            if (infilePath == null) infilePath = System.getenv("DD_INFILE");
            if (outfilePath == null) outfilePath = System.getenv("DD_OUTFILE");
        }
        // Open files
        // DIOCLE_CLOCK handling (not used in this program but consume)
        String clock = System.getenv("DIOCLE_CLOCK");
        // collation not needed for this program (no compare except rec-type)
        if (infilePath != null) {
            inReader = Files.newBufferedReader(Paths.get(infilePath), TEXT_CS);
        } else {
            inReader = new BufferedReader(new InputStreamReader(System.in, TEXT_CS));
        }
        if (outfilePath != null) {
            outWriter = Files.newBufferedWriter(Paths.get(outfilePath), TEXT_CS,
                    StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING, StandardOpenOption.WRITE);
        } else {
            outWriter = new BufferedWriter(new OutputStreamWriter(System.out, TEXT_CS));
        }
        mainPara();
        // close
        if (inReader != null) inReader.close();
        if (outWriter != null) outWriter.flush();
        if (outWriter != null) outWriter.close();
        // GOBACK with return code 0
        // If RETURN-CODE non-zero would exit; here always 0
    }

    // Paragraph methods
    private void mainPara() throws Exception {
        // OPEN INPUT IN-FILE, OPEN OUTPUT OUT-FILE already done
        while (!wsEofFlag.equals("Y")) {
            String line = inReader.readLine();
            if (line == null) {
                wsEofFlag = "Y";
            } else {
                // pad/truncate to IN_REC_LEN
                currentLineRaw = padRight(line, IN_REC_LEN);
                parseInputRecord();
                processRec();
            }
        }
        // CLOSE done in run()
    }

    private void processRec() throws Exception {
        wsReadCount = (wsReadCount + 1) % 100000; // PIC 9(05) wraps but not critical
        // EVALUATE REC-TYPE
        if (recType.equals("A")) {
            handleAcct();
        } else if (recType.equals("C")) {
            handleCust();
        } else {
            handleOther();
        }
    }

    private void handleAcct() throws Exception {
        wsHoldAcctNo = acctNo;
        wsHoldBranch = branchCode;
        dormantOutputRec = spaces(OUT_REC_LEN);
        outAcctNo = acctNo;
        outCustId = wsHoldCustId;
        outRecType = "A";
        outDaysInactive = lastActDays;
        outBalance = currBalanceInt;
        outBranchCode = branchCode;
        if (lastActDays >= wsDormantThreshold) {
            outDormantFlag = "Y";
            outReasonCode = padRight("DORMANT-365 ", 12);
        } else {
            if (lastActDays >= wsWarnThreshold) {
                outDormantFlag = "W";
                outReasonCode = padRight("WATCH-180   ", 12);
            } else {
                outDormantFlag = "N";
                outReasonCode = padRight("ACTIVE      ", 12);
            }
        }
        buildAndWriteOutput();
        wsWriteCount = (wsWriteCount + 1) % 100000;
        if (outDormantFlag.equals("Y")) {
            writeAlertDup();
        }
    }

    private void handleCust() throws Exception {
        wsHoldCustId = custId;
        dormantOutputRec = spaces(OUT_REC_LEN);
        outAcctNo = wsHoldAcctNo;
        outCustId = custId;
        outRecType = "C";
        outDaysInactive = contactDays;
        outBalance = 0;
        outBranchCode = wsHoldBranch;
        if (contactDays >= wsDormantThreshold) {
            outDormantFlag = "Y";
            outReasonCode = padRight("NO-CONTACT  ", 12);
        } else {
            outDormantFlag = "N";
            outReasonCode = padRight("IN-CONTACT  ", 12);
        }
        buildAndWriteOutput();
        wsWriteCount = (wsWriteCount + 1) % 100000;
    }

    private void handleOther() throws Exception {
        dormantOutputRec = spaces(OUT_REC_LEN);
        outAcctNo = wsHoldAcctNo;
        outCustId = wsHoldCustId;
        outRecType = recType;
        outDaysInactive = 0;
        outBalance = 0;
        outDormantFlag = "E";
        outReasonCode = padRight("UNKNOWN-TYPE", 12);
        outBranchCode = wsHoldBranch;
        buildAndWriteOutput();
        wsWriteCount = (wsWriteCount + 1) % 100000;
    }

    private void writeAlertDup() throws Exception {
        dormantOutputRec = spaces(OUT_REC_LEN);
        outAcctNo = wsHoldAcctNo;
        outCustId = wsHoldCustId;
        outRecType = "A";
        outDaysInactive = lastActDays;
        outBalance = currBalanceInt;
        outDormantFlag = "R";
        outReasonCode = padRight("REVIEW-REQ  ", 12);
        outBranchCode = wsHoldBranch;
        buildAndWriteOutput();
        wsWriteCount = (wsWriteCount + 1) % 100000;
    }

    // helpers
    private void parseInputRecord() {
        // currentLineRaw length 35
        recType = currentLineRaw.substring(0, 1);
        String blk = currentLineRaw.substring(1, 35); // 34 chars
        // Acct detail overlay
        acctNo = safeSubstring(blk, 0, 10);
        lastActDays = parseIntSafe(safeSubstring(blk, 10, 4));
        String balStr = safeSubstring(blk, 14, 9);
        currBalanceInt = parseIntSafe(balStr);
        acctStatus = safeSubstring(blk, 23, 8);
        branchCode = safeSubstring(blk, 31, 3);
        // Cust detail overlay (same blk)
        custId = safeSubstring(blk, 0, 10);
        custName = safeSubstring(blk, 10, 15);
        contactDays = parseIntSafe(safeSubstring(blk, 25, 4));
        custType = safeSubstring(blk, 29, 5);
    }

    private void buildAndWriteOutput() throws Exception {
        // Build 50 char record: 10+10+1+1+4+9+12+3
        StringBuilder sb = new StringBuilder(OUT_REC_LEN);
        sb.append(padRight(outAcctNo, 10));
        sb.append(padRight(outCustId, 10));
        sb.append(padRight(outRecType, 1));
        sb.append(padRight(outDormantFlag, 1));
        sb.append(String.format("%04d", outDaysInactive % 10000));
        // OUT-BALANCE 9(07)V99 as 9 digits zero padded
        // Mask to 9 digits (overflow truncated like TRUNC)
        int bal = outBalance % 1000000000;
        if (bal < 0) bal += 1000000000;
        sb.append(String.format("%09d", bal));
        sb.append(padRight(outReasonCode, 12));
        sb.append(padRight(outBranchCode, 3));
        String rec = sb.toString();
        if (rec.length() > OUT_REC_LEN) rec = rec.substring(0, OUT_REC_LEN);
        if (rec.length() < OUT_REC_LEN) rec = padRight(rec, OUT_REC_LEN);
        dormantOutputRec = rec;
        outWriter.write(dormantOutputRec);
        outWriter.newLine();
    }

    private static String spaces(int n) {
        return " ".repeat(n);
    }

    private static String padRight(String s, int n) {
        if (s == null) s = "";
        if (s.length() > n) return s.substring(0, n);
        if (s.length() == n) return s;
        return s + " ".repeat(n - s.length());
    }

    private static String safeSubstring(String s, int off, int len) {
        if (off >= s.length()) return spaces(len);
        int end = Math.min(s.length(), off + len);
        String sub = s.substring(off, end);
        if (sub.length() < len) sub = padRight(sub, len);
        return sub;
    }

    private static int parseIntSafe(String s) {
        s = s.trim();
        if (s.isEmpty()) return 0;
        // keep only digits (COBOL numeric DISPLAY may have spaces)
        StringBuilder b = new StringBuilder();
        for (char c : s.toCharArray()) if (c >= '0' && c <= '9') b.append(c);
        if (b.length() == 0) return 0;
        try { return Integer.parseInt(b.toString()); } catch (NumberFormatException e) {
            // large value, truncate to last 9 digits like TRUNC
            String t = b.toString();
            if (t.length() > 9) t = t.substring(t.length() - 9);
            return Integer.parseInt(t);
        }
    }
}
