{"mainClass": "Gen0041", "javaSource": "import java.io.*;
import java.math.*;
import java.nio.charset.*;
import java.nio.file.*;
import java.util.*;

public class Gen0041 {
    public static void main(String[] args) throws Exception {
        String inPath = System.getenv("DD_INFILE");
        String outPath = System.getenv("DD_OUTFILE");
        if (inPath == null || outPath == null) {
            System.err.println("DD_INFILE/DD_OUTFILE not set");
            System.exit(1);
        }
        Gen0041 prog = new Gen0041();
        prog.run(inPath, outPath);
    }

    // Working storage
    BigDecimal wsMatchRate = BigDecimal.ZERO;
    BigDecimal wsCapAmt = new BigDecimal("5000.00");
    BigDecimal wsEmpContrib = BigDecimal.ZERO;
    BigDecimal wsErMatchCalc = BigDecimal.ZERO;
    BigDecimal wsTotalCalc = BigDecimal.ZERO;
    int wsVestedPct = 0;
    String wsCapFlag = "N";
    String wsEofFlag = "N";

    // Current input fields
    String empId;
    String empName;
    BigDecimal annualSalary;
    BigDecimal empContribPct;
    int yearsService;
    String deptCode;
    String empStatus;

    List<String> inLines;
    BufferedWriter outWriter;

    void run(String inPath, String outPath) throws Exception {
        inLines = Files.readAllLines(Paths.get(inPath), StandardCharsets.ISO_8859_1);
        outWriter = Files.newBufferedWriter(Paths.get(outPath), StandardCharsets.ISO_8859_1,
                StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING, StandardOpenOption.WRITE);
        mainPara();
        outWriter.close();
    }

    void mainPara() throws Exception {
        int idx = 0;
        while (true) {
            if (idx >= inLines.size()) {
                wsEofFlag = "Y";
            } else {
                String line = inLines.get(idx++);
                // LINE SEQUENTIAL: record is line content; pad to 43 if shorter
                if (line.length() < 43) {
                    line = String.format("%-43s", line);
                }
                if (line.length() > 43) {
                    line = line.substring(0, 43);
                }
                parseInRec(line);
                if (!wsEofFlag.equals("Y")) {
                    processRec();
                    continue;
                }
            }
            if (wsEofFlag.equals("Y")) break;
        }
    }

    void parseInRec(String rec) {
        empId = rec.substring(0, 6);
        empName = rec.substring(6, 26);
        String sSalary = rec.substring(26, 32);
        String sPct = rec.substring(32, 36);
        String sYears = rec.substring(36, 38);
        deptCode = rec.substring(38, 42);
        empStatus = rec.substring(42, 43);

        annualSalary = parseNumber(sSalary, 0); // PIC 9(06) integer
        empContribPct = parseNumber(sPct, 2); // PIC 9(02)V99 -> 2 decimal places
        yearsService = parseInt(sYears);
    }

    BigDecimal parseNumber(String s, int scale) {
        s = s.trim();
        if (s.isEmpty()) return BigDecimal.ZERO;
        // s contains digits, possibly signed? For this file unsigned display.
        // V implies scale: digits represent value / 10^scale
        // Remove leading spaces, keep digits and sign
        s = s.trim();
        // If contains non-digit, handle?
        boolean negative = false;
        if (s.startsWith("-") || s.startsWith("+")) {
            negative = s.startsWith("-");
            s = s.substring(1);
        }
        // keep only digits
        StringBuilder dig = new StringBuilder();
        for (char c : s.toCharArray()) if (Character.isDigit(c)) dig.append(c);
        if (dig.length() == 0) return BigDecimal.ZERO;
        BigDecimal v = new BigDecimal(dig.toString());
        if (scale > 0) v = v.movePointLeft(scale);
        if (negative) v = v.negate();
        return v;
    }

    int parseInt(String s) {
        s = s.trim();
        if (s.isEmpty()) return 0;
        try { return Integer.parseInt(s.trim()); } catch (Exception e) {
            StringBuilder d=new StringBuilder();
            for(char c: s.toCharArray()) if(Character.isDigit(c)) d.append(c);
            if(d.length()==0) return 0;
            return Integer.parseInt(d.toString());
        }
    }

    void processRec() throws Exception {
        // DETERMINE MATCH RATE
        if (yearsService >= 10) {
            wsMatchRate = new BigDecimal("1.00");
        } else if (yearsService >= 5) {
            wsMatchRate = new BigDecimal("0.75");
        } else if (yearsService >= 2) {
            wsMatchRate = new BigDecimal("0.50");
        } else {
            wsMatchRate = new BigDecimal("0.25");
        }

        // EMPLOYEE CONTRIBUTION ROUNDED
        // COMPUTE WS-EMP-CONTRIB ROUNDED = ANNUAL-SALARY * EMP-CONTRIB-PCT / 100
        BigDecimal calc = annualSalary.multiply(empContribPct).divide(new BigDecimal("100"), 10, RoundingMode.HALF_UP);
        wsEmpContrib = calc.setScale(2, RoundingMode.HALF_UP);
        // TRUNC(STD) overflow handling: keep only PIC digits (5 integer +2 dec = 7 digits)
        // value stored keeps only PIC digits? For ROUNDED compute then move, overflow truncation?
        // Apply truncation to fit PIC 9(05)V99 : modulo 10^7 (including decimals) with sign?
        // For positive values, emulate truncation of high-order digits beyond 5 integer digits.
        // Use TRUNC: keep only lowest n digits.
        wsEmpContrib = truncToPic(wsEmpContrib, 5, 2);

        // EMPLOYER MATCH ROUNDED
        BigDecimal calc2 = wsEmpContrib.multiply(wsMatchRate);
        wsErMatchCalc = calc2.setScale(2, RoundingMode.HALF_UP);
        wsErMatchCalc = truncToPic(wsErMatchCalc, 5, 2);

        wsCapFlag = "N";
        if (wsErMatchCalc.compareTo(wsCapAmt) > 0) {
            wsErMatchCalc = wsCapAmt;
            wsCapFlag = "Y";
        }

        // VESTING
        if (yearsService >= 6) wsVestedPct = 100;
        else if (yearsService == 5) wsVestedPct = 80;
        else if (yearsService == 4) wsVestedPct = 60;
        else if (yearsService == 3) wsVestedPct = 40;
        else wsVestedPct = 0;
        if ("T".equals(empStatus)) wsVestedPct = 0;

        BigDecimal calc3 = wsEmpContrib.add(wsErMatchCalc);
        wsTotalCalc = calc3.setScale(2, RoundingMode.HALF_UP);
        wsTotalCalc = truncToPic(wsTotalCalc, 5, 2);

        writeOut();
    }

    BigDecimal truncToPic(BigDecimal val, int intDigits, int decDigits) {
        // TRUNC(STD): keeps only PIC digits (including decimals)
        // Emulate by modulo 10^(intDigits+decDigits) for positive, preserve sign
        // For simplicity apply only if overflow: absolute value >= 10^intDigits
        // COBOL stores only intDigits; high order truncated. We simulate via modulo.
        // Scale is decDigits.
        int totalDigits = intDigits + decDigits;
        BigDecimal scaled = val.movePointRight(decDigits); // integer representation
        // scaled should be integer (scale 0)
        BigDecimal mod = BigDecimal.TEN.pow(totalDigits);
        // For negative, COBOL keeps sign and truncates magnitude? Use remainder approach.
        boolean neg = scaled.signum() < 0;
        BigDecimal abs = scaled.abs().setScale(0, RoundingMode.DOWN);
        if (abs.compareTo(mod) >= 0) {
            abs = abs.remainder(mod);
            scaled = neg ? abs.negate() : abs;
            val = scaled.movePointLeft(decDigits).setScale(decDigits, RoundingMode.UNNECESSARY);
        }
        return val;
    }

    void writeOut() throws Exception {
        String outEmpId = padRight(empId, 6);
        String outEmpContrib = formatNumeric(wsEmpContrib, 5, 2);
        String outMatchRate = formatNumeric(wsMatchRate, 1, 2);
        // TRUNCATING MOVE into smaller field
        String outEmployerMatch = formatNumericTruncate(wsErMatchCalc, 4, 2);
        String outTotalContrib = formatNumeric(wsTotalCalc, 5, 2);
        String outVestedPct = formatNumericInt(wsVestedPct, 3);
        String outMatchCapFlag = wsCapFlag;

        String rec = outEmpId + outEmpContrib + outMatchRate + outEmployerMatch + outTotalContrib + outVestedPct + outMatchCapFlag;
        outWriter.write(rec);
        outWriter.newLine();
    }

    String formatNumeric(BigDecimal val, int intDigits, int decDigits) {
        int total = intDigits + decDigits;
        boolean neg = val.signum() < 0;
        BigDecimal abs = val.abs().setScale(decDigits, RoundingMode.UNNECESSARY);
        BigDecimal scaled = abs.movePointRight(decDigits).setScale(0, RoundingMode.UNNECESSARY);
        String s = scaled.toPlainString();
        // pad leading zeros to total length, truncate high order if overflow (should already truncated)
        if (s.length() > total) s = s.substring(s.length() - total);
        else if (s.length() < total) s = "0".repeat(total - s.length()) + s;
        if (neg) {
            // For signed DISPLAY without SEPARATE, negative would be encoded; but outputs here are unsigned.
            // Keep minus sign? Not needed. Just return as is.
        }
        return s;
    }

    String formatNumericTruncate(BigDecimal val, int intDigits, int decDigits) {
        int total = intDigits + decDigits;
        boolean neg = val.signum() < 0;
        BigDecimal abs = val.abs().setScale(decDigits, RoundingMode.UNNECESSARY);
        BigDecimal scaled = abs.movePointRight(decDigits).setScale(0, RoundingMode.UNNECESSARY);
        String s = scaled.toPlainString();
        if (s.length() > total) s = s.substring(s.length() - total);
        else if (s.length() < total) s = "0".repeat(total - s.length()) + s;
        return s;
    }

    String formatNumericInt(int val, int digits) {
        String s = String.valueOf(Math.abs(val));
        if (s.length() > digits) s = s.substring(s.length() - digits);
        else if (s.length() < digits) s = "0".repeat(digits - s.length()) + s;
        return s;
    }

    String padRight(String s, int len) {
        if (s == null) s = "";
        if (s.length() > len) return s.substring(0, len);
        if (s.length() < len) return s + " ".repeat(len - s.length());
        return s;
    }
}
