{"mainClass": "Gen0042", "javaSource": "import java.io.*;
import java.math.*;
import java.nio.file.*;

public class Gen0042 {
    static String ddInfile = System.getenv("DD_INFILE");
    static String ddOutfile = System.getenv("DD_OUTFILE");

    static InputStream inFile;
    static OutputStream outFile;

    static byte[] inRecBuf = new byte[33];
    static byte[] outRecBuf = new byte[32];

    // Working storage
    static String WS_EOF_FLAG = "N";
    static BigDecimal WS_DISCOUNT_AMT = BigDecimal.ZERO;
    static BigDecimal WS_SUBTOTAL = BigDecimal.ZERO;
    static BigDecimal WS_LATE_RATE = new BigDecimal("2.50");
    static BigDecimal WS_TEMP_LATE = BigDecimal.ZERO;
    static int WS_COUNTER = 0;

    // IN fields
    static String IN_BOX_ID;
    static String IN_CUST_ID;
    static String IN_BOX_SIZE;
    static String IN_BRANCH_CODE;
    static BigDecimal IN_ANNUAL_FEE;
    static BigDecimal IN_INSURANCE_FEE;
    static int IN_LATE_DAYS;
    static BigDecimal IN_DISCOUNT_PCT;

    // OUT fields
    static String OUT_BOX_ID;
    static String OUT_CUST_ID;
    static String OUT_BRANCH_CODE;
    static String OUT_BOX_SIZE;
    static BigDecimal OUT_BASE_AMT;
    static BigDecimal OUT_LATE_CHARGE;
    static BigDecimal OUT_TOTAL_DUE;
    static String OUT_BILL_STATUS;

    public static void main(String[] args) throws Exception {
        // guard: no reflection etc is enforced by not using them
        if (ddInfile == null) ddInfile = System.getenv("DD_INFILE");
        if (ddOutfile == null) ddOutfile = System.getenv("DD_OUTFILE");
        // open files
        String inPath = System.getenv("DD_INFILE");
        String outPath = System.getenv("DD_OUTFILE");
        if (inPath == null) inPath = ddInfile;
        if (outPath == null) outPath = ddOutfile;
        // Fallback to env names as described
        if (inPath == null) inPath = System.getenv("DD_INFILE");
        if (outPath == null) outPath = System.getenv("DD_OUTFILE");

        // If still null, try literal
        if (inPath == null) inPath = System.getenv("DD_INFILE");
        // Use System.getenv directly for compliance
        String p1 = System.getenv("DD_INFILE");
        String p2 = System.getenv("DD_OUTFILE");
        if (p1 != null) inPath = p1;
        if (p2 != null) outPath = p2;

        if (inPath == null || outPath == null) {
            // try without env - exit
            System.err.println("DD_INFILE/DD_OUTFILE not set");
            System.exit(1);
        }
        inFile = Files.newInputStream(Paths.get(inPath));
        outFile = Files.newOutputStream(Paths.get(outPath));
        mainPara();
        inFile.close();
        outFile.close();
    }

    static void mainPara() throws Exception {
        // OPEN INPUT IN-FILE OUTPUT OUT-FILE
        WS_EOF_FLAG = "N";
        while (!WS_EOF_FLAG.equals("Y")) {
            int r = readFixed(inFile, inRecBuf);
            if (r < 0 || r < inRecBuf.length) {
                if (r < 0 || r == 0) {
                    WS_EOF_FLAG = "Y";
                } else if (r < inRecBuf.length) {
                    // partial record -> treat as EOF? but pad
                    // For SEQUENTIAL, partial at end is ignored
                    WS_EOF_FLAG = "Y";
                }
            } else {
                parseInRec();
                processRec();
            }
        }
        // CLOSE
    }

    static void processRec() throws Exception {
        WS_COUNTER++;
        // COMPUTE WS-DISCOUNT-AMT = IN-ANNUAL-FEE * IN-DISCOUNT-PCT / 100
        // COBOL semantics: exact decimal then store into S9(5)V99 truncating
        BigDecimal disc = IN_ANNUAL_FEE.multiply(IN_DISCOUNT_PCT).divide(new BigDecimal("100"), 10, RoundingMode.HALF_UP);
        WS_DISCOUNT_AMT = storeToPic(disc, 5, 2, true);

        BigDecimal sub = IN_ANNUAL_FEE.add(IN_INSURANCE_FEE).subtract(WS_DISCOUNT_AMT);
        WS_SUBTOTAL = storeToPic(sub, 5, 2, true);
        if (WS_SUBTOTAL.compareTo(BigDecimal.ZERO) < 0) {
            WS_SUBTOTAL = BigDecimal.ZERO;
        }
        if (IN_LATE_DAYS > 0) {
            BigDecimal tl = BigDecimal.valueOf(IN_LATE_DAYS).multiply(WS_LATE_RATE);
            WS_TEMP_LATE = storeToPic(tl, 5, 2, true);
        } else {
            WS_TEMP_LATE = BigDecimal.ZERO;
        }
        OUT_BOX_ID = IN_BOX_ID;
        OUT_CUST_ID = IN_CUST_ID;
        OUT_BRANCH_CODE = IN_BRANCH_CODE;
        OUT_BOX_SIZE = IN_BOX_SIZE;
        OUT_BASE_AMT = storeToPic(WS_SUBTOTAL, 5, 2, true);
        OUT_LATE_CHARGE = storeToPic(WS_TEMP_LATE, 4, 2, true);
        BigDecimal total = WS_SUBTOTAL.add(WS_TEMP_LATE);
        OUT_TOTAL_DUE = storeToPic(total, 6, 2, true);
        if (OUT_TOTAL_DUE.compareTo(BigDecimal.ZERO) > 0) {
            OUT_BILL_STATUS = "P";
        } else {
            OUT_BILL_STATUS = "Z";
        }
        writeOutRec();
        if (IN_BOX_SIZE.equals("L")) {
            OUT_BOX_ID = IN_BOX_ID;
            OUT_CUST_ID = IN_CUST_ID;
            OUT_BRANCH_CODE = IN_BRANCH_CODE;
            OUT_BOX_SIZE = IN_BOX_SIZE;
            OUT_BASE_AMT = storeToPic(IN_INSURANCE_FEE, 5, 2, true);
            OUT_LATE_CHARGE = BigDecimal.ZERO;
            OUT_TOTAL_DUE = storeToPic(IN_INSURANCE_FEE, 6, 2, true);
            OUT_BILL_STATUS = "I";
            writeOutRec();
        }
    }

    // store to PIC S9(n)V99 or 9(n)V99 with truncation (no rounding) as COBOL MOVE/COMPUTE without ROUNDED
    // For fidelity, we truncate towards zero to scale 2
    static BigDecimal storeToPic(BigDecimal val, int intDigits, int scale, boolean signed) {
        if (val == null) return BigDecimal.ZERO;
        // Truncate to scale (COBOL without ROUNDED truncates)
        BigDecimal t = val.setScale(scale, RoundingMode.DOWN);
        // Overflow truncation TRUNC(STD): keep only low-order digits (PIC digits)
        // i.e., value modulo 10^intDigits (with sign)
        BigDecimal modulus = BigDecimal.TEN.pow(intDigits);
        // For packed, integer part truncated: we need to keep fractional scale separate
        // Compute scaled integer: t *10^scale
        BigDecimal scaled = t.movePointRight(scale); // integer
        // Truncate integer digits: keep last intDigits+scale digits? PIC 9(intDigits)V99 means total integer digits = intDigits.
        // So scaled has intDigits+scale digits max. Truncate higher digits.
        BigDecimal modScaled = BigDecimal.TEN.pow(intDigits + scale);
        // signed truncated magnitude: preserve sign
        boolean neg = scaled.signum() < 0;
        BigDecimal abs = scaled.abs();
        // overflow wrap: abs % modScaled
        BigDecimal truncated = abs.remainder(modScaled);
        // reapply sign
        if (neg) truncated = truncated.negate();
        BigDecimal result = truncated.movePointLeft(scale).setScale(scale, RoundingMode.UNNECESSARY);
        // normalize -0 to 0
        if (result.compareTo(BigDecimal.ZERO) == 0) result = BigDecimal.ZERO.setScale(scale);
        // ensure scale
        result = result.setScale(scale, RoundingMode.UNNECESSARY);
        return result;
    }

    static void parseInRec() {
        int pos = 0;
        IN_BOX_ID = readStr(inRecBuf, pos, 8); pos += 8;
        IN_CUST_ID = readStr(inRecBuf, pos, 6); pos += 6;
        IN_BOX_SIZE = readStr(inRecBuf, pos, 1); pos += 1;
        IN_BRANCH_CODE = readStr(inRecBuf, pos, 3); pos += 3;
        IN_ANNUAL_FEE = unpack(inRecBuf, pos, 4, 2, false); pos += 4; // 9(5)V99 unsigned
        IN_INSURANCE_FEE = unpack(inRecBuf, pos, 4, 2, false); pos += 4;
        IN_LATE_DAYS = Integer.parseInt(readStr(inRecBuf, pos, 3)); pos += 3;
        String discStr = readStr(inRecBuf, pos, 4); pos += 4;
        // PIC 9(02)V99 DISPLAY : 4 chars digits, implied 2 decimals
        int discInt = 0;
        try { discInt = Integer.parseInt(discStr.trim().isEmpty()?"0":discStr.trim()); } catch (NumberFormatException e) {
            // if contains not digits, parse raw
            discInt = parseDigits(discStr);
        }
        // If discStr may contain leading zeros, e.g. "0050" => 0.50? Actually 00.50
        IN_DISCOUNT_PCT = new BigDecimal(discInt).movePointLeft(2).setScale(2, RoundingMode.UNNECESSARY);
    }

    static void writeOutRec() throws Exception {
        // build 32 bytes
        byte[] rec = new byte[32];
        int pos = 0;
        writeStr(rec, pos, 8, OUT_BOX_ID); pos += 8;
        writeStr(rec, pos, 6, OUT_CUST_ID); pos += 6;
        writeStr(rec, pos, 3, OUT_BRANCH_CODE); pos += 3;
        writeStr(rec, pos, 1, OUT_BOX_SIZE); pos += 1;
        pack(rec, pos, 4, 2, OUT_BASE_AMT, true); pos += 4;
        pack(rec, pos, 4, 2, OUT_LATE_CHARGE, true); pos += 4;
        pack(rec, pos, 5, 2, OUT_TOTAL_DUE, true); pos += 5;
        writeStr(rec, pos, 1, OUT_BILL_STATUS); pos += 1;
        outFile.write(rec);
    }

    // helpers
    static int readFixed(InputStream is, byte[] buf) throws IOException {
        int off = 0;
        while (off < buf.length) {
            int n = is.read(buf, off, buf.length - off);
            if (n < 0) {
                if (off == 0) return -1;
                break;
            }
            off += n;
        }
        return off;
    }
    static String readStr(byte[] buf, int pos, int len) {
        return new String(buf, pos, len, java.nio.charset.StandardCharsets.ISO_8859_1);
    }
    static void writeStr(byte[] buf, int pos, int len, String s) {
        byte[] b = s == null ? new byte[0] : s.getBytes(java.nio.charset.StandardCharsets.ISO_8859_1);
        for (int i = 0; i < len; i++) {
            buf[pos + i] = i < b.length ? b[i] : (byte) ' ';
        }
    }
    static int parseDigits(String s) {
        int v = 0;
        for (char c : s.toCharArray()) if (c >= '0' && c <= '9') v = v * 10 + (c - '0');
        return v;
    }
    static BigDecimal unpack(byte[] buf, int pos, int len, int scale, boolean signed) {
        // COMP-3 big-endian packed, sign nibble last
        StringBuilder digits = new StringBuilder();
        int sign = 1;
        for (int i = 0; i < len; i++) {
            int b = buf[pos + i] & 0xFF;
            int hi = (b >> 4) & 0xF;
            int lo = b & 0xF;
            if (i == len - 1) {
                digits.append(hi);
                if (lo == 0x0D) sign = -1;
                else sign = 1;
            } else {
                digits.append(hi);
                digits.append(lo);
            }
        }
        // digits contains all nibbles except sign, may have leading zero pad
        String s = digits.toString();
        // remove leading pad zeros beyond required? keep as is
        // Convert to BigDecimal with scale
        BigDecimal v = new BigDecimal(s).movePointLeft(scale);
        if (sign < 0) v = v.negate();
        v = v.setScale(scale, RoundingMode.UNNECESSARY);
        return v;
    }
    static void pack(byte[] buf, int pos, int len, int scale, BigDecimal val, boolean signed) {
        boolean neg = val.signum() < 0;
        BigDecimal abs = val.abs().setScale(scale, RoundingMode.UNNECESSARY).movePointRight(scale);
        String s = abs.toPlainString();
        // s is integer digits (no decimal)
        // remove decimal point if any
        if (s.indexOf('.') >= 0) s = s.replace(".", "");
        // pad with leading zeros to len*2 -1 digits
        int totalDigits = len * 2 - 1;
        if (s.length() > totalDigits) {
            // overflow already truncated earlier, but handle
            s = s.substring(s.length() - totalDigits);
        }
        s = String.format("%" + totalDigits + "s", s).replace(' ', '0');
        for (int i = 0; i < len; i++) {
            int hi = s.charAt(i * 2) - '0';
            int lo;
            if (i == len - 1) {
                if (signed) lo = neg ? 0x0D : 0x0C;
                else lo = 0x0F;
            } else {
                lo = s.charAt(i * 2 + 1) - '0';
            }
            buf[pos + i] = (byte) ((hi << 4) | lo);
        }
    }
}

