{"mainClass": "Gen0049", "javaSource": "import java.io.*;
import java.math.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

public class Gen0049 {
    // Working-Storage
    static int wsReadCnt = 0;
    static int wsWriteCnt = 0;

    static BigDecimal wsDiscountPct = BigDecimal.ZERO;
    static BigDecimal wsFeeAfterDisc = BigDecimal.ZERO;
    static BigDecimal wsTaxRate = new BigDecimal("7.50");
    static BigDecimal wsFeeWithTax = BigDecimal.ZERO;
    static BigDecimal wsBillHold = BigDecimal.ZERO;
    static BigDecimal wsSpendThreshold = new BigDecimal("15000.00");
    static String wsFlagField = "N";

    // Output field picture scale = decimal digits after implied decimal
    static final int SCALE_DISCOUNT = 2; // 9(02)V99
    static final int SCALE_FEE_AFTER = 2; // 9(06)V99
    static final int SCALE_FEE_WITH_TAX = 2;
    static final int SCALE_BILL_HOLD = 2; // 9(05)V99
    static final int SCALE_BILL_AMT = 2; // OUT BILL-AMT 9(05)V99
    static final int SCALE_BILL_AMT_DISP = 2; // 9(03)V99
    static final int SCALE_SPEND_THRESHOLD = 2;

    static BigDecimal cobolMove(BigDecimal value, int scale, int integerDigits) {
        if (value == null) value = BigDecimal.ZERO;
        BigDecimal rounded = value.setScale(scale, RoundingMode.HALF_UP);
        // TRUNC(STD) keep only PIC digits: integer part truncated to integerDigits
        // Build truncated integer portion
        boolean negative = rounded.signum() < 0;
        BigDecimal abs = rounded.abs();
        // separate integer and fractional
        BigDecimal intPart = abs.setScale(0, RoundingMode.DOWN);
        BigDecimal fracPart = abs.subtract(intPart);
        // truncate integer digits: modulo 10^integerDigits
        BigDecimal mod = BigDecimal.TEN.pow(integerDigits);
        BigDecimal truncatedInt = intPart.remainder(mod);
        BigDecimal result = truncatedInt.add(fracPart).setScale(scale, RoundingMode.UNNECESSARY);
        if (negative) result = result.negate();
        return result;
    }

    static BigDecimal computeRounded(BigDecimal raw, int targetScale, int targetIntDigits) {
        BigDecimal rounded = raw.setScale(targetScale, RoundingMode.HALF_UP);
        return cobolMove(rounded, targetScale, targetIntDigits);
    }

    // Picture formatting: PIC 9(n)V99 -> output as n+m digits, zero padded, no decimal point
    static String formatPIC9V99(BigDecimal val, int intDigits, int scale) {
        // val is already scaled and truncated
        // For unsigned PIC, negative not expected; if negative would use display but not needed
        BigDecimal abs = val.abs();
        // Ensure scale
        abs = abs.setScale(scale, RoundingMode.UNNECESSARY);
        // integer part zero-padded to intDigits
        BigDecimal intPart = abs.setScale(0, RoundingMode.DOWN);
        BigDecimal fracFactor = BigDecimal.TEN.pow(scale);
        BigDecimal fracPart = abs.subtract(intPart).multiply(fracFactor).setScale(0, RoundingMode.UNNECESSARY);
        String intStr = intPart.toPlainString();
        // intPart may have fewer digits, pad
        if (intStr.length() > intDigits) {
            // already truncated, but just in case take rightmost
            intStr = intStr.substring(intStr.length() - intDigits);
        } else {
            intStr = String.format("%" + intDigits + "s", intStr).replace(' ', '0');
        }
        String fracStr = fracPart.toPlainString();
        fracStr = String.format("%" + scale + "s", fracStr).replace(' ', '0');
        if (fracStr.length() > scale) fracStr = fracStr.substring(fracStr.length()-scale);
        return intStr + fracStr;
    }

    static BigDecimal parsePIC9V99(String s, int intDigits, int scale) {
        if (s == null) s = "";
        s = s.trim();
        if (s.isEmpty()) return BigDecimal.ZERO;
        // s should be digits only length intDigits+scale
        // If it contains decimal point (unlikely), handle
        if (s.contains(".")) {
            BigDecimal bd = new BigDecimal(s);
            return cobolMove(bd, scale, intDigits);
        }
        // Remove non-digits? Keep as is
        // Ensure length
        // If shorter, pad left with zeros (COBOL numeric field would be zero padded)
        String digits = s.replaceAll("[^0-9]", "");
        if (digits.isEmpty()) return BigDecimal.ZERO;
        if (digits.length() <= scale) {
            digits = String.format("%" + (scale+1) + "s", digits).replace(' ', '0');
        }
        int len = digits.length();
        String intPart = digits.substring(0, len - scale);
        String fracPart = digits.substring(len - scale);
        BigDecimal bd = new BigDecimal(intPart + "." + fracPart);
        return bd;
    }

    static void processRecGen0049(String custId, String cardType, BigDecimal annualSpend, BigDecimal annFeeBase, int tenureYears,
                                   StringBuilder outRecordBuilder, Holder<BigDecimal> billAmtHolder, Holder<BigDecimal> billAmtDispHolder) {
        wsDiscountPct = cobolMove(BigDecimal.ZERO, SCALE_DISCOUNT, 2);
        wsFlagField = "N";
        wsFeeWithTax = cobolMove(BigDecimal.ZERO, SCALE_FEE_WITH_TAX, 6);
        wsFeeAfterDisc = cobolMove(BigDecimal.ZERO, SCALE_FEE_AFTER, 6);

        if (tenureYears >= 10) {
            wsDiscountPct = cobolMove(new BigDecimal("25.00"), SCALE_DISCOUNT, 2);
        } else if (tenureYears >= 5) {
            wsDiscountPct = cobolMove(new BigDecimal("15.00"), SCALE_DISCOUNT, 2);
        } else if (tenureYears >= 2) {
            wsDiscountPct = cobolMove(new BigDecimal("5.00"), SCALE_DISCOUNT, 2);
        } else {
            wsDiscountPct = cobolMove(BigDecimal.ZERO, SCALE_DISCOUNT, 2);
        }
        if ("P".equals(cardType)) {
            BigDecimal raw = wsDiscountPct.add(new BigDecimal("10.00"));
            wsDiscountPct = computeRounded(raw, SCALE_DISCOUNT, 2);
        }
        if (annualSpend.compareTo(wsSpendThreshold) >= 0) {
            wsFlagField = "Y";
            wsFeeWithTax = cobolMove(BigDecimal.ZERO, SCALE_FEE_WITH_TAX, 6);
        } else {
            // COMPUTE WS-FEE-AFTER-DISC ROUNDED = ANN-FEE-BASE * (100 - WS-DISCOUNT-PCT) /100
            BigDecimal rawAfter = annFeeBase.multiply(new BigDecimal("100").subtract(wsDiscountPct)).divide(new BigDecimal("100"), 10, RoundingMode.HALF_UP);
            wsFeeAfterDisc = computeRounded(rawAfter, SCALE_FEE_AFTER, 6);
            BigDecimal rawWithTax = wsFeeAfterDisc.multiply(new BigDecimal("100").add(wsTaxRate)).divide(new BigDecimal("100"), 10, RoundingMode.HALF_UP);
            wsFeeWithTax = computeRounded(rawWithTax, SCALE_FEE_WITH_TAX, 6);
        }

        // MOVEs to output fields
        String custIdO = padRight(custId, 10);
        String discountRateStr = formatPIC9V99(wsDiscountPct, 2, 2);
        String feeWaivedFlag = wsFlagField;

        BigDecimal billAmt;
        String billDesc;
        if ("Y".equals(wsFlagField)) {
            billAmt = cobolMove(BigDecimal.ZERO, SCALE_BILL_AMT, 5);
            billDesc = padRight("FEE WAIVED SPEND BONUS", 20);
        } else {
            billAmt = cobolMove(wsFeeWithTax, SCALE_BILL_AMT, 5);
            billDesc = padRight("ANNUAL FEE BILLED    ", 20);
            // the literal already 20 chars (with 4 spaces), padRight will keep it
            billDesc = padRight("ANNUAL FEE BILLED", 20);
            // But spec literal is 'ANNUAL FEE BILLED    ' which is 16+4=20, same as padRight
        }
        String billAmtStr = formatPIC9V99(billAmt, 5, 2);
        // WS-BILL-HOLD handling
        wsBillHold = cobolMove(billAmt, SCALE_BILL_HOLD, 5);
        BigDecimal rawHold = wsBillHold.multiply(new BigDecimal("1.005"));
        wsBillHold = computeRounded(rawHold, SCALE_BILL_HOLD, 5);
        BigDecimal billAmtDisp = cobolMove(wsBillHold, SCALE_BILL_AMT_DISP, 3);
        String billAmtDispStr = formatPIC9V99(billAmtDisp, 3, 2);

        // Build output record: CUST-ID(10) + BILL-AMT(7) + BILL-AMT-DISP(5) + DISCOUNT-RATE(4) + FLAG(1) + DESC(20)
        String outRec = custIdO + billAmtStr + billAmtDispStr + discountRateStr + feeWaivedFlag + billDesc;
        outRecordBuilder.setLength(0);
        outRecordBuilder.append(outRec);
    }

    static String padRight(String s, int len) {
        if (s == null) s = "";
        if (s.length() > len) return s.substring(0, len);
        StringBuilder sb = new StringBuilder(s);
        while (sb.length() < len) sb.append(' ');
        return sb.toString();
    }

    static class Holder<T> { T value; }

    public static void main(String[] args) throws Exception {
        String inPath = System.getenv("DD_INFILE");
        String outPath = System.getenv("DD_OUTFILE");
        if (inPath == null) inPath = System.getenv("DD_INFILE");
        // Fallbacks not needed
        List<String> lines = new ArrayList<>();
        if (inPath != null) {
            Path p = Paths.get(inPath);
            if (Files.exists(p)) {
                byte[] all = Files.readAllBytes(p);
                String content = new String(all, StandardCharsets.ISO_8859_1);
                // LINE SEQUENTIAL: split on \r?\n , keep empty lines? One record per line.
                // Preserve empty file -> no records
                if (!content.isEmpty()) {
                    String[] split = content.split("\\r?\\n", -1);
                    // If file ends with newline, last element after split is empty -> should not be treated as record
                    // COBOL LINE SEQUENTIAL trailing newline does not create extra record.
                    // Remove last empty element if original ends with newline
                    boolean endsWithNewline = content.endsWith("\n") || content.endsWith("\r");
                    for (int i=0;i<split.length;i++) {
                        if (i==split.length-1 && endsWithNewline && split[i].isEmpty()) continue;
                        lines.add(split[i]);
                    }
                }
            }
        }
        List<String> outLines = new ArrayList<>();
        for (String line : lines) {
            // Parse input record fixed 47 chars: 0-10,10-30,30-31,31-39,39-45,45-47
            String rec = line;
