            String feeBaseStr = rec.substring(39,45); //6 chars
            String tenureStr = rec.substring(45,47); //2 chars
            BigDecimal annualSpend = parsePIC9V99(spendStr, 6, 2);
            BigDecimal annFeeBase = parsePIC9V99(feeBaseStr, 4, 2);
            int tenureYears = 0;
