            // tenure is 9(02) display
            wsReadCnt++;
            StringBuilder outRecBuilder = new StringBuilder();
            Holder<BigDecimal> h1 = new Holder<>();
            Holder<BigDecimal> h2 = new Holder<>();
            processRecGen0049(custId, cardType, annualSpend, annFeeBase, tenureYears, outRecBuilder, h1, h2);
            outLines.add(outRecBuilder.toString());
