{"mainClass": "Gen0053", "javaSource": "import java.io.*;
import java.math.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

public class Gen0053 {
    // Working storage
    private static boolean wsEof = false;
    private static int wsCountIn = 0;
    private static int wsCountOut = 0;
    private static BigDecimal wsNetPay = BigDecimal.ZERO;
    private static BigDecimal wsAdjAmt = BigDecimal.ZERO;
    private static final BigDecimal WS_CAP_LIMIT = new BigDecimal("50000.00");

    // Current record fields
    private static String inEmpId;
    private static String inEmpName;
    private static String inDeductCode;
