    private static String outDeptCode;
    private static String outStatus;
    private static String outMessage;

    private static List<String> inLines;
    private static int inIndex;
    private static BufferedWriter outWriter;

    public static void main(String[] args) throws Exception {
        String inFile = System.getenv("DD_INFILE");
        String outFile = System.getenv("DD_OUTFILE");
        if (inFile == null) inFile = System.getenv("DD_INFILE");
        if (outFile == null) outFile = System.getenv("DD_OUTFILE");

        // Guard: refuse network/process/reflection (no-op, just ensure we don't use)

        // Open
        Path inPath = inFile != null ? Paths.get(inFile) : null;
        Path outPath = outFile != null ? Paths.get(outFile) : null;

        // Read all input lines as text (LINE SEQUENTIAL) using ISO-8859-1 to preserve bytes
        if (inPath != null && Files.exists(inPath)) {
            byte[] all = Files.readAllBytes(inPath);
            String content = new String(all, StandardCharsets.ISO_8859_1);
            // Split on \r?\n, keep empty lines? One record per line
            // Preserve exactly: split with -1 and handle trailing newline
            String[] parts = content.split("\\r\\n|\\n|\\r", -1);
            inLines = new ArrayList<>(Arrays.asList(parts));
            // If file ends with newline, split creates extra empty element at end; remove it
            // GnuCOBOL LINE SEQUENTIAL: trailing newline does not create extra record
            if (!inLines.isEmpty() && inLines.get(inLines.size()-1).isEmpty() && content.endsWith("\n") || content.endsWith("\r")) {
                // Only remove one trailing empty caused by final separator
                // Check if last element is due to terminator
                if (!content.isEmpty() && inLines.size()>1) {
                    // remove last empty
                    inLines.remove(inLines.size()-1);
                }
            }
            // If file was empty, inLines may contain one empty string; treat as no records
            if (inLines.size()==1 && inLines.get(0).isEmpty() && content.isEmpty()) {
                inLines.clear();
            }
        } else {
            inLines = new ArrayList<>();
        }
        inIndex = 0;

        if (outPath != null) {
            Path parent = outPath.getParent();
            if (parent != null) Files.createDirectories(parent);
            outWriter = Files.newBufferedWriter(outPath, StandardCharsets.ISO_8859_1);
        } else {
            outWriter = null;
        }

        mainPara();

        if (outWriter != null) {
            outWriter.flush();
            outWriter.close();
        }
    }

    private static void mainPara() throws Exception {
        // OPEN INPUT IN-FILE OUTPUT OUT-FILE already handled
        while (!wsEof) {
            readInFile();
            if (!wsEof) {
                wsCountIn++;
                processRec();
            }
        }
        // CLOSE
    }

    private static void readInFile() {
        if (inIndex >= inLines.size()) {
            wsEof = true;
        } else {
            String line = inLines.get(inIndex++);
            parseInRec(line);
            wsEof = false;
        }
    }

    private static void parseInRec(String line) {
        // Pad to 62 with spaces if short
        String rec = padRight(line, 62);
        // If longer, truncate? COBOL would take first 62
        if (rec.length() > 62) rec = rec.substring(0, 62);
        inEmpId = rec.substring(0, 6);
        inEmpName = rec.substring(6, 26);
        inDeductCode = rec.substring(26, 28);
        String deductAmtStr = rec.substring(28, 35); // 7 chars
        String grossPayStr = rec.substring(35, 43); // 8 chars
        inPayPeriod = rec.substring(43, 49);
        inDeptCode = rec.substring(49, 52);
        // filler 52-62 ignored
        inDeductAmt = parseImplied(deductAmtStr, 2);
        inGrossPay = parseImplied(grossPayStr, 2);
    }

    private static BigDecimal parseImplied(String s, int decimals) {
        s = s.trim();
        if (s.isEmpty()) return BigDecimal.ZERO;
        // Keep only digits and sign? File should be digits
        // Handle possible sign overpunch? But LINE SEQUENTIAL with PIC 9 implies unsigned.
        // So just digits.
        String digits = s.replaceAll("[^0-9]", "");
        if (digits.isEmpty()) digits = "0";
        // pad?
        BigDecimal v = new BigDecimal(digits);
        v = v.movePointLeft(decimals);
        v = v.setScale(decimals, RoundingMode.UNNECESSARY);
        return v;
    }

    private static void processRec() throws Exception {
        // EVALUATE TRUE
        boolean dedHealth = inDeductCode.equals("HL");
        boolean dedRetire = inDeductCode.equals("RT");
        boolean dedTax = inDeductCode.equals("TX");
        boolean dedUnion = inDeductCode.equals("UN");
        boolean dedOther = inDeductCode.equals("OT");

        if (dedHealth) {
            outDeductDesc = "HEALTH";
            wsAdjAmt = inDeductAmt;
            outMessage = "HEALTH POSTED";
        } else if (dedRetire) {
            outDeductDesc = "RETIREMENT";
            // COMPUTE WS-ADJ-AMT = IN-DEDUCT-AMT * 1.05
            BigDecimal res = inDeductAmt.multiply(new BigDecimal("1.05"));
            wsAdjAmt = truncateToPic(res, 5, 2);
            outMessage = "RETIRE W/MATCH";
        } else if (dedTax) {
            outDeductDesc = "TAX W/H";
            BigDecimal res = inDeductAmt.add(new BigDecimal("25.00"));
            wsAdjAmt = truncateToPic(res, 5, 2);
            outMessage = "TAX FEE APPLIED";
        } else if (dedUnion) {
            outDeductDesc = "UNION DUES";
            wsAdjAmt = inDeductAmt;
            outMessage = "UNION DUES OK";
        } else if (dedOther) {
            outDeductDesc = "OTHER";
            wsAdjAmt = inDeductAmt;
            outMessage = "OTHER DEDUCT";
        } else {
            outDeductDesc = "UNKNOWN";
            wsAdjAmt = inDeductAmt;
            outMessage = "UNKNOWN CODE";
        }
        calcNet();
        writeOut();
    }

    private static BigDecimal truncateToPic(BigDecimal val, int intDigits, int decDigits) {
        // TRUNC(STD): keep only PIC digits, truncation toward zero? And overflow truncated?
        // For now: set scale decDigits with DOWN (truncation), then apply mod for integer overflow
        BigDecimal scaled = val.setScale(decDigits, RoundingMode.DOWN);
        // Handle overflow: keep only intDigits + decDigits digits? PIC 9(05)V99 max 99999.99
        // TRUNC STD keeps only PIC digits (mod 10^n)
        // We implement: value mod 10^(intDigits+decDigits) then /10^decimals ??? But simpler: max check
        // Use truncation: compute limit = 10^(intDigits) - 10^(-decDigits)
        // If scaled >= 10^intDigits, keep remainder modulo 10^intDigits (positive)
        BigDecimal tenPowInt = BigDecimal.TEN.pow(intDigits);
        if (scaled.compareTo(tenPowInt) >= 0 || scaled.compareTo(tenPowInt.negate()) <= 0) {
            // Truncate to low-order digits: remainder
            // For positive: scaled % tenPowInt
            // Preserve scale
            BigDecimal[] dr = scaled.remainder(tenPowInt).abs().multiply(BigDecimal.ONE.movePointRight(0)).divideAndRemainder(BigDecimal.ONE);
            // Simpler: use BigDecimal remainder
            scaled = scaled.remainder(tenPowInt);
            if (scaled.compareTo(BigDecimal.ZERO) < 0) scaled = scaled.add(tenPowInt);
            scaled = scaled.setScale(decDigits, RoundingMode.DOWN);
        }
        return scaled;
    }

    private static void calcNet() {
        if (wsAdjAmt.compareTo(inGrossPay) > 0) {
            wsAdjAmt = inGrossPay;
        }
        BigDecimal res = inGrossPay.subtract(wsAdjAmt);
        res = truncateToPic(res, 6, 2);
        wsNetPay = res;
        if (wsNetPay.compareTo(BigDecimal.ZERO) < 0) {
            wsNetPay = BigDecimal.ZERO.setScale(2);
        }
    }

    private static void writeOut() throws Exception {
        outEmpId = inEmpId;
        outEmpName = inEmpName;
        outPostedAmt = wsAdjAmt;
        outNetPay = wsNetPay;
        outPayPeriod = inPayPeriod;
        outDeptCode = inDeptCode;
        // EVALUATE TRUE for status
        if (wsNetPay.compareTo(BigDecimal.ZERO) == 0) {
            outStatus = "ER";
        } else if (wsAdjAmt.compareTo(WS_CAP_LIMIT) >= 0) {
            outStatus = "CP";
        } else {
            outStatus = "OK";
        }
        // Build output record length 84
        StringBuilder sb = new StringBuilder();
        sb.append(padRight(outEmpId, 6));
        sb.append(padRight(outEmpName, 20));
        sb.append(padRight(outDeductDesc, 12));
        sb.append(formatPic9(outPostedAmt, 5, 2));
        sb.append(formatPic9(outNetPay, 6, 2));
        sb.append(padRight(outPayPeriod, 6));
        sb.append(padRight(outDeptCode, 3));
        sb.append(padRight(outStatus, 2));
        sb.append(padRight(outMessage, 20));
        String outLine = sb.toString();
        if (outWriter != null) {
            outWriter.write(outLine);
            outWriter.newLine();
        }
        wsCountOut++;
    }

    private static String padRight(String s, int len) {
        if (s == null) s = "";
        if (s.length() > len) return s.substring(0, len);
        StringBuilder b = new StringBuilder(s);
        while (b.length() < len) b.append(' ');
        return b.toString();
    }

    private static String formatPic9(BigDecimal val, int intDigits, int decDigits) {
        if (val == null) val = BigDecimal.ZERO;
        val = val.setScale(decDigits, RoundingMode.DOWN);
        // Ensure positive? PIC 9 is unsigned, negative would not occur except 0 case
        if (val.compareTo(BigDecimal.ZERO) < 0) val = BigDecimal.ZERO;
        // Convert to integer of total digits
        BigDecimal scaled = val.movePointRight(decDigits);
        long totalDigits = intDigits + decDigits;
        String digits = scaled.toPlainString();
        // Remove decimal point (should be none)
        digits = digits.replace(".", "").replace("-", "");
        // digits may have leading minus? already handled
        // Pad left with zeros to totalDigits
        if (digits.length() > totalDigits) {
            // truncation: keep low-order digits
            digits = digits.substring(digits.length() - (int) totalDigits);
        } else if (digits.length() < totalDigits) {
            digits = "0".repeat((int) totalDigits - digits.length()) + digits;
        }
        return digits;
    }
}
