{"mainClass": "Gen0059", "javaSource": "import java.io.*;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.List;

public class Gen0059 {
    // FD IN-FILE copy GEN0059I
    private static final int IN_ACCT_OFF = 0; private static final int IN_ACCT_LEN = 8;
    private static final int IN_NAME_OFF = 8; private static final int IN_NAME_LEN = 12;
    private static final int IN_TXN_AMT_OFF = 20; private static final int IN_TXN_AMT_LEN = 7;
    private static final int IN_DAILY_LIM_OFF = 27; private static final int IN_DAILY_LIM_LEN = 7;
    private static final int IN_TXN_TYPE_OFF = 34; private static final int IN_TXN_TYPE_LEN = 4;
    private static final int IN_TXN_COUNT_OFF = 38; private static final int IN_TXN_COUNT_LEN = 3;
    private static final int IN_REC_LEN = 41;

    // FD OUT-FILE copy GEN0059O
    private static final int OUT_ACCT_LEN = 8;
    private static final int OUT_NAME_LEN = 12;
    private static final int OUT_STATUS_LEN = 10;
    private static final int OUT_APPROVED_LEN = 7;
    private static final int OUT_REMAIN_LEN = 7;
    private static final int OUT_GROUP_TOTAL_LEN = 9;
    private static final int OUT_REC_LEN = 53;

    // Working storage
    private String wsEofFlag = "N";
    private String wsPrevAcct = "        ";
    private String wsFirstRec = "Y";
    private BigDecimal wsGroupTotal = BigDecimal.ZERO;
    private int wsGroupCount = 0;
    private BigDecimal wsGrandTotal = BigDecimal.ZERO;
    private int wsGrandCount = 0;
    private BigDecimal wsRemainLimit = BigDecimal.ZERO;
    private BigDecimal wsApproved = BigDecimal.ZERO;
    private String wsStatus = "          ";

    // Current input record fields
    private String custAcct = "";
    private String custName = "";
    private BigDecimal txnAmount = BigDecimal.ZERO;
    private BigDecimal dailyLimit = BigDecimal.ZERO;
    private String txnType = "";
    private int txnCount = 0;

    // Output fields
    private String outAcct;
    private String outName;
    private String outStatus;
    private BigDecimal outApprovedAmt;
    private BigDecimal outRemainLimit;
    private BigDecimal outGroupTotal;

    private List<String> inLines;
    private int inIndex = 0;
    private BufferedWriter outWriter;

    public static void main(String[] args) throws Exception {
        Gen0059 prog = new Gen0059();
        prog.run();
    }

    private void run() throws Exception {
        String inFile = System.getenv("DD_INFILE");
        String outFile = System.getenv("DD_OUTFILE");
        if (inFile == null) inFile = System.getenv("DD_INFILE");
        if (outFile == null) outFile = System.getenv("DD_OUTFILE");

        // Read input LINE SEQUENTIAL as text ISO-8859-1, one record per line
        if (inFile != null) {
            Path p = Paths.get(inFile);
            if (Files.exists(p)) {
                byte[] bytes = Files.readAllBytes(p);
                String content = new String(bytes, StandardCharsets.ISO_8859_1);
                // Split on \r\n or \n, preserve empty lines? Each line is a record.
                // Use BufferedReader logic: if file ends without newline, last line still counts.
                // Files.readAllLines would strip terminators; replicate with split.
                inLines = new java.util.ArrayList<>();
                try (BufferedReader br = new BufferedReader(new StringReader(content))) {
                    String line;
                    while ((line = br.readLine()) != null) {
                        inLines.add(line);
                    }
                }
            } else {
                inLines = List.of();
            }
        } else {
            inLines = List.of();
        }

        Path outPath = outFile != null ? Paths.get(outFile) : null;
        if (outPath != null && outPath.getParent() != null) Files.createDirectories(outPath.getParent());
        OutputStream os = outPath != null ? Files.newOutputStream(outPath) : OutputStream.nullOutputStream();
        outWriter = new BufferedWriter(new OutputStreamWriter(os, StandardCharsets.ISO_8859_1));

        mainLogic();

        outWriter.flush();
        outWriter.close();
    }

    private void mainLogic() throws Exception {
        // OPEN INPUT IN-FILE / OPEN OUTPUT OUT-FILE already done
        readNext();
        while (!wsEofFlag.equals("Y")) {
            if (wsFirstRec.equals("Y")) {
                wsPrevAcct = custAcct;
                wsFirstRec = "Y"; // as in source: MOVE "Y" TO WS-FIRST-REC then MOVE "N"
                wsFirstRec = "N";
            }
            if (!custAcct.equals(wsPrevAcct)) {
                writeSubtotal();
                wsPrevAcct = custAcct;
                wsGroupTotal = BigDecimal.ZERO;
                wsGroupCount = 0;
            }
            processRecord();
            readNext();
        }
        if (wsGroupCount > 0) {
            writeSubtotal();
        }
        writeTrailer();
        // CLOSE
    }

    private void readNext() {
        if (inIndex >= inLines.size()) {
            wsEofFlag = "Y";
            return;
        }
        String rec = inLines.get(inIndex++);
        // Pad/truncate to IN_REC_LEN with spaces (GnuCOBOL LINE SEQUENTIAL pads)
        rec = padRight(rec, IN_REC_LEN);
        if (rec.length() > IN_REC_LEN) rec = rec.substring(0, IN_REC_LEN);
        custAcct = rec.substring(IN_ACCT_OFF, IN_ACCT_OFF + IN_ACCT_LEN);
        custName = rec.substring(IN_NAME_OFF, IN_NAME_OFF + IN_NAME_LEN);
        String sAmt = rec.substring(IN_TXN_AMT_OFF, IN_TXN_AMT_OFF + IN_TXN_AMT_LEN);
        String sLim = rec.substring(IN_DAILY_LIM_OFF, IN_DAILY_LIM_OFF + IN_DAILY_LIM_LEN);
        txnType = rec.substring(IN_TXN_TYPE_OFF, IN_TXN_TYPE_OFF + IN_TXN_TYPE_LEN);
        String sCnt = rec.substring(IN_TXN_COUNT_OFF, IN_TXN_COUNT_OFF + IN_TXN_COUNT_LEN);
        txnAmount = parsePic9V99(sAmt, 5, 2);
        dailyLimit = parsePic9V99(sLim, 5, 2);
        txnCount = parseIntSafe(sCnt);
        wsEofFlag = "N";
    }

    private void processRecord() throws Exception {
        wsApproved = BigDecimal.ZERO;
        wsStatus = padRight("", OUT_STATUS_LEN);
        wsRemainLimit = dailyLimit.subtract(wsGroupTotal);
        if (wsRemainLimit.compareTo(BigDecimal.ZERO) < 0) wsRemainLimit = BigDecimal.ZERO;

        if (txnType.equals("WDR ")) {
            if (txnAmount.compareTo(dailyLimit) > 0) {
                wsStatus = padRight("OVER LIMIT", OUT_STATUS_LEN);
                wsApproved = BigDecimal.ZERO;
            } else {
                if (txnAmount.compareTo(wsRemainLimit) > 0) {
                    wsStatus = padRight("DENIED", OUT_STATUS_LEN);
                    wsApproved = BigDecimal.ZERO;
                } else {
                    wsStatus = padRight("APPROVED", OUT_STATUS_LEN);
                    wsApproved = txnAmount;
                    wsGroupTotal = wsGroupTotal.add(wsApproved);
                    wsGrandTotal = wsGrandTotal.add(wsApproved);
                }
            }
        } else {
            if (txnType.equals("DEP ")) {
                wsStatus = padRight("DEPOSIT", OUT_STATUS_LEN);
                wsApproved = txnAmount;
                // ADD 0 TO WS-GROUP-TOTAL (no effect)
                wsGrandTotal = wsGrandTotal.add(txnAmount);
            } else {
                wsStatus = padRight("INQUIRY", OUT_STATUS_LEN);
                wsApproved = BigDecimal.ZERO;
            }
        }
        wsGroupCount += 1;
        wsGrandCount += 1;
        wsRemainLimit = dailyLimit.subtract(wsGroupTotal);
        if (wsRemainLimit.compareTo(BigDecimal.ZERO) < 0) wsRemainLimit = BigDecimal.ZERO;

        outAcct = padRight(wsPrevAcct, OUT_ACCT_LEN);
        outName = padRight(custName, OUT_NAME_LEN);
        outStatus = padRight(wsStatus, OUT_STATUS_LEN);
        outApprovedAmt = wsApproved;
        outRemainLimit = wsRemainLimit;
        outGroupTotal = wsGroupTotal;
        writeGen0059ORec();
    }

    private void writeSubtotal() throws Exception {
        outAcct = padRight(wsPrevAcct, OUT_ACCT_LEN);
        outName = padRight("*SUBTOTAL*", OUT_NAME_LEN);
        outStatus = padRight("SUBTOTAL", OUT_STATUS_LEN);
        outApprovedAmt = BigDecimal.ZERO;
        outRemainLimit = BigDecimal.ZERO;
        outGroupTotal = wsGroupTotal;
        writeGen0059ORec();
    }

    private void writeTrailer() throws Exception {
        outAcct = padRight("TRAILER", OUT_ACCT_LEN);
        outName = padRight("FINAL TOTAL", OUT_NAME_LEN);
        outStatus = padRight("TRAILER", OUT_STATUS_LEN);
        // MOVE WS-GRAND-COUNT TO OUT-APPROVED-AMT (PIC 9(05)V99) -> value as  integer with 2 decimals = grandCount
        outApprovedAmt = new BigDecimal(wsGrandCount);
        outRemainLimit = BigDecimal.ZERO;
        outGroupTotal = wsGrandTotal;
        writeGen0059ORec();
    }

    private void writeGen0059ORec() throws Exception {
        StringBuilder sb = new StringBuilder(OUT_REC_LEN);
        sb.append(padRight(outAcct, OUT_ACCT_LEN));
        sb.append(padRight(outName, OUT_NAME_LEN));
        sb.append(padRight(outStatus, OUT_STATUS_LEN));
        sb.append(formatPic9V99(outApprovedAmt, 5, 2, OUT_APPROVED_LEN));
        sb.append(formatPic9V99(outRemainLimit, 5, 2, OUT_REMAIN_LEN));
        sb.append(formatPic9V99(outGroupTotal, 7, 2, OUT_GROUP_TOTAL_LEN));
        String line = sb.toString();
        if (line.length() > OUT_REC_LEN) line = line.substring(0, OUT_REC_LEN);
        outWriter.write(line);
        outWriter.write(System.lineSeparator());
    }

    // Helpers
    private static String padRight(String s, int len) {
        if (s == null) s = "";
        if (s.length() > len) return s.substring(0, len);
        StringBuilder sb = new StringBuilder(len);
        sb.append(s);
        while (sb.length() < len) sb.append(' ');
        return sb.toString();
    }

    private static BigDecimal parsePic9V99(String field, int intDigits, int decDigits) {
        if (field == null) return BigDecimal.ZERO;
        String t = field.trim();
        if (t.isEmpty()) return BigDecimal.ZERO;
        // If contains '.' or ',' treat as decimal
        if (t.contains(".") || t.contains(",")) {
            t = t.replace(",", "");
            try { return new BigDecimal(t).setScale(decDigits, RoundingMode.UNNECESSARY); } catch (Exception e) { }
        }
        // Otherwise digits with implied decimal
        String digits = t.replaceAll("[^0-9-]", "");
        if (digits.isEmpty()) return BigDecimal.ZERO;
        boolean neg = digits.startsWith("-");
        if (neg) digits = digits.substring(1);
        digits = digits.replaceAll("^0+", "");
        if (digits.isEmpty()) digits = "0";
        BigDecimal val = new BigDecimal(digits);
        BigDecimal divisor = BigDecimal.TEN.pow(decDigits);
        val = val.divide(divisor, decDigits, RoundingMode.UNNECESSARY);
        if (neg) val = val.negate();
        return val;
    }

    private static int parseIntSafe(String s) {
        try { return Integer.parseInt(s.trim()); } catch (Exception e) { return 0; }
