        // But easier: if abs >= 10^intDigits then take abs % 10^intDigits + fractional
        if (abs.compareTo(limit) >= 0) {
            BigDecimal intPart = abs.setScale(0, RoundingMode.DOWN);
            BigDecimal fracPart = abs.subtract(intPart);
            BigDecimal intTrunc = intPart.remainder(limit);
            abs = intTrunc.add(fracPart);
            truncated = negative ? abs.negate() : abs;
            truncated = truncated.setScale(decDigits, RoundingMode.DOWN);
        }
        return truncated;
    }

    private static String formatPic9V99(BigDecimal v, int intDigits, int decDigits) {
        // Unsigned: format as zero-padded digits intDigits+decDigits
