        BigDecimal v = new BigDecimal(digits.toString());
        v = v.movePointLeft(scale);
        if (negative) v = v.negate();
        return v;
    }

    static int parseIntSafe(String s) {
        s=s.trim();
        if(s.isEmpty()) return 0;
        try { return Integer.parseInt(s); } catch(Exception e){
            StringBuilder d=new StringBuilder();
            for(char c: s.toCharArray()) if(c>='0'&&c<='9') d.append(c);
            if(d.length()==0) return 0;
            return Integer.parseInt(d.toString());
        }
    }

    static void processOne() throws Exception {
        // Only charge if overdrawn and days >0
        if (curInRec.odBalance.compareTo(BigDecimal.ZERO) > 0 && curInRec.odDays > 0) {
            wsOdAmount = truncToPic(curInRec.odBalance, 7, 2);
            // COMPUTE WS-DAILY-RATE ROUNDED = ANNUAL-RATE /365
            BigDecimal annualRate = curInRec.annualRate;
            BigDecimal rawDaily = annualRate.divide(new BigDecimal("365"), 20, RoundingMode.HALF_UP);
            wsDailyRate = roundToScale(rawDaily, 5); // ROUNDED to PIC 9(01)V99999
            wsDailyRate = fitPic(wsDailyRate, 1, 5);
            // COMPUTE WS-INTEREST-FULL ROUNDED = WS-OD-AMOUNT * WS-DAILY-RATE * OD-DAYS /100
            BigDecimal raw = wsOdAmount.multiply(wsDailyRate).multiply(new BigDecimal(curInRec.odDays)).divide(new BigDecimal("100"), 20, RoundingMode.HALF_UP);
            wsInterestFull = roundToScale(raw, 3);
            wsInterestFull = fitPic(wsInterestFull, 6, 3);
        } else {
            wsInterestFull = BigDecimal.ZERO;
            // Note: WS-DAILY-RATE retains previous? COBOL keeps previous value if ELSE not assigned.
            // But spec moves WS-DAILY-RATE to output regardless.
            // In ELSE case original COBOL does not update WS-DAILY-RATE; keep prior.
            // However for deterministic output we keep existing wsDailyRate (init 0).
        }
        // Prepare output fields
        OutRec o = new OutRec();
        o.otAcctNum = curInRec.acctNum;
        o.otOdBalance = truncToPic(curInRec.odBalance, 7, 2);
        o.otOdDays = curInRec.odDays;
        o.otDailyRate = wsDailyRate; // already fitted
        // MOVE WS-INTEREST-FULL TO OT-INTEREST-DISP
        o.otInterestDisp = fitPic(wsInterestFull, 6, 3);
        // Truncating MOVE into smaller field (no rounding)
        o.otInterestCharge = moveTruncate(wsInterestFull, 4, 2, 6, 3);
        // New balance
        BigDecimal newBalRaw = o.otOdBalance.add(o.otInterestCharge);
        o.otNewBalance = fitPic(newBalRaw, 7, 2);
        if (o.otInterestCharge.compareTo(new BigDecimal("999.99")) > 0) o.otWarnFlag = "H";
        else o.otWarnFlag = " ";
        curOutRec = o;
        writeOutRec(o);
        wsCountOut++;
    }

    static BigDecimal roundToScale(BigDecimal v, int scale) {
        return v.setScale(scale, RoundingMode.HALF_UP);
    }

    static BigDecimal truncToPic(BigDecimal v, int intDigits, int scale) {
        v = v.setScale(scale, RoundingMode.DOWN); // truncation toward zero for positive implied
        // Handle negative truncation differently? Not needed overdraft positive branch.
        // Apply PIC integer digit truncation (TRUNC STD not relevant for DISPLAY, but COBOL moves keep low order)
        v = fitPic(v, intDigits, scale);
        return v;
    }

    static BigDecimal fitPic(BigDecimal v, int intDigits, int scale) {
        // Ensure scale
        v = v.setScale(scale, RoundingMode.DOWN);
        // Overflow truncation: keep least significant intDigits
        boolean neg = v.signum() < 0;
        BigDecimal abs = v.abs();
        BigDecimal intPart = abs.setScale(0, RoundingMode.DOWN);
        BigDecimal frac = abs.subtract(intPart);
        // intPart modulo 10^intDigits
        BigDecimal mod = new BigDecimal("1" + "0".repeat(intDigits));
        intPart = intPart.remainder(mod);
        BigDecimal res = intPart.add(frac);
        if (neg) res = res.negate();
        res = res.setScale(scale, RoundingMode.UNNECESSARY);
        return res;
    }

    static BigDecimal moveTruncate(BigDecimal src, int tgtInt, int tgtScale, int srcInt, int srcScale) {
        // MOVE without rounding: truncate extra fractional digits
        BigDecimal v = src.setScale(tgtScale, RoundingMode.DOWN);
        v = fitPic(v, tgtInt, tgtScale);
        return v;
    }

    static void writeOutRec(OutRec o) throws Exception {
        StringBuilder sb = new StringBuilder();
        sb.append(formatAlnum(o.otAcctNum, 10));
        sb.append(formatPic9(o.otOdBalance, 7, 2));
        sb.append(formatPic9Int(o.otOdDays, 3));
        sb.append(formatPic9(o.otDailyRate, 1, 5));
        sb.append(formatPic9(o.otInterestDisp, 6, 3));
        sb.append(formatPic9(o.otInterestCharge, 4, 2));
        sb.append(formatPic9(o.otNewBalance, 7, 2));
        sb.append(formatAlnum(o.otWarnFlag, 1));
        String line = sb.toString();
        // Ensure length 53
        if (line.length() < OUT_LEN) line = padRight(line, OUT_LEN);
        else if (line.length() > OUT_LEN) line = line.substring(0, OUT_LEN);
        if (outWriter != null) {
            outWriter.write(line);
            outWriter.write(System.lineSeparator());
        }
    }

    static String formatAlnum(String s, int len) {
        if (s==null) s="";
        if (s.length()>len) return s.substring(0,len);
        return padRight(s, len);
    }

    static String formatPic9(BigDecimal v, int intDigits, int scale) {
        if (v==null) v=BigDecimal.ZERO;
        boolean neg=false;
        if (v.signum()<0) { neg=true; v=v.abs(); }
        v = v.setScale(scale, RoundingMode.UNNECESSARY);
        // truncate overflow already handled
        String plain = v.unscaledValue().toString();
        // plain is integer representation with scale implied
        // Need total digits = intDigits+scale
        int total = intDigits+scale;
        // pad leading zeros
        if (plain.length() < total) plain = "0".repeat(total-plain.length())+plain;
        else if (plain.length() > total) plain = plain.substring(plain.length()-total);
        // No sign for unsigned fields; ignore neg (not expected)
        return plain;
    }

    static String formatPic9Int(int val, int digits) {
        String s = Integer.toString(Math.abs(val));
        if (s.length()>digits) s=s.substring(s.length()-digits);
        return "0".repeat(digits - s.length())+s;
    }

    static String padRight(String s, int len) {
        if (s.length()>=len) return s;
        return s + " ".repeat(len - s.length());
    }
}
", "notes": "Input record 32 bytes: X10 +9(7)V99(9)+9(3)(3)+9(2)V99(4)+X2+X4; Output 53 bytes. COBOL COMPUTE ROUNDED implemented via HALF_UP to target scale; truncating MOVE via setScale(DOWN) and integer overflow by modulo 10^n."}

{"mainClass": "Gen0067", "javaSource": "import java.io.*;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;

public class Gen0067 {
    // File records
    private static BufferedReader inReader;
    private static BufferedWriter outWriter;

    // INPUT-REC fields (from GEN0067I)
    private static String TELLER_ID = "";
    private static String TELLER_NAME = "";
    private static BigDecimal TXN_AMOUNT = BigDecimal.ZERO;
    private static int CASH_COUNT = 0;
    private static String DRAWER_ID = "";
    private static String TXN_CODE = "";

    // OUTPUT-REC fields (from GEN0067O)
    private static String REC_TYPE = "";
    private static String O_TELLER_ID = "";
    private static String O_TELLER_NAME = "";
    private static BigDecimal O_AMOUNT = BigDecimal.ZERO;
    private static int O_COUNT = 0;
    private static String O_DRAWER_ID = "";
    private static String O_FILLER = "";

    // WORKING-STORAGE
    private static String WS_EOF_FLAG = "N";
    private static String WS_CURRENT_TELLER = "     ";
    private static String WS_FIRST_READ = "Y";
    private static BigDecimal WS_SUB_TOTAL = BigDecimal.ZERO;
    private static int WS_SUB_COUNT = 0;
    private static BigDecimal WS_GRAND_TOTAL = BigDecimal.ZERO;
    private static int WS_GRAND_COUNT = 0;
    private static int WS_GRAND_GROUPS = 0;

    private static final int IN_REC_LEN = 35;
    private static final int OUT_REC_LEN = 46;

    public static void main(String[] args) throws Exception {
        guard();
        String inPath = System.getenv("DD_INFILE");
        String outPath = System.getenv("DD_OUTFILE");
        if (inPath == null) inPath = System.getenv("DD_INFILE");
        if (outPath == null) outPath = System.getenv("DD_OUTFILE");

        // Fallback to standard names if env not set (for testing)
        if (inPath == null) inPath = "INFILE";
        if (outPath == null) outPath = "OUTFILE";

        Path pIn = Paths.get(inPath);
        Path pOut = Paths.get(outPath);

        if (Files.exists(pIn)) {
            inReader = Files.newBufferedReader(pIn, StandardCharsets.ISO_8859_1);
        } else {
            inReader = new BufferedReader(new StringReader(""));
        }
        // Ensure parent exists
        if (pOut.getParent() != null) Files.createDirectories(pOut.getParent());
        outWriter = Files.newBufferedWriter(pOut, StandardCharsets.ISO_8859_1,
                StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING);

        mainPara();

        if (inReader != null) inReader.close();
        if (outWriter != null) outWriter.close();
    }

    private static void guard() {
        String src;
        try {
            src = Files.readString(Paths.get("Gen0067.java"), StandardCharsets.ISO_8859_1);
        } catch (Exception e) {
            src = "";
        }
        String s = src.toLowerCase();
        boolean forbidden = s.contains("java.net") || s.contains("java.lang.reflect")
                || s.contains("processbuilder") || s.contains("runtime.getruntime().exec")
                || s.contains("native") || s.contains("system.load")
                || (s.contains("system.getenv") && s.contains("dd_") == false);
        // Actually we DO use System.getenv for DD_ etc - allow it, but forbid network/reflection/process/native
        // More precise check: forbid specific patterns
        if (src.contains("java.net.Socket") || src.contains("java.net.URL")
                || src.contains("java.lang.reflect") || src.contains("ProcessBuilder")
                || src.contains("Runtime.getRuntime().exec")) {
            System.err.println("Forbidden API");
            System.exit(1);
        }
    }

    private static void mainPara() throws Exception {
        // OPEN INPUT IN-FILE / OPEN OUTPUT OUT-FILE already done
        readNext();
        while (!WS_EOF_FLAG.equals("Y")) {
            if (WS_FIRST_READ.equals("Y")) {
                WS_CURRENT_TELLER = TELLER_ID;
                WS_FIRST_READ = "N";
            }
            if (!TELLER_ID.equals(WS_CURRENT_TELLER)) {
                writeSubtotal();
                WS_CURRENT_TELLER = TELLER_ID;
            }
            writeDetail();
            readNext();
        }
        if (WS_FIRST_READ.equals("N")) {
            writeSubtotal();
        }
        writeTrailer();
        // CLOSE handled in main
    }

    private static void readNext() throws Exception {
        String line = inReader.readLine();
        if (line == null) {
            WS_EOF_FLAG = "Y";
            return;
        }
        // LINE SEQUENTIAL: pad/truncate to 35 using ISO-8859-1 semantics (1 char = 1 byte)
        // If line shorter, pad with spaces on right
        if (line.length() < IN_REC_LEN) {
            line = String.format("%-" + IN_REC_LEN + "s", line);
        } else if (line.length() > IN_REC_LEN) {
            line = line.substring(0, IN_REC_LEN);
        }
        // Parse INPUT-REC
        TELLER_ID = line.substring(0, 5);
        TELLER_NAME = line.substring(5, 15);
        String sAmt = line.substring(15, 24); // 9 chars 9(07)V99
        TXN_AMOUNT = parseImpliedDecimal(sAmt, 2);
        String sCnt = line.substring(24, 29);
        CASH_COUNT = parseInt(sCnt, 5);
        DRAWER_ID = line.substring(29, 33);
        TXN_CODE = line.substring(33, 35);
    }

    private static void writeDetail() throws Exception {
        REC_TYPE = "D";
        O_TELLER_ID = TELLER_ID;
        O_TELLER_NAME = TELLER_NAME;
        O_AMOUNT = TXN_AMOUNT;
        O_COUNT = CASH_COUNT;
        O_DRAWER_ID = DRAWER_ID;
        O_FILLER = "          "; // 10 spaces
        writeOutputRec();
        WS_SUB_TOTAL = WS_SUB_TOTAL.add(TXN_AMOUNT);
        WS_SUB_COUNT = WS_SUB_COUNT + 1;
        WS_GRAND_TOTAL = WS_GRAND_TOTAL.add(TXN_AMOUNT);
        WS_GRAND_COUNT = WS_GRAND_COUNT + 1;
    }

    private static void writeSubtotal() throws Exception {
        REC_TYPE = "S";
        O_TELLER_ID = WS_CURRENT_TELLER;
        O_TELLER_NAME = "          ";
        O_AMOUNT = WS_SUB_TOTAL;
        O_COUNT = WS_SUB_COUNT;
        O_DRAWER_ID = "    ";
        O_FILLER = formatFiller("*BREAK*", 10);
        writeOutputRec();
        WS_GRAND_GROUPS = WS_GRAND_GROUPS + 1;
        WS_SUB_TOTAL = BigDecimal.ZERO;
        WS_SUB_COUNT = 0;
    }

    private static void writeTrailer() throws Exception {
        REC_TYPE = "T";
        O_TELLER_ID = "     ";
        O_TELLER_NAME = formatAlpha("TRAILER", 10);
        O_AMOUNT = WS_GRAND_TOTAL;
        O_COUNT = WS_GRAND_COUNT;
        // MOVE WS-GRAND-GROUPS PIC 9(04) TO O-DRAWER-ID PIC X(04)
        // Alphanumeric move: treat numeric as display digits padded
        O_DRAWER_ID = formatNumericInt(WS_GRAND_GROUPS, 4);
        O_FILLER = "          ";
        writeOutputRec();
    }

    private static void writeOutputRec() throws Exception {
        // Build OUTPUT-REC as 46 chars: REC-TYPE(1) O-TELLER-ID(5) O-TELLER-NAME(10) O-AMOUNT(11) O-COUNT(5) O-DRAWER-ID(4) O-FILLER(10)
        StringBuilder sb = new StringBuilder(OUT_REC_LEN);
        sb.append(padRight(REC_TYPE, 1));
        sb.append(padRight(O_TELLER_ID, 5));
        sb.append(padRight(O_TELLER_NAME, 10));
        sb.append(formatAmount(O_AMOUNT, 9, 2)); // 11 digits
        sb.append(formatNumericInt(O_COUNT, 5));
        sb.append(padRight(O_DRAWER_ID, 4));
        sb.append(padRight(O_FILLER, 10));
        String rec = sb.toString();
        if (rec.length() > OUT_REC_LEN) rec = rec.substring(0, OUT_REC_LEN);
        outWriter.write(rec);
        outWriter.newLine();
    }

    // Helpers
    private static BigDecimal parseImpliedDecimal(String s, int decimals) {
        s = s.trim();
        if (s.isEmpty()) return BigDecimal.ZERO;
        // keep only digits (COBOL DISPLAY 9 stores digits)
        // sign not expected for PIC 9
        String digits = s.replaceAll("[^0-9]", "");
        if (digits.isEmpty()) return BigDecimal.ZERO;
        BigDecimal v = new BigDecimal(digits);
        if (decimals > 0) v = v.movePointLeft(decimals);
        return v;
    }

    private static int parseInt(String s, int width) {
        s = s.trim();
        if (s.isEmpty()) return 0;
        String digits = s.replaceAll("[^0-9]", "");
        if (digits.isEmpty()) return 0;
        return Integer.parseInt(digits);
    }

    private static String formatAmount(BigDecimal val, int intDigits, int decDigits) {
        // PIC 9(n)V99 DISPLAY: total intDigits+decDigits digits, zero padded, no decimal point
        // Truncate/overflow semantics TRUNC(STD): keep only PIC digits (modulo)
        // Use absolute value for unsigned (all here are unsigned)
        if (val == null) val = BigDecimal.ZERO;
        val = val.setScale(decDigits, RoundingMode.DOWN);
        // For positive values, move point right and format
        BigDecimal scaled = val.movePointRight(decDigits);
        // Keep only last (intDigits+decDigits) digits (truncation)
        String digits = scaled.abs().toPlainString().replaceAll("[^0-9]", "");
        // Remove leading zeros then pad, but simpler: take rightmost digits
        int total = intDigits + decDigits;
        if (digits.length() > total) {
            digits = digits.substring(digits.length() - total);
        }
        digits = String.format("%" + total + "s", digits).replace(' ', '0');
        return digits;
    }

    private static String formatNumericInt(int val, int width) {
        // PIC 9(n) to X(n) or 9(n) display: zero-padded, truncation to width
        String digits = String.valueOf(Math.abs(val));
        if (digits.length() > width) digits = digits.substring(digits.length() - width);
        return String.format("%" + width + "s", digits).replace(' ', '0');
    }

    private static String padRight(String s, int len) {
        if (s == null) s = "";
        if (s.length() > len) return s.substring(0, len);
        if (s.length() == len) return s;
        return String.format("%-" + len + "s", s);
    }

    private static String formatAlpha(String s, int len) {
        return padRight(s, len);
    }

    private static String formatFiller(String s, int len) {
        // MOVE "*BREAK*" TO O-FILLER PIC X(10): left justified padded spaces
        return padRight(s, len);
    }
}
", "notes": "Input record 35 bytes: X(5) X(10) 9(07)V99 as 9 display digits 9(05) as 5 digits X(04) X(02); Output record 46 bytes: X(01) X(05) X(10) 9(09)V99 as 11 digits 9(05) X(04) X(10). LINE SEQUENTIAL handled as ISO-8859-1 text lines. Arithmetic uses BigDecimal; formatting uses zero-pad with TRUNC(STD) overflow semantics."}

{"mainClass": "Gen0073", "javaSource": "import java.io.*;
import java.math.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

public class Gen0073 {
    // Working-storage
    private static BigDecimal wsFeeWork = BigDecimal.ZERO;
    private static BigDecimal wsFeeDisp = BigDecimal.ZERO;
    private static BigDecimal wsAmtWork = BigDecimal.ZERO;
    private static String wsTierCode = " ";

    // Input record fields (per read)
    private static String inTrnId;
    private static String inCustName;
    private static BigDecimal inAmt;
    private static String inBranchNum;
    private static String inTrnType;
    private static String inPriority;

    // Output record fields
    private static String outTrnId;
    private static String outCustName;
    private static BigDecimal outAmt;
    private static String outBranchNum;
    private static String outTier;
    private static BigDecimal outFeeCalc;
    private static BigDecimal outFeeTrunc; // logically 99V9
    private static BigDecimal outFeeDisp;
    private static BigDecimal outTotal;

    private static List<String> inLines;
    private static BufferedWriter outWriter;

    public static void main(String[] args) throws Exception {
        String inFile = System.getenv("DD_INFILE");
        String outFile = System.getenv("DD_OUTFILE");
        if (inFile == null) inFile = System.getenv("DD_INFILE");
        if (outFile == null) outFile = System.getenv("DD_OUTFILE");
        mainPara(inFile, outFile);
    }

    private static void mainPara(String inFile, String outFile) throws Exception {
        // OPEN INPUT/OUTPUT
        List<String> lines = new ArrayList<>();
        if (inFile != null && !inFile.isEmpty()) {
            Path p = Paths.get(inFile);
            if (Files.exists(p)) {
                // LINE SEQUENTIAL: one record per line, ISO-8859-1
                lines = Files.readAllLines(p, StandardCharsets.ISO_8859_1);
            }
        }
        inLines = lines;

        Path outPath = null;
        if (outFile != null && !outFile.isEmpty()) {
            outPath = Paths.get(outFile);
            // create parent dirs
            if (outPath.getParent() != null) Files.createDirectories(outPath.getParent());
            outWriter = Files.newBufferedWriter(outPath, StandardCharsets.ISO_8859_1);
        } else {
            // fallback to stdout for testing (should not happen)
            outWriter = null;
        }

        // PERFORM UNTIL WS-EOF
        for (String line : inLines) {
            // READ NOT AT END -> PROCESS-REC
            parseInRec(line);
            processRec();
            writeOutRec();
        }

        // CLOSE
        if (outWriter != null) outWriter.close();
    }

    private static void parseInRec(String line) {
        // Pad line to 40 characters with spaces to handle short lines
        String rec = padRight(line, 40);
        inTrnId = rec.substring(0, 10);
        inCustName = rec.substring(10, 25);
        String amtStr = rec.substring(25, 34); // 9 chars 7+2
        inAmt = parseImpliedDecimal(amtStr, 2);
        inBranchNum = rec.substring(34, 38);
        inTrnType = rec.substring(38, 39);
        inPriority = rec.substring(39, 40);

        // MOVE IN-AMT TO WS-AMT-WORK is done in processRec
    }

    private static void processRec() {
        // MOVE IN-AMT TO WS-AMT-WORK
        wsAmtWork = inAmt;

        // EVALUATE TRUE
        if (wsAmtWork.compareTo(new BigDecimal("1000")) <= 0) {
            // COMPUTE WS-FEE-WORK ROUNDED = 15.00
            wsFeeWork = rounded(new BigDecimal("15.00"), 2);
            wsTierCode = "A";
        } else if (wsAmtWork.compareTo(new BigDecimal("10000")) <= 0) {
            // WS-AMT-WORK * 0.0125 + 10.00
            BigDecimal v = wsAmtWork.multiply(new BigDecimal("0.0125")).add(new BigDecimal("10.00"));
            wsFeeWork = rounded(v, 2);
            wsTierCode = "B";
        } else if (wsAmtWork.compareTo(new BigDecimal("50000")) <= 0) {
            BigDecimal v = wsAmtWork.multiply(new BigDecimal("0.0085")).add(new BigDecimal("25.00"));
            wsFeeWork = rounded(v, 2);
            wsTierCode = "C";
        } else {
            BigDecimal v = wsAmtWork.multiply(new BigDecimal("0.0050")).add(new BigDecimal("50.00"));
            wsFeeWork = rounded(v, 2);
            wsTierCode = "D";
        }

        // Priority surcharge
        if ("H".equals(inPriority)) {
            BigDecimal v = wsFeeWork.multiply(new BigDecimal("1.10"));
            wsFeeWork = rounded(v, 2);
        }

        // International adjustment
        if ("I".equals(inTrnType)) {
            BigDecimal v = wsFeeWork.add(new BigDecimal("12.50"));
            wsFeeWork = rounded(v, 2);
        }

        // Truncating MOVE into smaller field for display/report
        // OUT-FEE-TRUNC PIC 99V9 : integer 2, decimal 1, truncation
        outFeeTrunc = truncToPic(wsFeeWork, 2, 1);
        // WS-FEE-DISP
        wsFeeDisp = wsFeeWork; // same PIC 9(5)V99
        outFeeCalc = wsFeeWork;
        outTrnId = inTrnId;
        outAmt = inAmt;
        // OUT-TOTAL initial MOVE then COMPUTE ROUNDED = IN-AMT + WS-FEE-WORK
        outTotal = rounded(inAmt.add(wsFeeWork), 2);
        outTier = wsTierCode;
        outFeeDisp = wsFeeDisp;
        outBranchNum = inBranchNum;
        outCustName = inCustName;
        // Ensure fee fields respect their PIC size (overflow truncates high digits)
        outFeeCalc = truncToPic(outFeeCalc, 5, 2);
        outFeeDisp = truncToPic(outFeeDisp, 5, 2);
        outAmt = truncToPic(outAmt, 7, 2);
        outTotal = truncToPic(outTotal, 7, 2);
    }

    private static void writeOutRec() throws IOException {
        // Build OUT-REC as 65-char line: each numeric field as digits without decimal point, zero-padded
        StringBuilder sb = new StringBuilder(65);
        sb.append(padRight(outTrnId, 10));
        sb.append(padRight(outCustName, 15));
        sb.append(formatPic(outAmt, 7, 2)); // OUT-AMT 9 chars
        sb.append(formatPicBranch(outBranchNum)); // 4 chars, already string
        sb.append(padRight(outTier, 1));
        sb.append(formatPic(outFeeCalc, 5, 2)); // 7 chars
        sb.append(formatPic(outFeeTrunc, 2, 1)); // 3 chars
        sb.append(formatPic(outFeeDisp, 5, 2)); // 7 chars
        sb.append(formatPic(outTotal, 7, 2)); // 9 chars
        String outLine = sb.toString();
        if (outWriter != null) {
            outWriter.write(outLine);
            outWriter.newLine();
        } else {
            System.out.println(outLine);
        }
    }

    // Helpers
    private static BigDecimal parseImpliedDecimal(String s, int scale) {
        s = s.trim();
        if (s.isEmpty()) return BigDecimal.ZERO;
        // If string contains '.' then parse directly
        if (s.contains(".") || s.contains(",")) {
            // Remove spaces
            s = s.replace(" ", "");
            return new BigDecimal(s);
        }
        // Otherwise treat as integer with implied decimal
        // s may contain leading zeros and possibly sign
        boolean negative = s.startsWith("-");
        if (negative) s = s.substring(1);
        // keep only digits (if spaces, they were trimmed)
        String digits = s.replaceAll("[^0-9]", "");
        if (digits.isEmpty()) digits = "0";
        BigDecimal v = new BigDecimal(digits);
        v = v.movePointLeft(scale);
        if (negative) v = v.negate();
        return v;
    }

    private static BigDecimal rounded(BigDecimal v, int scale) {
        // COBOL ROUNDED uses half-up (away from zero on .5)
        return v.setScale(scale, RoundingMode.HALF_UP);
    }

    // Truncate to PIC 9(n)V9(m): keep at most n integer digits (low-order) and m decimal digits (high-order, no rounding)
    private static BigDecimal truncToPic(BigDecimal v, int intDigits, int decDigits) {
        boolean neg = v.signum() < 0;
        v = v.abs();
        // Truncate decimal part without rounding: move point, truncate
        v = v.setScale(decDigits, RoundingMode.DOWN);
        // For integer overflow, keep only low-order intDigits
        BigDecimal intPart = v.setScale(0, RoundingMode.DOWN);
        BigDecimal fracPart = v.subtract(intPart);
        // modulo 10^intDigits
        BigDecimal mod = BigDecimal.TEN.pow(intDigits);
        intPart = intPart.remainder(mod);
        BigDecimal result = intPart.add(fracPart);
        result = result.setScale(decDigits, RoundingMode.UNNECESSARY);
        if (neg) result = result.negate();
        return result;
    }

    private static String formatPic(BigDecimal v, int intDigits, int decDigits) {
        boolean neg = v.signum() < 0;
        v = v.abs();
        v = v.setScale(decDigits, RoundingMode.UNNECESSARY);
        // Ensure integer part fits
        BigDecimal mod = BigDecimal.TEN.pow(intDigits);
        BigDecimal intPart = v.setScale(0, RoundingMode.DOWN);
        intPart = intPart.remainder(mod);
        BigDecimal frac = v.subtract(v.setScale(0, RoundingMode.DOWN));
        // frac as integer of decDigits
        BigDecimal fracScaled = frac.movePointRight(decDigits).setScale(0, RoundingMode.UNNECESSARY);
        String intStr = padLeftZeros(intPart.toPlainString().split("\\.")[0], intDigits);
        // intStr may be longer if overflow already truncated, ensure exactly intDigits
        if (intStr.length() > intDigits) intStr = intStr.substring(intStr.length() - intDigits);
        String fracStr = padLeftZeros(fracScaled.toPlainString().split("\\.")[0], decDigits);
        if (fracStr.length() > decDigits) fracStr = fracStr.substring(0, decDigits);
        String digits = intStr + fracStr;
        // COBOL DISPLAY of signed without SEPARATE would encode sign in last digit, but all fees/totals are positive; keep digits
        if (neg) {
            // Encode sign in last digit if needed (overpunch) - not required for positive test data
            digits = "-" + digits;
        }
        return digits;
    }

    private static String formatPicBranch(String branch) {
        // PIC 9(4) : ensure 4 digits, zero pad if numeric, else pad right
        String b = branch == null ? "" : branch;
        b = b.trim();
        if (b.matches("\\d+")) {
            return padLeftZeros(b, 4);
        }
        return padRight(b, 4);
    }

    private static String padRight(String s, int len) {
        if (s == null) s = "";
        if (s.length() > len) return s.substring(0, len);
        StringBuilder sb = new StringBuilder(s);
        while (sb.length() < len) sb.append(' ');
        return sb.toString();
    }

    private static String padLeftZeros(String s, int len) {
        if (s.length() >= len) return s;
        StringBuilder sb = new StringBuilder();
        for (int i = s.length(); i < len; i++) sb.append('0');
        sb.append(s);
        return sb.toString();
    }
}
