{"mainClass": "Gen0075", "javaSource": "import java.io.*;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.ArrayList;
import java.util.List;

public class Gen0075 {
    // File records
    static class EscrowShortageRec {
        String eLoanId;
        String eBranchCode;
        String eBorrowerName;
        int eShortageAmt; // 9(07)
        int eSpreadMonths; // 9(03)
        String eEscrowType;
        int ePriorBalance;
    }
    static class EscrowSpreadOutRec {
        String oRecordType; // X01
        String oLoanId; // X10
        String oBranchCode; // X04
        String oBorrowerName; // X20
        int oMonthlyAmt; // 9(05)
        int oRemainingAmt; // 9(07)
        int oRecCount; // 9(09)
        String oFiller; // X10
    }

    // Working storage
    private String wsEofFlag = "N";
    private String wsPrevBranch = "    ";
    private String wsFirstRead = "Y";
    private int wsSubtotalShortage = 0; // 9(09)
    private int wsSubtotalCount = 0; // 9(05)
    private int wsGrandShortage = 0; // 9(11)
    private int wsGrandCount = 0; // 9(09)
    private int wsMonthlyCalc = 0; // 9(05)
    private int wsRemainingCalc = 0; // 9(07)

    // File handling
    private List<String> inLines = new ArrayList<>();
    private int inIndex = 0;
    private EscrowShortageRec currentInRec = null;
    private List<String> outLines = new ArrayList<>();
    private EscrowSpreadOutRec outRec = new EscrowSpreadOutRec();

    // Current input fields (E-...)
    private String eLoanId = "";
    private String eBranchCode = "";
    private String eBorrowerName = "";
    private int eShortageAmt = 0;
    private int eSpreadMonths = 0;

    public static void main(String[] args) throws Exception {
        Gen0075 p = new Gen0075();
        p.mainLogic();
        p.flushOutput();
    }

    private void mainLogic() throws Exception {
        openInput();
        openOutput();
        readInput();
        while (!wsEofFlag.equals("Y")) {
            checkBreak();
            processRecord();
            readInput();
        }
        writeFinalBreak();
        writeTrailer();
        closeFiles();
    }

    private void openInput() throws Exception {
        String path = System.getenv("DD_INFILE");
        if (path == null) path = System.getenv("DD_INFILE");
        if (path != null) {
            Path p = Paths.get(path);
            if (Files.exists(p)) {
                byte[] bytes = Files.readAllBytes(p);
                String content = new String(bytes, StandardCharsets.ISO_8859_1);
                // LINE SEQUENTIAL: split on line breaks, preserve empty lines
                // Use BufferedReader logic to handle \r\n, \n
                BufferedReader br = new BufferedReader(new StringReader(content));
                String line;
                while ((line = br.readLine()) != null) {
                    inLines.add(line);
                }
            }
        }
    }

    private void openOutput() {
        outLines = new ArrayList<>();
    }

    private void closeFiles() {
    }

    private void flushOutput() throws Exception {
        String outPath = System.getenv("DD_OUTFILE");
        if (outPath == null) outPath = System.getenv("DD_OUTFILE");
        if (outPath != null) {
            Path p = Paths.get(outPath);
            // LINE SEQUENTIAL: one record per line with \n (no extra separator handling)
            // Use ISO-8859-1 bytes
            try (BufferedWriter w = Files.newBufferedWriter(p, StandardCharsets.ISO_8859_1)) {
                for (int i = 0; i < outLines.size(); i++) {
                    w.write(outLines.get(i));
                    w.newLine();
                }
            }
        } else {
            // fallback to stdout if not set (should not happen)
            for (String l : outLines) System.out.println(l);
        }
    }

    private void readInput() {
        if (inIndex >= inLines.size()) {
            wsEofFlag = "Y";
            return;
        }
        String line = inLines.get(inIndex++);
        // Pad to 53 if shorter (LINE SEQUENTIAL may have shorter lines)
        if (line.length() < 53) {
            line = String.format("%-53s", line);
        }
        // Parse fixed positions
        // 1-10 loan, 11-14 branch, 15-34 borrower, 35-41 shortage 7, 42-44 spread 3, 45-46 type, 47-53 prior 7
        eLoanId = safeSubstring(line, 0, 10);
        eBranchCode = safeSubstring(line, 10, 14);
        eBorrowerName = safeSubstring(line, 14, 34);
        String sShortage = safeSubstring(line, 34, 41);
        String sSpread = safeSubstring(line, 41, 44);
        // eEscrowType and prior balance not used in logic except for record length
        eShortageAmt = parseNumeric(sShortage, 7);
        eSpreadMonths = parseNumeric(sSpread, 3);
    }

    private void checkBreak() {
        if (wsFirstRead.equals("Y")) {
            wsPrevBranch = eBranchCode;
            wsFirstRead = "N";
        } else {
            // Alphanumeric comparison: if DIOCLE_COLLATION=EBCDIC compare Cp037 bytes
            String coll = System.getenv("DIOCLE_COLLATION");
            boolean ebcdic = "EBCDIC".equals(coll);
            boolean notEqual;
            if (ebcdic) {
                notEqual = compareEbcdic(eBranchCode, wsPrevBranch) != 0;
            } else {
                notEqual = !eBranchCode.equals(wsPrevBranch);
            }
            if (notEqual) {
                writeSubtotal();
                wsPrevBranch = eBranchCode;
                wsSubtotalShortage = 0;
                wsSubtotalCount = 0;
            }
        }
    }

    private void processRecord() {
        if (eSpreadMonths == 0) {
            // MOVE E-SHORTAGE-AMT TO WS-MONTHLY-CALC (PIC 9(05) - truncate to 5 digits if needed)
            wsMonthlyCalc = truncateDigits(eShortageAmt, 5);
            wsRemainingCalc = 0;
        } else {
            // DIVIDE E-SHORTAGE-AMT BY E-SPREAD-MONTHS GIVING WS-MONTHLY-CALC
            // COBOL integer division truncated
            BigDecimal bdShortage = BigDecimal.valueOf(eShortageAmt);
            BigDecimal bdSpread = BigDecimal.valueOf(eSpreadMonths);
            BigDecimal div = bdShortage.divide(bdSpread, 0, RoundingMode.DOWN);
            wsMonthlyCalc = truncateDigits(div.intValue(), 5);
            // MULTIPLY WS-MONTHLY-CALC BY E-SPREAD-MONTHS GIVING WS-REMAINING-CALC
            BigDecimal bdMonthly = BigDecimal.valueOf(wsMonthlyCalc);
            BigDecimal mult = bdMonthly.multiply(bdSpread);
            int multiplied = truncateDigits(mult.intValue(), 7);
            wsRemainingCalc = multiplied;
            // COMPUTE WS-REMAINING-CALC = E-SHORTAGE-AMT - WS-REMAINING-CALC
            BigDecimal result = bdShortage.subtract(BigDecimal.valueOf(wsRemainingCalc));
            wsRemainingCalc = truncateDigits(result.intValue(), 7);
            if (wsRemainingCalc < 0) wsRemainingCalc = 0; // keep TRUNC semantics but shortage >=0 so not negative
        }
        // ADDs with TRUNC(STD) - keep only PIC digits
        wsSubtotalShortage = truncateDigits(wsSubtotalShortage + eShortageAmt, 9);
        wsSubtotalCount = truncateDigits(wsSubtotalCount + 1, 5);
        wsGrandShortage = truncateDigits(wsGrandShortage + eShortageAmt, 11);
        wsGrandCount = truncateDigits(wsGrandCount + 1, 9);

        // MOVE to output
        outRec = new EscrowSpreadOutRec();
        outRec.oRecordType = "D";
        outRec.oLoanId = eLoanId;
        outRec.oBranchCode = eBranchCode;
        outRec.oBorrowerName = eBorrowerName;
        outRec.oMonthlyAmt = wsMonthlyCalc;
        outRec.oRemainingAmt = wsRemainingCalc;
        outRec.oRecCount = wsSubtotalCount;
        outRec.oFiller = "          ";
        writeEscrowSpreadOutRec();
    }

    private void writeSubtotal() {
        outRec = new EscrowSpreadOutRec();
        outRec.oRecordType = "S";
        outRec.oLoanId = "          ";
        outRec.oBranchCode = wsPrevBranch;
        outRec.oBorrowerName = "** SUBTOTAL **";
        outRec.oMonthlyAmt = 0;
        outRec.oRemainingAmt = truncateDigits(wsSubtotalShortage, 7);
        outRec.oRecCount = wsSubtotalCount;
        outRec.oFiller = "          ";
        writeEscrowSpreadOutRec();
    }

    private void writeFinalBreak() {
        if (wsFirstRead.equals("N")) {
            writeSubtotal();
        }
    }

    private void writeTrailer() {
        outRec = new EscrowSpreadOutRec();
        outRec.oRecordType = "T";
        outRec.oLoanId = "TRAILER";
        outRec.oBranchCode = "    ";
        outRec.oBorrowerName = "GRAND TOTAL";
        outRec.oMonthlyAmt = 0;
        outRec.oRemainingAmt = 0;
        outRec.oRecCount = wsGrandCount;
        outRec.oFiller = "          ";
        writeEscrowSpreadOutRec();

        outRec = new EscrowSpreadOutRec();
        outRec.oRecordType = "T";
        outRec.oLoanId = "AMOUNT";
        outRec.oBranchCode = "    ";
        outRec.oBorrowerName = "TOTAL SHORTAGE";
        outRec.oMonthlyAmt = 0;
        outRec.oRemainingAmt = truncateDigits(wsGrandShortage, 7);
        outRec.oRecCount = wsGrandCount;
        outRec.oFiller = "          ";
        writeEscrowSpreadOutRec();
    }

    private void writeEscrowSpreadOutRec() {
        // Build 66-char record
        String rec = formatOutput(outRec);
        outLines.add(rec);
    }

    private String formatOutput(EscrowSpreadOutRec r) {
        StringBuilder sb = new StringBuilder(66);
        sb.append(padRight(r.oRecordType, 1));
        sb.append(padRight(r.oLoanId, 10));
        sb.append(padRight(r.oBranchCode, 4));
        sb.append(padRight(r.oBorrowerName, 20));
        sb.append(padNumeric(r.oMonthlyAmt, 5));
        sb.append(padNumeric(r.oRemainingAmt, 7));
        sb.append(padNumeric(r.oRecCount, 9));
        sb.append(padRight(r.oFiller, 10));
        return sb.toString();
    }

    // Helpers
    private static String safeSubstring(String s, int start, int end) {
        if (start >= s.length()) return "";
        if (end > s.length()) end = s.length();
        return s.substring(start, end);
    }
    private static int parseNumeric(String s, int len) {
        s = s.trim();
        if (s.isEmpty()) return 0;
        // keep only digits, COBOL PIC 9(n) - if non-numeric, treat as 0
        StringBuilder digits = new StringBuilder();
        for (char c : s.toCharArray()) if (c >= '0' && c <= '9') digits.append(c);
        if (digits.length() == 0) return 0;
        try { return Integer.parseInt(digits.toString()); } catch (NumberFormatException e) { return 0; }
    }
    private static String padRight(String s, int len) {
        if (s == null) s = "";
        if (s.length() > len) return s.substring(0, len);
        return String.format("%-" + len + "s", s);
    }
    private static String padNumeric(int v, int len) {
        // DISPLAY of binary field shows PIC digits: zero-padded, keep only last len digits (TRUNC STD)
        int truncated = truncateDigits(v, len);
        String fmt = String.format("%0" + len + "d", truncated);
        if (fmt.length() > len) fmt = fmt.substring(fmt.length() - len);
        return fmt;
    }
    private static int truncateDigits(int value, int digits) {
        if (digits >= 10) return value; // fits int
        int mod = (int) Math.pow(10, digits);
        // TRUNC(STD) keeps lowest digits for overflow; for positive values simple mod
        if (value >= 0) return value % mod;
        // negative not expected here
        return value % mod;
    }
    private static int compareEbcdic(String a, String b) {
        try {
            byte[] ba = a.getBytes("Cp037");
            byte[] bb = b.getBytes("Cp037");
            int len = Math.min(ba.length, bb.length);
            for (int i = 0; i < len; i++) {
                int ca = ba[i] & 0xFF;
                int cb = bb[i] & 0xFF;
                if (ca != cb) return ca - cb;
            }
            return ba.length - bb.length;
        } catch (Exception e) {
            return a.compareTo(b);
        }
    }
}
