        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '-' ) negative = true;
            else if (c >= '0' && c <= '9') digits.append(c);
        }
        if (digits.length() == 0) return BigDecimal.ZERO;
        BigDecimal v = new BigDecimal(digits.toString());
        if (decimals > 0) v = v.movePointLeft(decimals);
        if (negative) v = v.negate();
        return v;
    }

    private static int parseInt(String s) {
        s = s.trim();
        if (s.isEmpty()) return 0;
        try { return Integer.parseInt(s); } catch (NumberFormatException e) {
