    private static String formatImplied(BigDecimal val, int totalDigits, int decimals) {
        // PIC 9(n)V... unsigned, display as zero-padded digits without decimal point
        // Truncate/overflow handling: keep only PIC digits (TRUNC behavior) - use modulo 10^n
        // For simplicity, for positive values we do integer representation = val * 10^decimals rounded/truncated already
        // Then format to totalDigits zero padded, keeping least significant totalDigits
        if (val == null) val = BigDecimal.ZERO;
        boolean negative = val.signum() < 0;
        if (negative) val = val.abs();
        BigDecimal scaled = val.movePointRight(decimals);
        // Ensure integer (should already be)
        scaled = scaled.setScale(0, RoundingMode.UNNECESSARY);
        String s = scaled.toPlainString();
        // Remove decimal part if any (should not)
        // Keep only digits
        StringBuilder digits = new StringBuilder();
        for (char c: s.toCharArray()) if (c>='0' && c<='9') digits.append(c);
        s = digits.toString();
        if (s.length() > totalDigits) {
            s = s.substring(s.length() - totalDigits);
        } else if (s.length() < totalDigits) {
            s = "0".repeat(totalDigits - s.length()) + s;
        }
        // For signed DISPLAY without SEPARATE, would encode sign in last digit - not needed (all unsigned here)
        // If negative, COBOL would show last digit as overpunch; but our fields are unsigned.
        return s;
    }

    private static String padRight(String s, int len) {
        if (s == null) s = "";
        if (s.length() > len) return s.substring(0, len);
        if (s.length() < len) return s + " ".repeat(len - s.length());
        return s;
    }

