        WS_T_RATE[5] = new BigDecimal("2.900");
        WS_T_DESC[5] = "PREMIUM     ";
        WS_T_CODE[6] = "C2";
        WS_T_MIN_BAL[6] = new BigDecimal("100000.00");
        WS_T_RATE[6] = new BigDecimal("3.250");
        WS_T_DESC[6] = "ELITE       ";
        WS_T_CODE[7] = "D1";
        WS_T_MIN_BAL[7] = new BigDecimal("0.00");
        WS_T_RATE[7] = new BigDecimal("0.750");
        WS_T_DESC[7] = "YOUTH       ";
        WS_T_CODE[8] = "D2";
        WS_T_MIN_BAL[8] = new BigDecimal("0.00");
        WS_T_RATE[8] = new BigDecimal("1.000");
        WS_T_DESC[8] = "SENIOR      ";
        WS_TABLE_INIT_DONE = "Y";
    }

    private static void processRecPara() {
        WS_FOUND_FLAG = "N";
        WS_MATCH_RATE = BigDecimal.ZERO;
        WS_MATCH_DESC = "            ";
        // PERFORM VARYING WS-IDX FROM 1 BY 1 UNTIL WS-IDX > 8
        for (WS_IDX = 1; WS_IDX <= 8; WS_IDX++) {
            if (I_TIER_CODE.equals(WS_T_CODE[WS_IDX])) {
                WS_MATCH_RATE = WS_T_RATE[WS_IDX];
                WS_MATCH_DESC = WS_T_DESC[WS_IDX];
                WS_FOUND_FLAG = "Y";
            }
        }
        // After PERFORM, WS_IDX = 9 (COBOL leaves it at 9)
        // Already 9 due to for loop exit
        if (WS_FOUND_FLAG.equals("N")) {
            WS_MATCH_RATE = new BigDecimal("1.000");
            WS_MATCH_DESC = "DEFAULT     ";
        }
        // IF I-BALANCE < WS-T-MIN-BAL(WS-IDX -1) AND WS-FOUND-FLAG='Y'
        // Note: WS_IDX is 9, so index 8
        int checkIdx = WS_IDX - 1;
        if (checkIdx >=1 && checkIdx <=8) {
            if (I_BALANCE.compareTo(WS_T_MIN_BAL[checkIdx]) < 0 && WS_FOUND_FLAG.equals("Y")) {
                WS_MATCH_RATE = BigDecimal.ZERO;
                // COMPUTE WS-MATCH-RATE = WS-MATCH-RATE * 0.5
                WS_MATCH_RATE = WS_MATCH_RATE.multiply(new BigDecimal("0.5"));
            }
        }
        WS_BONUS_RATE = BigDecimal.ZERO;
        if (I_TERM_MONTHS >= 12) {
            WS_BONUS_RATE = new BigDecimal("0.250");
        }
        if (I_TERM_MONTHS >= 24) {
            WS_BONUS_RATE = new BigDecimal("0.500");
        }
        WS_MATCH_RATE = WS_MATCH_RATE.add(WS_BONUS_RATE);
        // COMPUTE WS-CALC-DIVIDEND ROUNDED = I-BALANCE * WS-MATCH-RATE / 100
        BigDecimal raw = I_BALANCE.multiply(WS_MATCH_RATE).divide(new BigDecimal("100"), 10, RoundingMode.HALF_UP);
        WS_CALC_DIVIDEND = raw.setScale(2, RoundingMode.HALF_UP);
        // COMPUTE WS-CALC-NEW-BAL = I-BALANCE + WS-CALC-DIVIDEND
        WS_CALC_NEW_BAL = I_BALANCE.add(WS_CALC_DIVIDEND);
        O_ACCOUNT_NUM = I_ACCOUNT_NUM;
        O_CUSTOMER_NAME = I_CUSTOMER_NAME;
        O_OLD_BALANCE = I_BALANCE;
        O_DIVIDEND_RATE = WS_MATCH_RATE;
        O_DIVIDEND_AMT = WS_CALC_DIVIDEND;
        O_NEW_BALANCE = WS_CALC_NEW_BAL;
        O_TIER_DESC = WS_MATCH_DESC;
        String outRec = buildOutRec();
        outLines.add(outRec);
    }
}
", "notes": "LINE SEQUENTIAL handling: numeric PIC 9(n)V99 fields are stored as zero-padded digit strings without decimal point (implied V). Input record length 57, output 74. PERFORM VARYING leaves WS-IDX=9 so the balance-check uses WS-T-MIN-BAL(8)=0 and is effectively dead code, reproduced faithfully. COMPUTE ROUNDED uses HALF_UP to 2 decimals. BigDecimal used for all arithmetic."}

{"mainClass": "Gen0077", "javaSource": "import java.io.*;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.List;

public class Gen0077 {
    private static final int IN_LEN = 30;
    private static final int OUT_LEN = 43;

    private static int wsCountIn = 0;
    private static int wsCountOut = 0;
    private static int wsCountFlagged = 0;

    private static String wsDormantFlagTmp = "N";
    private static String wsReasonTmp = "  ";
    private static String wsActionTmp = "            ";
    private static String wsCategory = "  ";

    // current input fields
    private static String inAccountId;
    private static String inAccountType;
    private static BigDecimal inBalance;
    private static String inBalanceRaw; // 9 chars
    private static int inLastActDays;
    private static String inLastActDaysRaw; // 4 chars
    private static int inOverdraftCount;
    private static String inBranchCode;

    private static List<String> inLines;
    private static int inIndex = 0;
    private static boolean wsEof = false;
    private static BufferedWriter outWriter;

    public static void main(String[] args) throws Exception {
        String inFile = System.getenv("DD_INFILE");
        String outFile = System.getenv("DD_OUTFILE");
        // DIOCLE_CLOCK / DIOCLE_COLLATION not used by this program but read to satisfy contract
        String clock = System.getenv("DIOCLE_CLOCK");
        String coll = System.getenv("DIOCLE_COLLATION");

        Path inPath = inFile != null ? Paths.get(inFile) : null;
        Path outPath = outFile != null ? Paths.get(outFile) : null;

        if (inPath != null && Files.exists(inPath)) {
            byte[] bytes = Files.readAllBytes(inPath);
            String content = new String(bytes, StandardCharsets.ISO_8859_1);
            // ORGANIZATION LINE SEQUENTIAL: one record per line, split on LF/CRLF, keep empty lines
            // Use BufferedReader approach to preserve exact lines without separators
            inLines = Files.readAllLines(inPath, StandardCharsets.ISO_8859_1);
        } else {
            inLines = List.of();
        }

        if (outPath != null) {
            if (outPath.getParent() != null) Files.createDirectories(outPath.getParent());
            outWriter = Files.newBufferedWriter(outPath, StandardCharsets.ISO_8859_1,
                    StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING);
        } else {
            outWriter = new BufferedWriter(new OutputStreamWriter(System.out, StandardCharsets.ISO_8859_1));
        }

        mainPara();

        if (outWriter != null) outWriter.close();
        // GOBACK with RETURN-CODE 0
        // System.exit not needed for 0
    }

    private static void mainPara() throws IOException {
        // OPEN INPUT INFILE / OPEN OUTPUT OUTFILE already done
        while (!wsEof) {
            // READ INFILE
            if (inIndex >= inLines.size()) {
                wsEof = true;
            } else {
                String rec = inLines.get(inIndex++);
                // LINE SEQUENTIAL fixed length handling: pad/truncate to IN_LEN with spaces (bytes ISO-8859-1)
                // If record longer, truncate to len; if shorter, pad with spaces (COBOL would pad)
                String padded = padRight(rec, IN_LEN);
                if (padded.length() > IN_LEN) padded = padded.substring(0, IN_LEN);
                parseInRec(padded);
                processRec();
            }
        }
        showTotals();
        // CLOSE
    }

    private static void parseInRec(String rec) {
        inAccountId = rec.substring(0, 10);
        inAccountType = rec.substring(10, 12);
        inBalanceRaw = rec.substring(12, 21); // 9 chars 9(07)V99
        inLastActDaysRaw = rec.substring(21, 25); // 9(04)
        String overdraftRaw = rec.substring(25, 27);
        inBranchCode = rec.substring(27, 30);

        // parse balance: 9 digits implicit 2 decimals -> BigDecimal = digits /100
        // Blank handling: if spaces treat as 0
        String bTrim = inBalanceRaw.trim();
        if (bTrim.isEmpty()) bTrim = "0";
        // Ensure numeric; non-numeric spaces -> 0
        try {
            // inBalanceRaw may contain leading zeros; parse as integer
            long v = Long.parseLong(inBalanceRaw.trim().isEmpty() ? "0" : inBalanceRaw);
            inBalance = new BigDecimal(v).movePointLeft(2);
        } catch (NumberFormatException e) {
            // fallback: extract digits
            String digits = inBalanceRaw.replaceAll("[^0-9]", "");
            if (digits.isEmpty()) digits = "0";
            long v = Long.parseLong(digits);
            inBalance = new BigDecimal(v).movePointLeft(2);
        }
        try {
            inLastActDays = Integer.parseInt(inLastActDaysRaw.trim().isEmpty() ? "0" : inLastActDaysRaw.trim());
        } catch (NumberFormatException e) {
            inLastActDays = 0;
        }
        try {
            inOverdraftCount = Integer.parseInt(overdraftRaw.trim().isEmpty() ? "0" : overdraftRaw.trim());
        } catch (NumberFormatException e) {
            inOverdraftCount = 0;
        }
    }

    private static boolean inDormantCandidate() { return inLastActDays >= 365 && inLastActDays <= 9999; }
    private static boolean inActive() { return inLastActDays >= 0 && inLastActDays <= 364; }
    private static boolean inSemiDormant() { return inLastActDays >= 180 && inLastActDays <= 364; }
    private static boolean inTypeSavings() { return "SA".equals(inAccountType); }
    private static boolean inTypeChecking() { return "CH".equals(inAccountType); }
    private static boolean inTypeMoneyMkt() { return "MM".equals(inAccountType); }
    private static boolean inNoOverdraft() { return inOverdraftCount == 0; }
    private static boolean inSomeOverdraft() { return inOverdraftCount >= 1 && inOverdraftCount <= 99; }

    private static void processRec() throws IOException {
        wsCountIn++;
        wsDormantFlagTmp = "N";
        wsReasonTmp = "  ";
        wsActionTmp = "            ";
        wsCategory = "  ";

        // EVALUATE TRUE
        if (inDormantCandidate() && inTypeSavings()) {
            wsDormantFlagTmp = "Y";
            wsReasonTmp = "DA";
            wsActionTmp = padRight("FLAG DORMANT",12);
        } else if (inDormantCandidate() && inTypeMoneyMkt()) {
            wsDormantFlagTmp = "Y";
            wsReasonTmp = "DA";
            wsActionTmp = padRight("FLAG DORMANT",12);
        } else if (inDormantCandidate() && inTypeChecking()) {
            if (inBalance.compareTo(new BigDecimal("100.00")) < 0) {
                wsDormantFlagTmp = "Y";
                wsReasonTmp = "CH";
                wsActionTmp = padRight("REVIEW CHK ",12);
            } else {
                wsDormantFlagTmp = "N";
                wsReasonTmp = "CH";
                wsActionTmp = padRight("NO ACTION  ",12);
            }
        } else if (inSemiDormant()) {
            wsDormantFlagTmp = "N";
            wsReasonTmp = "SE";
            wsActionTmp = padRight("WATCH LIST ",12);
        } else if (inActive()) {
            wsDormantFlagTmp = "N";
            wsReasonTmp = "AC";
            wsActionTmp = padRight("ACTIVE     ",12);
        } else {
            wsDormantFlagTmp = "N";
            wsReasonTmp = "AC";
            wsActionTmp = padRight("ACTIVE     ",12);
        }

        // SECOND EVALUATE
        if ("Y".equals(wsDormantFlagTmp) && inSomeOverdraft()) {
            wsReasonTmp = "SE";
            wsActionTmp = padRight("REVIEW OD  ",12);
        } else if ("N".equals(wsDormantFlagTmp) && inNoOverdraft()) {
            // CONTINUE
        } else {
            // CONTINUE
        }

        writeOut();
    }

    private static void writeOut() throws IOException {
        // MOVE ...
        String outAccountId = padRight(inAccountId,10);
        String outAccountType = padRight(inAccountType,2);
        String outBalance = padRight(inBalanceRaw,9); // MOVE preserves raw chars
        String outDaysInactive = padRight(inLastActDaysRaw,4);
        String outDormantFlag = wsDormantFlagTmp;
        String outReasonCode = padRight(wsReasonTmp,2);
        String outActionText = padRight(wsActionTmp,12);
        String outBranchCode = padRight(inBranchCode,3);

        String outRec = outAccountId + outAccountType + outBalance + outDaysInactive + outDormantFlag + outReasonCode + outActionText + outBranchCode;
        // Ensure exactly OUT_LEN bytes (ISO-8859-1)
        if (outRec.length() > OUT_LEN) outRec = outRec.substring(0, OUT_LEN);
        if (outRec.length() < OUT_LEN) outRec = padRight(outRec, OUT_LEN);
        outWriter.write(outRec);
        outWriter.newLine();
        wsCountOut++;
        if ("Y".equals(wsDormantFlagTmp)) wsCountFlagged++;
    }

    private static void showTotals() {
        // DISPLAY "IN=" WS-COUNT-IN " OUT=" WS-COUNT-OUT
        // WS-COUNT-* PIC 9(06) -> 6 digits zero padded
        String countInStr = String.format("%06d", wsCountIn);
        String countOutStr = String.format("%06d", wsCountOut);
        String flaggedStr = String.format("%06d", wsCountFlagged);
        System.out.println("IN=" + countInStr + " OUT=" + countOutStr);
        System.out.println("FLAGGED=" + flaggedStr);
    }

    private static String padRight(String s, int len) {
        if (s == null) s = "";
        if (s.length() >= len) return s.substring(0, len);
        StringBuilder sb = new StringBuilder(len);
        sb.append(s);
        for (int i = s.length(); i < len; i++) sb.append(' ');
        return sb.toString();
    }
}
