{"mainClass": "Gen0087", "javaSource": "import java.io.*;
import java.math.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

public class Gen0087 {
    // File records lengths (LINE SEQUENTIAL text records)
    static final int IN_REC_LEN = 53;
    static final int OUT_REC_LEN = 61;

    // Working storage
    static String wsEofFlag = "N";
    static int wsReadCnt = 0;
    static int wsWriteCnt = 0;
    static BigDecimal wsTotalDue = BigDecimal.ZERO.setScale(2);
    static BigDecimal wsPenalty = BigDecimal.ZERO.setScale(2);
    static BigDecimal wsBaseAmt = BigDecimal.ZERO.setScale(2);
    static int wsMonthsNum = 0;
    static String wsTextBuffer = "                    "; // 20
    static int wsInspectCnt = 0;
    static String wsBillCode = "    "; // 4
    static String wsShortName = "     "; //5
    static String wsSizeNorm = "          "; //10
    static String wsNameNorm = "                    "; //20

    // Input current record fields
    static String inBoxId;
    static String inCustName;
    static String inBoxSize;
    static BigDecimal inMonthlyRent;
    static BigDecimal inAnnualFee;
    static int inMonthsOverdue;
    static String inStatusFlag;

    static BufferedReader inReader;
    static BufferedWriter outWriter;

    public static void main(String[] args) throws Exception {
        // Guard against prohibited APIs - required by prompt: check env usage only allowed
        // No network/process/reflection usage
        String inPath = System.getenv("DD_INFILE");
        String outPath = System.getenv("DD_OUTFILE");
        if (inPath == null) inPath = System.getenv("DD_INFILE");
        // Support also alternative naming? prompt says DD_INFILE, DD_OUTFILE
        if (inPath == null) {
            // try to fallback to any DD_ env? But still need literal usage
            // keep null check
        }
        String p1 = System.getenv("DD_INFILE");
        String p2 = System.getenv("DD_OUTFILE");
        if (p1 != null) inPath = p1;
        if (p2 != null) outPath = p2;
        if (inPath == null || outPath == null) {
            System.err.println("DD_INFILE/DD_OUTFILE not set");
            System.exit(1);
        }
        inReader = Files.newBufferedReader(Paths.get(inPath), StandardCharsets.ISO_8859_1);
        outWriter = Files.newBufferedWriter(Paths.get(outPath), StandardCharsets.ISO_8859_1);

        mainPara();

        outWriter.flush();
        outWriter.close();
        inReader.close();

        // DISPLAY
        // Format: 'GEN0087 DONE READ=' WS-READ-CNT ' WRITTEN=' WS-WRITE-CNT
        // WS-READ-CNT PIC 9(06) -> display 6 digits with leading zeros
        String readDisp = String.format("%06d", wsReadCnt);
        String writtenDisp = String.format("%06d", wsWriteCnt);
        System.out.println("GEN0087 DONE READ=" + readDisp + " WRITTEN=" + writtenDisp);
    }

    static void mainPara() throws Exception {
        // OPEN INPUT IN-FILE OUTPUT OUT-FILE implied
        while (true) {
            String line = readInFile();
            if (line == null) {
                wsEofFlag = "Y";
            }
            if ("Y".equals(wsEofFlag)) break;
            wsReadCnt++;
            // TRUNC(STD) handling for counters would keep 6 digits; we keep int but display modulo 1e6 if needed
            wsReadCnt = wsReadCnt % 1000000;
            processOne();
        }
        // CLOSE
    }

    static void processOne() throws Exception {
        wsTextBuffer = padSpaces("", 20);
        wsBillCode = padSpaces("", 4);
        wsShortName = padSpaces("", 5);
        wsSizeNorm = padSpaces("", 10);
        wsNameNorm = padSpaces("", 20);

        wsTextBuffer = inCustName; // PIC X(20) move
        // INSPECT WS-TEXT-BUFFER REPLACING ALL ' ' BY '-'
        wsTextBuffer = wsTextBuffer.replace(' ', '-');
        // INSPECT WS-TEXT-BUFFER TALLYING WS-INSPECT-CNT FOR ALL '-'
        // Note: COBOL TALLYING does not initialise counter; but in original code WS-INSPECT-CNT starts 0 and is never reset.
        // However PROCESS-ONE should tally per record; but spec doesn't reset. In COBOL TALLYING adds to current value.
        // The prompt says preserve semantics exactly. The original code does NOT move 0 to WS-INSPECT-CNT before tally.
        // That would cause accumulation across records. But typical synthetic expects reset? Let's check code: no MOVE 0 before TALLY.
        // So we must accumulate, matching COBOL.
        int cnt = countOccurrences(wsTextBuffer, "-"); // FOR ALL '-' counts occurrences (non-overlapping)
        wsInspectCnt += cnt;
        // Keep within PIC 9(03) TRUNC(STD): modulo 1000
        wsInspectCnt = wsInspectCnt % 1000;

        wsNameNorm = inCustName;
        // REPLACING ALL '_' BY ' '
        wsNameNorm = wsNameNorm.replace('_', ' ');
        // CONVERTING lowercase to uppercase
        wsNameNorm = wsNameNorm.toUpperCase(); // equivalent to converting a-z to A-Z
        wsShortName = substringPad(wsNameNorm, 0, 5); // (1:05)

        wsSizeNorm = inBoxSize;
        wsSizeNorm = wsSizeNorm.replace('_', ' ');
        wsSizeNorm = wsSizeNorm.toUpperCase();
        // MOVE WS-SIZE-NORM(1:03) TO WS-SIZE-NORM(1:03) is no-op

        wsMonthsNum = inMonthsOverdue;
        wsBaseAmt = inMonthlyRent;

        // COMPUTE WS-TOTAL-DUE = IN-ANNUAL-FEE + (WS-BASE-AMT * WS-MONTHS-NUM)
        // Use BigDecimal, exact
        wsTotalDue = inAnnualFee.add(wsBaseAmt.multiply(BigDecimal.valueOf(wsMonthsNum)));
        wsTotalDue = wsTotalDue.setScale(2, RoundingMode.UNNECESSARY); // COBOL retains scale 2
        // Truncate to PIC 9(06)V99 range? TRUNC(STD) would keep low order digits but we keep as is; formatting will truncate display.
        // Overflow handling: store only 6+2 digits? We'll apply truncation for stored value: modulo 1000000
        wsTotalDue = truncToPic(wsTotalDue, 6, 2);

        if ("O".equals(inStatusFlag)) {
            // COMPUTE WS-PENALTY = WS-BASE-AMT * 0.10 * WS-MONTHS-NUM
            wsPenalty = wsBaseAmt.multiply(new BigDecimal("0.10")).multiply(BigDecimal.valueOf(wsMonthsNum));
            wsPenalty = wsPenalty.setScale(2, RoundingMode.HALF_UP); // COBOL rounding for COMPUTE? Use half up? Actually COBOL default rounding? We use HALF_UP to match.
            wsPenalty = truncToPic(wsPenalty, 4, 2);
            wsTotalDue = wsTotalDue.add(wsPenalty).setScale(2, RoundingMode.UNNECESSARY);
            wsTotalDue = truncToPic(wsTotalDue, 6, 2);
            wsBillCode = "OVRD";
        } else {
            wsPenalty = BigDecimal.ZERO.setScale(2);
            wsPenalty = truncToPic(wsPenalty, 4, 2);
            wsBillCode = "BILL";
        }
        if (wsInspectCnt > 3) {
            wsTotalDue = wsTotalDue.add(new BigDecimal("5.00"));
            wsTotalDue = truncToPic(wsTotalDue, 6, 2);
        }

        // MOVE to output
        String outBoxId = padOrTruncate(inBoxId, 8);
        String outCustNameFmt = padOrTruncate(wsNameNorm, 20);
        String outBoxSizeFmt = padOrTruncate(wsSizeNorm, 10);
        String outTotalDueStr = formatPic9(wsTotalDue, 6, 2);
        String outPenaltyAmtStr = formatPic9(wsPenalty, 4, 2);
        String outBillCode = padOrTruncate(wsBillCode, 4);
        String outShortName = padOrTruncate(wsShortName, 5);

        String outRec = outBoxId + outCustNameFmt + outBoxSizeFmt + outTotalDueStr + outPenaltyAmtStr + outBillCode + outShortName;
        // WRITE OUT-REC-GEN0087 - LINE SEQUENTIAL: one line per record
        outWriter.write(outRec);
        outWriter.newLine();
        wsWriteCnt++;
        wsWriteCnt = wsWriteCnt % 1000000;
    }

    static String readInFile() throws Exception {
        String line = inReader.readLine();
        if (line == null) return null;
        // LINE SEQUENTIAL with fixed-length bytes: take as provided, pad/truncate to 53
        // If file was written as bytes without newline, readLine still works for LINE SEQUENTIAL text
        String rec = padSpaces(line, IN_REC_LEN);
        if (rec.length() > IN_REC_LEN) rec = rec.substring(0, IN_REC_LEN);
        // Parse fields
        // 1-8 BOX-ID X(08)
        // 9-28 CUST-NAME X(20)
        // 29-38 BOX-SIZE X(10)
        // 39-44 MONTHLY-RENT 9(04)V99 -> 6 chars digits
        // 45-50 ANNUAL-FEE 9(04)V99 -> 6 chars
        // 51-52 MONTHS-OVERDUE 9(02) -> 2 chars
        // 53 STATUS X(01)
        int pos = 0;
        inBoxId = rec.substring(pos, pos+8); pos+=8;
        inCustName = rec.substring(pos, pos+20); pos+=20;
        inBoxSize = rec.substring(pos, pos+10); pos+=10;
        String sMonthly = rec.substring(pos, pos+6); pos+=6;
        String sAnnual = rec.substring(pos, pos+6); pos+=6;
        String sMonths = rec.substring(pos, pos+2); pos+=2;
        inStatusFlag = rec.substring(pos, pos+1); pos+=1;

        inMonthlyRent = parsePic9(sMonthly, 2);
        inAnnualFee = parsePic9(sAnnual, 2);
        inMonthsOverdue = parsePicInt(sMonths);

        return rec;
    }

    static BigDecimal parsePic9(String s, int scale) {
        // PIC 9(n)V99 stored as digits without decimal point, possibly spaces? If blank treat as 0
        s = s.trim();
        if (s.isEmpty()) return BigDecimal.ZERO.setScale(scale);
        // Keep only digits and sign? For this copybook unsigned
        String digits = s.replaceAll("[^0-9]", "");
        if (digits.isEmpty()) digits="0";
        BigDecimal v = new BigDecimal(digits);
        v = v.movePointLeft(scale).setScale(scale, RoundingMode.UNNECESSARY);
        return v;
    }
    static int parsePicInt(String s) {
        s=s.trim();
        if (s.isEmpty()) return 0;
        try { return Integer.parseInt(s.replaceAll("[^0-9\\-]", "")); } catch(Exception e){ return 0;}
    }
    static String formatPic9(BigDecimal v, int intDigits, int scale) {
        // DISPLAY without decimal point, 9(n)V99 -> total intDigits+scale digits with leading zeros
        // Negative handling not needed (unsigned)
        v = v.setScale(scale, RoundingMode.HALF_UP);
        boolean negative = v.signum() < 0;
        v = v.abs();
        // Truncate to PIC digits: keep low order digits (TRUNC STD)
        // e.g., if value exceeds 10^intDigits, keep remainder modulo 10^intDigits
        BigDecimal mod = BigDecimal.TEN.pow(intDigits + scale);
        // Actually value with scale: integer representation = v * 10^scale
        BigInteger intRep = v.movePointRight(scale).toBigIntegerExact();
        BigInteger modVal = BigInteger.TEN.pow(intDigits+scale);
        intRep = intRep.mod(modVal);
        String s = intRep.toString();
        int total = intDigits + scale;
        if (s.length() < total) s = "0".repeat(total - s.length()) + s;
        if (negative) {
            // For unsigned PIC, COBOL would not have negative, but if occurs we would carry sign in display via overpunch?
            // Not needed here
        }
        return s;
    }
    static BigDecimal truncToPic(BigDecimal v, int intDigits, int scale) {
        v = v.setScale(scale, RoundingMode.DOWN); // truncation? COBOL COMPUTE without ROUNDED truncates? Keep scale
        // Apply TRUNC(STD) storage: value modulo 10^intDigits
        // For PIC 9(06)V99 max 999999.99, overflow wraps
        BigDecimal limit = BigDecimal.TEN.pow(intDigits);
        if (v.abs().compareTo(limit) >= 0) {
            // Keep low order intDigits digits for integer part, preserve fractional
            // Equivalent to v modulo 10^intDigits (with sign)
            BigDecimal[] divRem = v.divideAndRemainder(limit);
            // For positive, remainder is v % limit
            // For negative, COBOL keeps sign?
            v = v.remainder(limit);
            v = v.setScale(scale, RoundingMode.UNNECESSARY);
        }
        return v;
    }
