{"mainClass": "Gen0095", "javaSource": "import java.io.*;
import java.math.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

public class Gen0095 {
    private static final int IN_REC_LEN = 54;
    private static final int OUT_REC_LEN = 61;

    public static void main(String[] args) throws Exception {
        String inPath = System.getenv("DD_INFILE");
        String outPath = System.getenv("DD_OUTFILE");
        if (inPath == null) inPath = System.getenv("DD_INFILE");
        if (outPath == null) outPath = System.getenv("DD_OUTFILE");
        // Fallback names if not set (should not happen in test harness)
        if (inPath == null) inPath = "INFILE";
        if (outPath == null) outPath = "OUTFILE";
        List<String> lines = Files.readAllLines(Paths.get(inPath), StandardCharsets.ISO_8859_1);
        List<String> outLines = new ArrayList<>();
        for (String raw : lines) {
            // LINE SEQUENTIAL: record is line as is. Pad/truncate to IN_REC_LEN for field extraction.
            String rec = padRight(raw, IN_REC_LEN);
            // If line longer, keep as is truncated to IN_REC_LEN for IN fields (excess ignored) but spec says one record per line
            if (raw.length() > IN_REC_LEN) rec = raw.substring(0, IN_REC_LEN);
            String out = processRecord(rec);
            outLines.add(out);
        }
        // Write LINE SEQUENTIAL: one record per line, no extra separators beyond newline
        Path outP = Paths.get(outPath);
        try (BufferedWriter w = Files.newBufferedWriter(outP, StandardCharsets.ISO_8859_1)) {
            for (int i = 0; i < outLines.size(); i++) {
                w.write(outLines.get(i));
                if (i < outLines.size() - 1) w.newLine();
                else if (!lines.isEmpty()) w.newLine(); // mimic COBOL LINE SEQUENTIAL final newline if input had content
                // If input was empty, produce empty file (no newline)
            }
            // Handle case where input empty: still no output; ensure file exists empty
            if (lines.isEmpty()) {
                // already handled, file is empty
            }
        }
        // Handle empty input: need to ensure file truncated correctly (above does)
        // If outLines empty, the writer created empty file
    }

    private static String processRecord(String inRec) {
        // Parse IN fields from fixed positions (0-based)
        String inAcctNum = substring(inRec, 0, 10);
        String inAcctName = substring(inRec, 10, 20);
        String sBalance = substring(inRec, 30, 9); // 9(7)V99
        String sRate = substring(inRec, 39, 4);    // 9(2)V99
        String sDays = substring(inRec, 43, 3);    // 9(3)
        // String inAcctType = substring(inRec,46,8); // unused

        BigDecimal balance = parseNumber(sBalance, 2); // 7+2 digits, implied 2 decimals
        BigDecimal rate = parseNumber(sRate, 2);
        int days = parseInt(sDays);

        // WORKING STORAGE init
        BigDecimal wsInterest = BigDecimal.ZERO;
        BigDecimal wsTotalDue = BigDecimal.ZERO;

        // Name handling
        String wsNameUp = inAcctName; // MOVE IN-ACCT-NAME TO WS-NAME-UP (X20)
        // Ensure exactly 20 chars padded
        wsNameUp = padRight(wsNameUp, 20).substring(0,20);

        int wsSpaceCnt = countChar(wsNameUp, ' ');

        // REPLACING ALL '_' BY ' '
        wsNameUp = wsNameUp.replace('_', ' ');
        // CONVERTING lower to upper
        wsNameUp = wsNameUp.toUpperCase(Locale.ROOT);

        // Reference modification to build initials
        // WS-INIT PIC X(05) VALUE SPACES
        char[] wsInitArr = new char[5];
        Arrays.fill(wsInitArr, ' ');
        int wsPos = 1; // 1-based index into wsInit
        // MOVE WS-NAME-UP(1:1) TO WS-INIT(1:1)
        wsInitArr[0] = wsNameUp.charAt(0);
        // PERFORM VARYING WS-I FROM 2 BY 1 UNTIL >20
        for (int wsI = 2; wsI <= 20; wsI++) {
            char wsChar = wsNameUp.charAt(wsI - 1);
            if (wsChar == ' ' && wsI < 20) {
                char next = wsNameUp.charAt(wsI); // WS-I+1:1 (1-based)
                if (next != ' ') {
                    wsPos += 1;
                    if (wsPos <= 5) {
                        wsInitArr[wsPos - 1] = next;
                    }
                }
            }
        }
        String wsInit = new String(wsInitArr);

        // Daily rate and interest charge
        // WS-DAILY-RATE PIC 9(2)V9(6)
        BigDecimal wsDailyRate = BigDecimal.ZERO;
        if (days > 0 && balance.compareTo(BigDecimal.ZERO) > 0) {
            // COMPUTE WS-DAILY-RATE = IN-OD-RATE / 36500
            // COBOL COMPUTE with PIC 9(2)V9(6) would round? Default is not ROUNDED.
            // Without ROUNDED, truncation occurs on storage. We simulate by computing exact then truncating to 6 decimal places.
            // rate is already with 2 decimals, e.g. "0750" => 7.50
            BigDecimal exact = rate.divide(new BigDecimal("36500"), 20, RoundingMode.DOWN);
            // Truncate (not round) to 6 decimal places, and also integer part limited to 2 digits (TRUNC STD not relevant here)
            wsDailyRate = truncate(exact, 6);
            // Interest
            BigDecimal interestRaw = balance.multiply(wsDailyRate).multiply(BigDecimal.valueOf(days));
            // FUNCTION INTEGER(WS-INTEREST *100)/100  => truncation toward zero
            BigDecimal tmp = interestRaw.multiply(BigDecimal.valueOf(100));
            BigDecimal integ = integerPartTruncate(tmp);
            wsInterest = integ.divide(BigDecimal.valueOf(100), 2, RoundingMode.UNNECESSARY);
            // Ensure stored as 9(7)V99 => truncate to 2 decimals and limit to 7 integer digits (overflow wraps via TRUNC STD but unlikely in test)
            wsInterest = truncate(wsInterest, 2);
        } else {
            wsInterest = BigDecimal.ZERO;
        }
        wsTotalDue = balance.add(wsInterest);
        // Storage truncation to PIC 9(7)V99 (scale 2)
        wsInterest = truncate(wsInterest, 2);
        wsTotalDue = truncate(wsTotalDue, 2);

        // Build OUT-REC
        String outAcctNum = padRight(inAcctNum, 10).substring(0,10);
        String outDispName = padRight(wsNameUp, 20).substring(0,20);
        String outNameInit = padRight(wsInit, 5).substring(0,5);
        String outIntCharge = format9V99(wsInterest, 7, 2); // 9 chars
        String outTotalDue = format9V99(wsTotalDue, 7, 2);
        String outSpaceCnt = format9(wsSpaceCnt, 3);
        String outFlag;
        if (wsInterest.compareTo(new BigDecimal("500")) > 0) {
            outFlag = "HIGH ";
        } else if (wsInterest.compareTo(new BigDecimal("100")) > 0) {
            outFlag = "MED  ";
        } else {
            outFlag = "LOW  ";
        }
        return outAcctNum + outDispName + outNameInit + outIntCharge + outTotalDue + outSpaceCnt + outFlag;
    }

    private static BigDecimal parseNumber(String s, int decimals) {
        s = s.trim();
        if (s.isEmpty()) return BigDecimal.ZERO;
        // Keep only digits and sign
        // For PIC 9(7)V99 the text is digits without decimal point; we insert decimal
        // If string contains '.' keep as is (defensive)
        if (s.contains(".")) {
            try { return new BigDecimal(s); } catch (Exception e) { return BigDecimal.ZERO; }
        }
        // Remove non-digit
        String digits = s.replaceAll("[^0-9-]", "");
        if (digits.isEmpty() || digits.equals("-")) return BigDecimal.ZERO;
        boolean neg = digits.startsWith("-");
        if (neg) digits = digits.substring(1);
        // pad left with zeros if needed
        BigDecimal val = new BigDecimal(digits);
        if (decimals > 0) val = val.movePointLeft(decimals);
        if (neg) val = val.negate();
        return val;
    }

    private static int parseInt(String s) {
        s = s.trim();
        if (s.isEmpty()) return 0;
        try { return Integer.parseInt(s.replaceAll("[^0-9-]", "")); } catch (Exception e) { return 0; }
    }

    private static int countChar(String s, char c) {
        int cnt=0; for(int i=0;i<s.length();i++) if(s.charAt(i)==c) cnt++; return cnt;
    }

    private static String padRight(String s, int len) {
        if (s.length() >= len) return s;
        StringBuilder sb = new StringBuilder(s);
        while (sb.length() < len) sb.append(' ');
        return sb.toString();
    }

    private static String substring(String s, int off, int len) {
        if (off >= s.length()) return padRight("", len);
        int end = Math.min(s.length(), off+len);
        String sub = s.substring(off, end);
        if (sub.length() < len) sub = padRight(sub, len);
        return sub;
    }

    private static BigDecimal truncate(BigDecimal v, int scale) {
        return v.setScale(scale, RoundingMode.DOWN);
    }

    private static BigDecimal integerPartTruncate(BigDecimal v) {
        // FUNCTION INTEGER truncates toward zero
        return v.setScale(0, RoundingMode.DOWN);
    }

    private static String format9V99(BigDecimal v, int intDigits, int decDigits) {
        // PIC 9(7)V99 displays as digits without point, zero padded, truncating overflow to TRUNC STD (keep low-order digits)
        // v is already truncated to decDigits
        v = v.setScale(decDigits, RoundingMode.DOWN);
        boolean neg = v.signum() < 0;
        if (neg) v = v.abs();
        BigDecimal scaled = v.movePointRight(decDigits); // integer representation
        // Keep only intDigits+decDigits low-order digits (TRUNC STD)
        int totalDigits = intDigits + decDigits;
        BigDecimal mod = BigDecimal.TEN.pow(totalDigits);
        scaled = scaled.remainder(mod);
        long iv = scaled.longValue(); // fits in 9 digits (<1e9)
        String s = String.format("%0" + totalDigits + "d", iv);
        return s;
    }

    private static String format9(int v, int digits) {
        int mod = (int)Math.pow(10, digits);
        int vv = ((v % mod)+mod)%mod;
        return String.format("%0" + digits + "d", vv);
    }
}
