{"mainClass": "Gen0104", "javaSource": "import java.io.*;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

public class Gen0104 {
    private static Path inPath;
    private static Path outPath;
    private static BufferedReader inReader;
    private static BufferedWriter outWriter;

    private static String wsEofFlag = "N";
    private static int wsReadCnt = 0;
    private static int wsWriteCnt = 0;
    private static BigDecimal wsRemainingLim = BigDecimal.ZERO;
    private static BigDecimal wsApprovedAmt = BigDecimal.ZERO;
    private static String wsDeclineCode = "  ";

    // Input current record fields (GEN0104I-REC = 41 chars: 1 + 40)
    private static String g04iRecType = " ";
    private static String g04iRecBody = ""; // 40
    private static String g04iA_acctNo = "";
    private static String g04iA_reqAmtStr = "";
    private static String g04iA_dailyUsedStr = "";
    private static String g04iA_limitStr = "";
    private static String g04iB_cardNo = "";
    private static String g04iB_atmId = "";
    private static String g04iB_reqAmtStr = "";
    private static String g04iB_availBalStr = "";

    // Output record fields
    private static String g04oRecType = " ";
    private static int g04oSeqNo = 0;
    private static String g04oAcctOrCard = "";
    private static BigDecimal g04oReqAmt = BigDecimal.ZERO;
    private static BigDecimal g04oRemaining = BigDecimal.ZERO;
    private static BigDecimal g04oApprovedAmt = BigDecimal.ZERO;
    private static String g04oDecision = " ";
    private static String g04oReasonCode = "  ";
    private static String g04oAtmIdOut = "";

    private static boolean isEof() { return "Y".equals(wsEofFlag); }

    public static void main(String[] args) throws Exception {
        String inFile = System.getenv("DD_INFILE");
        String outFile = System.getenv("DD_OUTFILE");
        if (inFile == null) inFile = System.getenv("DD_INFILE");
        if (outFile == null) outFile = System.getenv("DD_OUTFILE");
        // Also support generic names if not found (fallback)
        if (inFile == null) inFile = System.getenv("DD_INFILE");
        if (outFile == null) outFile = System.getenv("DD_OUTFILE");

        mainPara();
    }

    private static void mainPara() throws Exception {
        openFiles();
        while (!isEof()) {
            String line = readInFile();
            if (line == null) {
                wsEofFlag = "Y";
            } else {
                wsReadCnt++;
                // parse IN record: pad to 41 with spaces
                String rec = padRight(line, 41);
                // For LINE SEQUENTIAL with ISO-8859-1, the line already excludes newline
                // If file contains raw bytes, reading via ISO-8859-1 preserves chars 0-255
                g04iRecType = rec.substring(0, 1);
                g04iRecBody = rec.substring(1, 41);
                // Pre-parse TYPE-A fields
                // G04I-REC-BODY X(40): TYPE-A layout: X(10) + 9(7)V99(9) + 9(7)V99(9) + 9(7)V99(9) + X(4) = 10+27+4=41? Wait 10+9+9+9+4=41 but body is 40.
                // Actually copybook says BODY X(40) but TYPE-A breakdown totals 41. Use GnuCOBOL redefines size = max; so body 40 implies truncation.
                // We follow exact positions within the 41-char whole record: rec is 41 chars.
                // So TYPE-A fields offsets from start: 1: recType, 1-10 acct, 11-19 req, 20-28 daily, 29-37 limit, 38-41 filler
                // TYPE-B: 1 recType, 1-16 card, 17-22 atm, 23-29 req(7), 30-38 avail(9), 39-42 filler -> exceeds 41 slight; we cap.
                parseInputFields(rec);
                processRecord();
            }
        }
        closeFiles();
    }

    private static void parseInputFields(String rec) {
        // rec length 41 padded
        // Helper to get substring safely
        // TYPE A
        g04iA_acctNo = sub(rec, 1, 10);
        g04iA_reqAmtStr = sub(rec, 11, 9);
        g04iA_dailyUsedStr = sub(rec, 20, 9);
        g04iA_limitStr = sub(rec, 29, 9);
        // TYPE B
        g04iB_cardNo = sub(rec, 1, 16);
        g04iB_atmId = sub(rec, 17, 6);
        g04iB_reqAmtStr = sub(rec, 23, 7);
        g04iB_availBalStr = sub(rec, 30, 9);
    }

    private static String sub(String s, int pos, int len) {
        // pos is 0-based index corresponding to COBOL 1-based; here pos already 0-based start in rec
        // Actually rec 0=recType, so pos param is offset from 0
        if (pos >= s.length()) return padRight("", len);
        int end = Math.min(pos + len, s.length());
        String t = s.substring(pos, end);
        if (t.length() < len) t = padRight(t, len);
        return t;
    }

    private static void processRecord() throws Exception {
        // MOVE SPACES TO GEN0104O-REC then move type
        g04oRecType = g04iRecType;
        g04oAcctOrCard = padRight("", 16);
        g04oReqAmt = BigDecimal.ZERO;
        g04oRemaining = BigDecimal.ZERO;
        g04oApprovedAmt = BigDecimal.ZERO;
        g04oDecision = " ";
        g04oReasonCode = "  ";
        g04oAtmIdOut = padRight("", 6);

        // EVALUATE
        if ("A".equals(g04iRecType)) {
            handleTypeA();
        } else if ("B".equals(g04iRecType)) {
            handleTypeB();
        } else {
            handleUnknown();
        }
        wsWriteCnt++;
        g04oSeqNo = wsReadCnt; // PIC 9(5)
        writeGen0104ORec();
    }

    private static void handleTypeA() {
        g04oAcctOrCard = padRight(g04iA_acctNo, 16);
        BigDecimal reqAmt = parseDisplayUnsigned(g04iA_reqAmtStr, 2);
        BigDecimal dailyUsed = parseDisplayUnsigned(g04iA_dailyUsedStr, 2);
        BigDecimal limit = parseDisplayUnsigned(g04iA_limitStr, 2);
        g04oReqAmt = reqAmt;
        wsRemainingLim = limit.subtract(dailyUsed);
        if (wsRemainingLim.compareTo(BigDecimal.ZERO) < 0) {
            wsRemainingLim = BigDecimal.ZERO;
        }
        // MOVE WS-REMAINING-LIM TO G04O-REMAINING (S9(7)V99)
        g04oRemaining = wsRemainingLim;
        if (reqAmt.compareTo(wsRemainingLim) <= 0) {
            wsApprovedAmt = reqAmt;
            wsDeclineCode = "OK";
            g04oDecision = "A";
        } else {
            wsApprovedAmt = BigDecimal.ZERO;
            wsDeclineCode = "OL";
            g04oDecision = "D";
        }
        g04oApprovedAmt = wsApprovedAmt;
        g04oReasonCode = wsDeclineCode;
        g04oAtmIdOut = "TYPEA ";
    }

    private static void handleTypeB() {
        g04oAcctOrCard = padRight(g04iB_cardNo, 16);
        BigDecimal reqAmt = parseDisplayUnsigned(g04iB_reqAmtStr, 2);
        BigDecimal availBal = parseDisplayUnsigned(g04iB_availBalStr, 2);
        g04oReqAmt = reqAmt;
        g04oRemaining = availBal;
        BigDecimal fiveHundred = new BigDecimal("500.00");
        if (reqAmt.compareTo(availBal) <= 0) {
            if (reqAmt.compareTo(fiveHundred) <= 0) {
                wsApprovedAmt = reqAmt;
                wsDeclineCode = "OK";
                g04oDecision = "A";
            } else {
                wsApprovedAmt = BigDecimal.ZERO;
                wsDeclineCode = "TL";
                g04oDecision = "D";
            }
        } else {
            wsApprovedAmt = BigDecimal.ZERO;
            wsDeclineCode = "IF";
            g04oDecision = "D";
        }
        g04oApprovedAmt = wsApprovedAmt;
        g04oReasonCode = wsDeclineCode;
        g04oAtmIdOut = padRight(g04iB_atmId, 6);
    }

    private static void handleUnknown() {
        g04oAcctOrCard = padRight("", 16);
        g04oReqAmt = BigDecimal.ZERO;
        g04oRemaining = BigDecimal.ZERO;
        g04oApprovedAmt = BigDecimal.ZERO;
        g04oReasonCode = "UK";
        g04oDecision = "D";
        g04oAtmIdOut = "UNKNWN";
    }

    // DISPLAY numeric helpers
    private static BigDecimal parseDisplayUnsigned(String s, int decimals) {
        // s is digits possibly with spaces; treat spaces as 0? If all spaces -> 0
        s = s == null ? "" : s;
        StringBuilder digits = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c >= '0' && c <= '9') digits.append(c);
            else if (c == ' ' ) digits.append('0');
            else digits.append('0');
        }
        if (digits.length() == 0) return BigDecimal.ZERO;
        BigDecimal v = new BigDecimal(digits.toString());
        if (decimals > 0) v = v.movePointLeft(decimals);
        return v;
    }

    private static String formatUnsigned(BigDecimal v, int totalDigits, int decimals) {
        // PIC 9(n)V99 : totalDigits = n+decimals? Here we pass totalDigits including decimals (e.g. 9 for 9(7)V99)
        // Format as integer of totalDigits digits with leading zeros, no decimal point
        BigDecimal scaled = v.setScale(decimals, RoundingMode.UNNECESSARY);
        // Handle truncation/overflow: keep only PIC digits (TRUNC STD) - mod 10^totalDigits
        // For simplicity, take absolute and mod
        BigDecimal factor = BigDecimal.TEN.pow(decimals);
        BigDecimal intVal = scaled.multiply(BigDecimal.ONE).movePointRight(decimals); // actually scaled*10^decimals
        // Use BigDecimal to long string
        // Ensure integer
        intVal = intVal.setScale(0, RoundingMode.UNNECESSARY);
        boolean negative = intVal.signum() < 0;
        if (negative) intVal = intVal.abs();
        // TRUNC to totalDigits digits (keep least significant)
        String s = intVal.toPlainString();
        // remove possible sign/minus already
        if (s.startsWith("-")) s = s.substring(1);
        // strip decimal part if any (should not)
        int dot = s.indexOf('.');
        if (dot >= 0) s = s.substring(0, dot);
        if (s.length() > totalDigits) s = s.substring(s.length() - totalDigits);
        s = padLeft(s, totalDigits, '0');
        return s;
    }

    private static String formatSigned(BigDecimal v, int totalDigits, int decimals) {
        boolean negative = v.signum() < 0;
        String digits = formatUnsigned(v.abs(), totalDigits, decimals);
        if (!negative) return digits;
        // Encode sign in last digit: d -> char (d + 0x40)
        char last = digits.charAt(digits.length() - 1);
        int d = last - '0';
        char encoded = (char)(d + 0x40); // 0->0x40 '@', 1->'A' etc as per COBOL signed DISPLAY
        return digits.substring(0, digits.length() - 1) + encoded;
    }

    private static void openFiles() throws Exception {
        String inEnv = System.getenv("DD_INFILE");
        String outEnv = System.getenv("DD_OUTFILE");
        if (inEnv == null) inEnv = "in.txt";
        if (outEnv == null) outEnv = "out.txt";
        inPath = Paths.get(inEnv);
        outPath = Paths.get(outEnv);
        // LINE SEQUENTIAL text, read as ISO-8859-1 bytes, one record per line (no separator added)
        inReader = Files.newBufferedReader(inPath, StandardCharsets.ISO_8859_1);
        outWriter = Files.newBufferedWriter(outPath, StandardCharsets.ISO_8859_1, StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING);
    }

    private static String readInFile() throws Exception {
        return inReader.readLine();
    }

    private static void writeGen0104ORec() throws Exception {
        // Build 63-char record
        StringBuilder sb = new StringBuilder();
        sb.append(padRight(g04oRecType, 1));
        sb.append(formatUnsigned(new BigDecimal(g04oSeqNo), 5, 0)); // PIC 9(5)
        sb.append(padRight(g04oAcctOrCard, 16));
        sb.append(formatUnsigned(g04oReqAmt, 9, 2));
        sb.append(formatSigned(g04oRemaining, 9, 2)); // S9(7)V99
        sb.append(formatUnsigned(g04oApprovedAmt, 9, 2));
        sb.append(padRight(g04oDecision, 1));
        sb.append(padRight(g04oReasonCode, 2));
        sb.append(padRight(g04oAtmIdOut, 6));
        sb.append(padRight("", 5)); // FILLER X(5)
        String rec = sb.toString();
        // Ensure 63
        if (rec.length() > 63) rec = rec.substring(0, 63);
        if (rec.length() < 63) rec = padRight(rec, 63);
        outWriter.write(rec);
        outWriter.write(System.lineSeparator()); // LINE SEQUENTIAL: one record per line
    }

    private static void closeFiles() throws Exception {
        if (inReader != null) inReader.close();
        if (outWriter != null) outWriter.close();
    }

    private static String padRight(String s, int len) {
        if (s == null) s = "";
        if (s.length() > len) return s.substring(0, len);
        StringBuilder sb = new StringBuilder(s);
        while (sb.length() < len) sb.append(' ');
        return sb.toString();
    }
    private static String padLeft(String s, int len, char c) {
        if (s.length() >= len) return s;
        StringBuilder sb = new StringBuilder();
        for (int i = s.length(); i < len; i++) sb.append(c);
        sb.append(s);
        return sb.toString();
    }
}
