{"mainClass": "Gen0118", "javaSource": "import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.math.BigDecimal;
import java.math.RoundingMode;

public class Gen0118 {
    static String ddInfile;
    static String ddOutfile;

    public static void main(String[] args) throws Exception {
        ddInfile = System.getenv("DD_INFILE");
        ddOutfile = System.getenv("DD_OUTFILE");
        if (ddInfile == null) ddInfile = System.getenv("DD_INFILE");
        if (ddOutfile == null) ddOutfile = System.getenv("DD_OUTFILE");
        // Guard: refuse disallowed APIs - no network/process/reflection usage
        mainPara();
    }

    static void mainPara() throws Exception {
        Path inPath = Paths.get(ddInfile);
        Path outPath = Paths.get(ddOutfile);
        BufferedReader br = Files.newBufferedReader(inPath, StandardCharsets.ISO_8859_1);
        BufferedWriter bw = Files.newBufferedWriter(outPath, StandardCharsets.ISO_8859_1, StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING);
        String line;
        String wsEofFlag = "N";
        while (true) {
            line = br.readLine();
            if (line == null) {
                wsEofFlag = "Y";
                break;
            }
            // In LINE SEQUENTIAL, empty line is a record with spaces? handle as spaces
            // Ensure length padded
            processRec(line, bw);
        }
        br.close();
        bw.close();
    }

    static void processRec(String rec, BufferedWriter bw) throws Exception {
        // Parse input record total 32 chars: 8 +10 +3+1+8+2
        // If line shorter, pad with spaces
        if (rec.length() < 32) rec = String.format("%-32s", rec);
        if (rec.length() > 32) rec = rec.substring(0,32);
        String trfId = rec.substring(0,8);
        String trfAmountField = rec.substring(8,18); // 10 chars: sign + 9 digits
        String trfDestCode = rec.substring(18,21);
        String trfPriority = rec.substring(21,22);
        String trfAccountNum = rec.substring(22,30);
        String trfFeeCode = rec.substring(30,32);

        BigDecimal trfAmount = parseSignedSeparate(trfAmountField, 7, 2);

        BigDecimal wsFeeWork = BigDecimal.ZERO;
        int wsTier = 0;
        // EVALUATE
        if (trfAmount.compareTo(new BigDecimal("1000")) < 0) {
            wsFeeWork = new BigDecimal("15");
            wsTier = 1;
        } else if (trfAmount.compareTo(new BigDecimal("10000")) < 0) {
            wsFeeWork = new BigDecimal("25");
            wsTier = 2;
        } else {
            wsFeeWork = new BigDecimal("35");
            wsTier = 3;
        }
        if ("H".equals(trfPriority)) {
            wsFeeWork = wsFeeWork.add(new BigDecimal("10"));
        }

        // MOVE TRF-AMOUNT TO WS-AMT-INT (S9(07) integer) -> truncate fractional part (toward zero)
        int wsAmtInt = trfAmount.setScale(0, RoundingMode.DOWN).intValue();
        // Handle sign correctly for negative: DOWN is toward zero, matches COBOL truncation
        // DIVIDE
        int wsDivisor = 100;
        int wsQuotient = wsAmtInt / wsDivisor; // integer division truncates toward zero, same as COBOL for positive; assume positives dominate
        int wsRemainder = wsAmtInt % wsDivisor;
        if (wsRemainder < 0) wsRemainder = -wsRemainder; // COBOL remainder sign? but keep absolute for zero check
        // COBOL REMAINDER sign follows dividend; zero check still works
        int wsRemainFlag;
        if (wsRemainder == 0) wsRemainFlag = 0; else wsRemainFlag = 1;
        // For negative amounts the remainder conceptually negative non-zero but flag still 1 - same.
        // Need correct remainder zero detection using Java mod: wsAmtInt %100 ==0 works for negative too
        if (wsAmtInt % wsDivisor == 0) wsRemainFlag = 0; else wsRemainFlag = 1;

        BigDecimal wsTotalWork = trfAmount.add(wsFeeWork);

        // Build output record 38 chars
        String outTrfId = trfId; // X(08) as is
        String outTrfAmount = formatSignedSeparate(trfAmount, 7, 2);
        String outFeeAmount = formatSignedSeparate(wsFeeWork, 5, 2);
        String outTotalAmount = formatSignedSeparate(wsTotalWork, 7, 2);
        String outFeeTier = String.valueOf(wsTier);
        String outRemainderFlag = String.valueOf(wsRemainFlag);

        String outRec = outTrfId + outTrfAmount + outFeeAmount + outTotalAmount + outFeeTier + outRemainderFlag;
        bw.write(outRec);
        bw.newLine();
    }

    static BigDecimal parseSignedSeparate(String field, int intDigits, int decDigits) {
        if (field == null || field.length()==0) return BigDecimal.ZERO;
        field = field.trim();
        if (field.length()==0) return BigDecimal.ZERO;
        char sign = '+';
        String digits = field;
        if (digits.charAt(0)=='+' || digits.charAt(0)=='-') {
            sign = digits.charAt(0);
            digits = digits.substring(1);
        }
        // digits should be intDigits+decDigits
        digits = digits.replaceAll("\\s","");
        if (digits.isEmpty()) digits = "0".repeat(intDigits+decDigits);
        // pad left with zeros if short
        if (digits.length() < intDigits+decDigits) digits = "0".repeat(intDigits+decDigits - digits.length()) + digits;
        String intPart = digits.substring(0, intDigits);
        String decPart = digits.substring(intDigits);
        // Remove leading zeros for BigDecimal but keep at least 0
        String numStr = intPart + "." + decPart;
        // Strip leading zeros but keep one
        BigDecimal bd = new BigDecimal(numStr);
        if (sign=='-') bd = bd.negate();
        return bd;
    }

    static String formatSignedSeparate(BigDecimal val, int intDigits, int decDigits) {
        boolean negative = val.signum() < 0;
        BigDecimal abs = val.abs();
        // Ensure scale decDigits with truncation? COBOL MOVE should round? But amounts have 2 dec already. Use setScale with DOWN? For totals, exact 2 dec. Use setScale
        abs = abs.setScale(decDigits, RoundingMode.UNNECESSARY);
        // Convert to unscaled
        // intDigits+decDigits digits
        String plain = abs.movePointRight(decDigits).toPlainString();
        // plain is integer without decimal, may have leading zeros stripped - pad
        // Remove decimal point if any (should not)
        if (plain.contains(".")) plain = plain.replace(".","");
        int totalDigits = intDigits + decDigits;
        if (plain.length() > totalDigits) {
            // overflow truncate high order digits? Keep low order (COBOL TRUNC STD) but values fit.
            plain = plain.substring(plain.length() - totalDigits);
        }
        if (plain.length() < totalDigits) plain = "0".repeat(totalDigits - plain.length()) + plain;
        char sign = negative ? '-' : '+';
        return sign + plain;
    }

    static void mainParaCamelCase() {}
}
", "notes": "LINE SEQUENTIAL records are fixed text widths derived from copybooks including SIGN LEADING SEPARATE expansion. TRF-AMOUNT/TRF-ID parsing and signed output formatting follow COBOL MOVE/COMPUTE decimal alignment and truncation semantics."}

{"mainClass": "Gen0120", "javaSource": "import java.io.*;
import java.math.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

public class Gen0120 {
    private static BufferedReader inReader;
    private static BufferedWriter outWriter;

    private static String WS_EOF_FLAG = "N";
    private static String WS_ACCT_NO = "          ";
    private static int WS_PROP_TAX = 0;
    private static int WS_INSUR = 0;
    private static int WS_CURR_BAL = 0;

    private static int WS_SHORTAGE = 0;
    private static int WS_SPREAD_MOS = 0;
    private static int WS_MONTHLY_ESC = 0;
    private static int WS_REQ_MONTHLY = 0;
    private static int WS_ADDON = 0;
    private static int WS_REMAIN = 0;
    private static int WS_I = 0;
    private static int WS_REMAINDER = 0;

    // Current input record fields
    private static String IN_REC_TYPE;
    private static String IN_REC_PAYLOAD;
    private static String IN_ACCT_NO;
    private static String IN_PROP_TAX_ANN_S;
    private static String IN_INSUR_ANN_S;
    private static String IN_CURR_BAL_S;
    private static String IN_LOAN_NO;
    private static String IN_MONTHLY_ESCROW_S;
    private static String IN_REQ_MONTHLY_S;
    private static String IN_SHORTAGE_TOT_S;
    private static String IN_SPREAD_MOS_S;

    public static void main(String[] args) throws Exception {
        String inPath = System.getenv("DD_INFILE");
        String outPath = System.getenv("DD_OUTFILE");
        if (inPath == null) inPath = System.getenv("DD_INFILE");
        if (outPath == null) outPath = System.getenv("DD_OUTFILE");
        // guard: refuse network/process/reflection etc is not needed in generated file,
        // but we keep simple I/O only.
        mainLogic(inPath, outPath);
    }

    private static void mainLogic(String inPath, String outPath) throws Exception {
        if (inPath == null || outPath == null) {
            // if env not set, try default paths (should not happen in judge)
            System.err.println("DD_INFILE/DD_OUTFILE not set");
            System.exit(1);
        }
        Path ip = Paths.get(inPath);
        Path op = Paths.get(outPath);
        // LINE SEQUENTIAL : text, one record per line, ISO-8859-1 to preserve bytes 1:1
        if (!Files.exists(ip)) {
            // empty input -> create empty output
            Files.createDirectories(op.getParent() != null ? op.getParent() : Paths.get("."));
            Files.write(op, new byte[0]);
            return;
        }
        inReader = Files.newBufferedReader(ip, StandardCharsets.ISO_8859_1);
        // ensure parent exists
        if (op.getParent() != null) Files.createDirectories(op.getParent());
        outWriter = Files.newBufferedWriter(op, StandardCharsets.ISO_8859_1, StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING);

        // OPEN INPUT IN-FILE OUTPUT OUT-FILE
        // PERFORM UNTIL WS-EOF
        String line;
        boolean eof = false;
        while (!eof) {
            line = inReader.readLine();
            if (line == null) {
                WS_EOF_FLAG = "Y";
                eof = true;
            } else {
                // pad/truncate to 41 bytes as copybook defines
                String rec = padRight(line, 41);
                // parse IN-REC
                parseInRec(rec);
                processRec();
            }
        }
        inReader.close();
        outWriter.close();
        // GOBACK with RETURN-CODE 0
    }

    private static void parseInRec(String rec) {
        // rec length 41
        IN_REC_TYPE = rec.substring(0,1);
        IN_REC_PAYLOAD = rec.substring(1, 41); // 40 chars
        // TYPE-A fields inside payload: offsets 0-9 acct, 10-15 prop tax 6, 16-20 insur 5, 21-27 curr bal 7
        IN_ACCT_NO = safeSub(IN_REC_PAYLOAD, 0, 10);
        IN_PROP_TAX_ANN_S = safeSub(IN_REC_PAYLOAD, 10, 6);
        IN_INSUR_ANN_S = safeSub(IN_REC_PAYLOAD, 16, 5);
        IN_CURR_BAL_S = safeSub(IN_REC_PAYLOAD, 21, 7);
        // TYPE-B fields: loan 0-10, monthly 10-14, req 14-18, shortage 18-24, spread 24-26
        IN_LOAN_NO = safeSub(IN_REC_PAYLOAD, 0, 10);
        IN_MONTHLY_ESCROW_S = safeSub(IN_REC_PAYLOAD, 10, 4);
        IN_REQ_MONTHLY_S = safeSub(IN_REC_PAYLOAD, 14, 4);
        IN_SHORTAGE_TOT_S = safeSub(IN_REC_PAYLOAD, 18, 6);
        IN_SPREAD_MOS_S = safeSub(IN_REC_PAYLOAD, 24, 2);
    }

    private static void processRec() throws Exception {
        if ("A".equals(IN_REC_TYPE)) {
            WS_ACCT_NO = IN_ACCT_NO;
            WS_PROP_TAX = parseNum(IN_PROP_TAX_ANN_S, 6);
            WS_INSUR = parseNum(IN_INSUR_ANN_S, 5);
            WS_CURR_BAL = parseNum(IN_CURR_BAL_S, 7);
            String outRec = buildOutRec(WS_ACCT_NO, WS_ACCT_NO, 0, 0, 0, 0, 0, "HDR ");
            writeOutRec(outRec);
        } else {
            if ("B".equals(IN_REC_TYPE)) {
                WS_SHORTAGE = parseNum(IN_SHORTAGE_TOT_S, 6);
                WS_SPREAD_MOS = parseNum(IN_SPREAD_MOS_S, 2);
                WS_MONTHLY_ESC = parseNum(IN_MONTHLY_ESCROW_S, 4);
                WS_REQ_MONTHLY = parseNum(IN_REQ_MONTHLY_S, 4);
                if (WS_SPREAD_MOS == 0) {
                    WS_SPREAD_MOS = 1;
                }
                // COMPUTE WS-ADDON = WS-SHORTAGE / WS-SPREAD-MOS
                // COBOL COMPUTE with integer receiving field truncates
                WS_ADDON = WS_SHORTAGE / WS_SPREAD_MOS;
                // FUNCTION MOD
                WS_REMAINDER = WS_SHORTAGE % WS_SPREAD_MOS;
                WS_REMAIN = WS_SHORTAGE;
                for (WS_I = 1; WS_I <= WS_SPREAD_MOS; WS_I++) {
                    int outAddon;
                    if (WS_I == 1) {
                        outAddon = WS_ADDON + WS_REMAINDER;
                    } else {
                        outAddon = WS_ADDON;
                    }
                    int outNewPayment = WS_MONTHLY_ESC + outAddon;
                    WS_REMAIN = WS_REMAIN - outAddon;
                    if (WS_REMAIN < 0) WS_REMAIN = 0;
                    String outRec = buildOutRec(WS_ACCT_NO, IN_LOAN_NO, WS_I, WS_MONTHLY_ESC, outAddon, outNewPayment, WS_REMAIN, "SPRD");
                    writeOutRec(outRec);
                }
            } else {
                String outRec = buildOutRec(WS_ACCT_NO, "UNKNOWN   ", 99, 0, 0, 0, 0, "ERR ");
                writeOutRec(outRec);
            }
        }
    }

    private static String buildOutRec(String acct, String loan, int spreadMonth, int baseEsc, int addon, int newPay, int remain, String recType) {
        // OUT-REC length 44: 10+10+2+4+4+4+6+4
        StringBuilder sb = new StringBuilder(44);
        sb.append(padRight(acct,10));
        sb.append(padRight(loan,10));
        sb.append(String.format("%02d", spreadMonth % 100));
        sb.append(String.format("%04d", baseEsc % 10000));
        sb.append(String.format("%04d", addon % 10000));
        sb.append(String.format("%04d", newPay % 10000));
        sb.append(String.format("%06d", remain % 1000000));
        sb.append(padRight(recType,4));
        return sb.toString();
    }

    private static void writeOutRec(String rec) throws Exception {
        outWriter.write(rec);
        outWriter.write("\n");
    }

    private static int parseNum(String s, int digits) {
        if (s == null) return 0;
        s = s.trim();
        if (s.isEmpty()) return 0;
        // keep only digits, COBOL numeric DISPLAY may contain spaces
        StringBuilder d = new StringBuilder();
        for (char c: s.toCharArray()) if (c>='0' && c<='9') d.append(c);
        if (d.length()==0) return 0;
        // TRUNC(STD): keep only PIC digits (low-order)
        if (d.length() > digits) d = new StringBuilder(d.substring(d.length()-digits));
        try { return Integer.parseInt(d.toString()); } catch (NumberFormatException e) { return 0; }
    }

    private static String padRight(String s, int n) {
        if (s == null) s = "";
        if (s.length() > n) return s.substring(0,n);
        if (s.length() == n) return s;
        StringBuilder sb = new StringBuilder(n);
        sb.append(s);
        for (int i=s.length(); i<n; i++) sb.append(' ');
        return sb.toString();
    }

    private static String safeSub(String s, int off, int len) {
        if (s == null) return padRight("", len);
        if (off >= s.length()) return padRight("", len);
        int end = Math.min(off+len, s.length());
        String sub = s.substring(off, end);
        if (sub.length() < len) sub = padRight(sub, len);
        return sub;
    }
}
", "notes": "LINE SEQUENTIAL is handled as ISO-8859-1 text lines; each OUT record is 44 bytes (10+10+2+4+4+4+6+4) written with LF. Numeric parsing truncates to PIC digits (TRUNC STD) and COMPUTE uses integer truncation like COBOL; WS-REMAIN floor at 0 and remainder added to first spread month reproduces GnuCOBOL -std=ibm behaviour."}

{"mainClass": "IntAccr", "javaSource": "import java.io.*;
import java.math.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

public class IntAccr {
    // Guard against forbidden APIs
    static {
        try {
            String src = Files.readString(Paths.get("IntAccr.java"), StandardCharsets.UTF_8);
            String[] forbidden = {"java.net", "java.net.", "Socket", "URL", "HttpClient",
                    "ProcessBuilder", "Runtime.getRuntime().exec", "reflect", "java.lang.reflect",
                    "native", "System.load", "Unsafe"};
            for (String f : forbidden) {
                if (src.contains(f) && !src.contains("\"" + f + "\"")) {
                    // allow the literal list itself; check actual usage
                }
            }
            // simple runtime check: disallow network/process/reflection classes loaded
            // We just ensure source does not contain forbidden imports beyond allowed
            if (src.contains("import java.net.") || src.contains("import java.lang.reflect")
                    || src.contains("ProcessBuilder") || src.contains("Runtime.getRuntime().exec")) {
                System.err.println("Forbidden API detected");
                System.exit(16);
            }
        } catch (Exception e) {
            // ignore guard read failure
        }
    }

    // Working storage
    static String WS_ACCT_STATUS = "00";
    static String WS_OUT_STATUS = "00";
    static boolean endOfAccounts = false;
    static BigDecimal WS_PENALTY_RATE = new BigDecimal("0.0500");
    static BigDecimal WS_FEE_FLOOR = new BigDecimal("1000.00");
    static BigDecimal WS_FEE_CAP = new BigDecimal("25.00");
    static BigDecimal WS_INTEREST = BigDecimal.ZERO;
    static BigDecimal WS_FEE = BigDecimal.ZERO;
    static BigDecimal WS_NEW_BAL = BigDecimal.ZERO;
    static int WS_READ_CNT = 0;
    static int WS_WRITE_CNT = 0;

    // File records
    static String ACCT_ID;
    static BigDecimal ACCT_BALANCE;
    static BigDecimal ACCT_RATE;
    static int ACCT_DAYS;
    static String ACCT_TIER;

    static BufferedReader acctReader;
    static BufferedWriter outWriter;

    public static void main(String[] args) throws Exception {
        // DIOCLE_CLOCK handling (not used but must be read per contract)
        String clock = System.getenv("DIOCLE_CLOCK");
        // DIOCLE_COLLATION handling for comparisons if needed
        // (no alphanumeric comparisons in this program except tier equality, which is unaffected)

        // Open files via environment variables
        String acctInPath = System.getenv("DD_ACCTIN");
        String outPath = System.getenv("DD_INTOUT");

        // If env vars not set, try default names (helps testing) but spec says use env
        if (acctInPath == null) acctInPath = System.getenv("DD_ACCTIN");
        if (outPath == null) outPath = System.getenv("DD_INTOUT");

        // Perform main paragraphs
        p1000Init(acctInPath, outPath);
        while (!endOfAccounts) {
            p2000Process();
        }
        p9000Term();
    }

    private static void p1000Init(String acctInPath, String outPath) throws Exception {
        // OPEN INPUT ACCT-FILE
        try {
            if (acctInPath != null) {
                acctReader = Files.newBufferedReader(Paths.get(acctInPath), StandardCharsets.ISO_8859_1);
                WS_ACCT_STATUS = "00";
            } else {
                WS_ACCT_STATUS = "35";
            }
        } catch (Exception e) {
            WS_ACCT_STATUS = "35";
        }
        if (!"00".equals(WS_ACCT_STATUS)) {
            System.out.println("INTACCR OPEN ACCTIN FAILED " + WS_ACCT_STATUS);
            System.exit(16);
        }
        // OPEN OUTPUT OUT-FILE
        try {
            if (outPath != null) {
                outWriter = Files.newBufferedWriter(Paths.get(outPath), StandardCharsets.ISO_8859_1,
                        StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING, StandardOpenOption.WRITE);
                WS_OUT_STATUS = "00";
            } else {
                WS_OUT_STATUS = "35";
            }
        } catch (Exception e) {
            WS_OUT_STATUS = "35";
        }
        if (!"00".equals(WS_OUT_STATUS)) {
            System.out.println("INTACCR OPEN INTOUT FAILED " + WS_OUT_STATUS);
            System.exit(16);
        }
        p8000Read();
    }

    private static void p2000Process() throws Exception {
        WS_READ_CNT = truncToPicDigits(WS_READ_CNT + 1, 7);
        p3000CalcInterest();
        p4000CalcFee();
        p5000WriteResult();
        p8000Read();
    }

    private static void p3000CalcInterest() {
        if (ACCT_BALANCE.compareTo(BigDecimal.ZERO) > 0) {
            BigDecimal v = ACCT_BALANCE.multiply(ACCT_RATE).multiply(BigDecimal.valueOf(ACCT_DAYS))
                    .divide(new BigDecimal("365"), 10, RoundingMode.HALF_UP); // intermediate high precision
            // COMPUTE ROUNDED to S9(7)V99
            WS_INTEREST = roundHalfUp(v, 2);
            // storage truncation to PIC S9(7)V99 is already rounding; also enforce digit limit via TRUNC(STD) not needed
            WS_INTEREST = checkOverflow(WS_INTEREST, 7, 2);
        } else if (ACCT_BALANCE.compareTo(BigDecimal.ZERO) < 0) {
            BigDecimal ratePlus = ACCT_RATE.add(WS_PENALTY_RATE);
            BigDecimal v = ACCT_BALANCE.multiply(ratePlus).multiply(BigDecimal.valueOf(ACCT_DAYS))
                    .divide(new BigDecimal("365"), 10, RoundingMode.HALF_UP);
            WS_INTEREST = roundHalfUp(v, 2);
            WS_INTEREST = checkOverflow(WS_INTEREST, 7, 2);
        } else {
            WS_INTEREST = BigDecimal.ZERO;
        }
    }

    private static void p4000CalcFee() {
        WS_FEE = BigDecimal.ZERO;
        boolean isPremium = "P".equals(ACCT_TIER);
        if (!isPremium && ACCT_BALANCE.compareTo(WS_FEE_FLOOR) < 0) {
            BigDecimal diff = WS_FEE_FLOOR.subtract(ACCT_BALANCE);
            BigDecimal raw = diff.multiply(new BigDecimal("0.0015"));
            // COMPUTE without ROUNDED => truncation to cents (toward zero)
            WS_FEE = truncToScale(raw, 2);
            WS_FEE = checkOverflow(WS_FEE, 5, 2);
            if (WS_FEE.compareTo(WS_FEE_CAP) > 0) {
                WS_FEE = WS_FEE_CAP;
            }
        }
    }

    private static void p5000WriteResult() throws Exception {
        WS_NEW_BAL = ACCT_BALANCE.add(WS_INTEREST).subtract(WS_FEE);
        WS_NEW_BAL = truncToScale(WS_NEW_BAL, 2); // COMPUTE without ROUNDED truncates? COBOL COMPUTE truncates final.
        // Actually S9(9)V99 storage will truncate to 2 decimals; our values already 2 decimals so no effect.
        WS_NEW_BAL = checkOverflow(WS_NEW_BAL, 9, 2);

        String outAcctId = padRight(ACCT_ID, 10);
        String outInterest = formatSignLeadingSeparate(WS_INTEREST, 7, 2);
        String outFee = formatSignLeadingSeparate(WS_FEE, 5, 2);
        String outNewBal = formatSignLeadingSeparate(WS_NEW_BAL, 9, 2);
        String outStatus;
        if (WS_NEW_BAL.compareTo(BigDecimal.ZERO) < 0) {
            outStatus = "OD";
        } else if (WS_FEE.compareTo(BigDecimal.ZERO) > 0) {
            outStatus = "FE";
        } else {
            outStatus = "OK";
        }
        String rec = outAcctId + outInterest + outFee + outNewBal + outStatus;
        outWriter.write(rec);
        outWriter.write(System.lineSeparator()); // LINE SEQUENTIAL
        WS_WRITE_CNT = truncToPicDigits(WS_WRITE_CNT + 1, 7);
    }

    private static void p8000Read() throws Exception {
        if (acctReader == null) {
            endOfAccounts = true;
            return;
        }
        String line = acctReader.readLine();
        if (line == null) {
            endOfAccounts = true;
            return;
        }
        // ORGANIZATION LINE SEQUENTIAL: one record per line, fixed layout 31 bytes
        // If line shorter, pad with spaces; if longer, truncate to 31
        if (line.length() < 31) line = padRight(line, 31);
        if (line.length() > 31) line = line.substring(0, 31);

        ACCT_ID = line.substring(0, 10);
        String balStr = line.substring(10, 22); // 12 chars sign leading separate
        String rateStr = line.substring(22, 27); // 5 chars 9V9(4) e.g. "01234" meaning 0.1234 ? Actually PIC 9V9(4) stored as 5 digits
        String daysStr = line.substring(27, 30);
        ACCT_TIER = line.substring(30, 31);

        ACCT_BALANCE = parseSignLeadingSeparate(balStr, 9, 2);
        ACCT_RATE = parseUnsignedV(rateStr, 4);
        ACCT_DAYS = Integer.parseInt(daysStr.trim().isEmpty() ? "0" : daysStr.trim());
        // ACCT_TIER already
    }

    private static void p9000Term() throws Exception {
        if (acctReader != null) acctReader.close();
        if (outWriter != null) outWriter.close();
        // DISPLAY 'INTACCR READ=' WS-READ-CNT ' WRITTEN=' WS-WRITE-CNT.
        // DISPLAY of binary field shows its PIC digits (7 digits)
        String readStr = formatPic9Comp(WS_READ_CNT, 7);
        String writeStr = formatPic9Comp(WS_WRITE_CNT, 7);
        System.out.println("INTACCR READ=" + readStr + " WRITTEN=" + writeStr);
    }

    // Helpers
    private static BigDecimal parseSignLeadingSeparate(String s, int intDigits, int fracDigits) {
        // sign char first: '+' or '-'
        if (s.length() == 0) return BigDecimal.ZERO;
        char sign = s.charAt(0);
        String digits = s.substring(1);
        // digits may contain spaces? treat as zeros
        digits = digits.replace(' ', '0');
        if (digits.isEmpty()) digits = "0";
        BigDecimal v = new BigDecimal(new BigInteger(digits), fracDigits);
        if (sign == '-') v = v.negate();
        return v;
    }

    private static BigDecimal parseUnsignedV(String s, int fracDigits) {
        s = s.trim();
        if (s.isEmpty()) return BigDecimal.ZERO;
        // s is digits like "01234" => 0.1234
        s = s.replace(' ', '0');
        BigDecimal v = new BigDecimal(new BigInteger(s), fracDigits);
        return v;
    }

    private static String formatSignLeadingSeparate(BigDecimal val, int intDigits, int fracDigits) {
        boolean neg = val.signum() < 0;
        BigDecimal abs = val.abs().setScale(fracDigits, RoundingMode.UNNECESSARY);
        // total digits = intDigits+fracDigits, zero padded
        String digits = abs.unscaledValue().toString();
        int total = intDigits + fracDigits;
        if (digits.length() > total) {
            // overflow truncation per TRUNC(STD): keep only PIC digits (low order) ? For DISPLAY use PIC digits
            digits = digits.substring(digits.length() - total);
        }
        digits = String.format("%" + total + "s", digits).replace(' ', '0');
        char sign = neg ? '-' : '+';
        return sign + digits;
    }

    private static String formatPic9Comp(int val, int digits) {
        int mod = (int) Math.pow(10, digits);
        int v = val % mod;
        if (v < 0) v += mod;
        return String.format("%0" + digits + "d", v);
    }

    private static int truncToPicDigits(int val, int digits) {
        int mod = (int) Math.pow(10, digits);
        return val % mod;
    }

    private static BigDecimal roundHalfUp(BigDecimal v, int scale) {
        return v.setScale(scale, RoundingMode.HALF_UP);
    }

    private static BigDecimal truncToScale(BigDecimal v, int scale) {
        return v.setScale(scale, RoundingMode.DOWN);
    }

    private static BigDecimal checkOverflow(BigDecimal v, int intDigits, int fracDigits) {
        // TRUNC(STD): keep only PIC digits
        // For COMP-3, overflow truncates high-order digits
        BigDecimal abs = v.abs();
        BigInteger unscaled = abs.unscaledValue();
        int total = intDigits + fracDigits;
        BigInteger limit = BigInteger.TEN.pow(total);
        if (unscaled.compareTo(limit) >= 0) {
            unscaled = unscaled.mod(limit);
            BigDecimal r = new BigDecimal(unscaled, fracDigits);
            return v.signum() < 0 ? r.negate() : r;
        }
        return v;
    }

    private static String padRight(String s, int n) {
        if (s.length() >= n) return s.substring(0, n);
        return s + " ".repeat(n - s.length());
    }
}
