{"mainClass": "Loywaive", "javaSource": "import java.io.*;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.List;

public class Loywaive {
    private BufferedReader lyReader;
    private BufferedWriter loWriter;
    private String wsEof = "N";

    // current record fields
    private String lyAcct;
    private BigDecimal lyBalance;
    private int lyTenureMonths;

    private String loAcct;
    private BigDecimal loFee;
    private String loCode;

    public static void main(String[] args) throws Exception {
        String inPath = System.getenv("DD_LOYIN");
        String outPath = System.getenv("DD_LOYOUT");
        Loywaive p = new Loywaive();
        p.run(inPath, outPath);
    }

    void run(String inPath, String outPath) throws Exception {
        openFiles(inPath, outPath);
        mainLoop();
        closeFiles();
    }

    private void openFiles(String inPath, String outPath) throws IOException {
        if (inPath == null) inPath = "LOYIN";
        if (outPath == null) outPath = "LOYOUT";
        lyReader = Files.newBufferedReader(Paths.get(inPath), StandardCharsets.ISO_8859_1);
        loWriter = Files.newBufferedWriter(Paths.get(outPath), StandardCharsets.ISO_8859_1,
                StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING, StandardOpenOption.WRITE);
    }

    private void closeFiles() throws IOException {
        if (lyReader != null) lyReader.close();
        if (loWriter != null) loWriter.close();
    }

    private void mainLoop() throws IOException {
        // 0000-MAIN
        // OPEN already done, PERFORM UNTIL WS-EOF = 'Y'
        while (!"Y".equals(wsEof)) {
            String line = lyReader.readLine();
            if (line == null) {
                wsEof = "Y";
            } else {
                parseLyRec(line);
                _1000Fee();
            }
        }
    }

    private void parseLyRec(String line) {
        // LY-REC total 21: X(8) + S9(7)V99 SIGN LEADING SEPARATE (10) + 9(3) (3)
        // Pad with spaces if short (LINE SEQUENTIAL may trim trailing spaces)
        if (line.length() < 21) {
            line = String.format("%-21s", line);
        }
        if (line.length() > 21) {
            line = line.substring(0, 21);
        }
        lyAcct = line.substring(0, 8);
        String balField = line.substring(8, 18); // 10 chars
        String tenureField = line.substring(18, 21); // 3 chars

        // Parse balance: sign leading separate
        // balField is sign char + 9 digits (7 integer + 2 decimal)
        // Example: "+000500000" => 5000.00 ; "-000001234" => -12.34
        char signChar = balField.charAt(0);
        String digits = balField.substring(1); // 9 chars
        // If digits contains non-digit (e.g. spaces), treat as zero; but normally digits
        // Keep only 0-9, if malformed, BigDecimal zero
        StringBuilder cleanDigits = new StringBuilder();
        for (int i = 0; i < digits.length(); i++) {
            char c = digits.charAt(i);
            if (c >= '0' && c <= '9') cleanDigits.append(c);
            else if (c == ' ') cleanDigits.append('0');
            else cleanDigits.append(c);
        }
        String d = cleanDigits.toString();
        // Ensure 9 digits
        if (d.length() < 9) d = String.format("%9s", d).replace(' ', '0');
        if (d.length() > 9) d = d.substring(d.length() - 9);
        // Insert decimal point before last 2 digits
        String intPart = d.substring(0, 7);
        String fracPart = d.substring(7, 9);
        BigDecimal bd = new BigDecimal(intPart + "." + fracPart);
        if (signChar == '-') {
            bd = bd.negate();
        }
        // '+' or other => positive
        lyBalance = bd;

        // Parse tenure: PIC 9(3) unsigned
        String t = tenureField.trim();
        if (t.isEmpty()) t = "0";
        // Remove non-digits
        StringBuilder tb = new StringBuilder();
        for (char c : tenureField.toCharArray()) {
            if (c >= '0' && c <= '9') tb.append(c);
        }
        if (tb.length() == 0) lyTenureMonths = 0;
        else {
            try { lyTenureMonths = Integer.parseInt(tb.toString()); } catch (NumberFormatException e) { lyTenureMonths = 0; }
        }
    }

    // 1000-FEE paragraph
    private void _1000Fee() throws IOException {
        loAcct = lyAcct;
        // IF LY-BALANCE NOT < 5000.00 OR LY-TENURE-MONTHS NOT < 120
        // i.e. LY-BALANCE >= 5000.00 OR LY-TENURE-MONTHS >= 120
        BigDecimal thresh = new BigDecimal("5000.00");
        boolean cond1 = lyBalance.compareTo(thresh) >= 0;
        boolean cond2 = lyTenureMonths >= 120;
        if (cond1 || cond2) {
            loFee = BigDecimal.ZERO;
            loCode = "WV";
        } else {
            loFee = new BigDecimal("4.50");
            loCode = "CH";
        }
        writeLoRec();
    }

    private void writeLoRec() throws IOException {
        // LO-REC: X(8) + 9(2)V99 (4 digits) + XX (2) = 14 chars
        String feeStr;
        // LO-FEE PIC 9(2)V99 : store as digits without decimal point, 4 digits zero padded
        // fee is either 0 or 4.50
        // Use BigDecimal *100
        BigDecimal scaled = loFee.movePointRight(2); // 0 or 450
        int feeInt = scaled.intValueExact(); // 0..9999
        feeStr = String.format("%04d", feeInt);
        // Ensure exactly 4 chars
        if (feeStr.length() > 4) feeStr = feeStr.substring(feeStr.length() - 4);
        String outLine = loAcct + feeStr + loCode;
        loWriter.write(outLine);
        loWriter.newLine();
    }
}
", "notes": "LOYIN is LINE SEQUENTIAL: LY-BALANCE is PIC S9(7)V99 SIGN LEADING SEPARATE (10 chars: sign + 7 integer digits + 2 decimal digits, implied decimal), tenure 9(3). LYWAIVE waives when balance >=5000.00 or tenure >=120. LOYOUT is LINE SEQUENTIAL: LO-FEE PIC 9(2)V99 written as 4 digits (e.g. 0450, 0000)."}

{"mainClass": "Qvfee020", "javaSource": "import java.io.*;
import java.math.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

public class Qvfee020 {
    private static BufferedReader acctReader;
    private static BufferedWriter feeWriter;
    private static boolean endOfFile = false;
    private static String qaRecLine;
    // QA fields parsed from current line
    private static String qaAcctId;
    private static BigDecimal qaBalance; // S9(9)V99
    private static String qaRateStr; // not used
    private static String qaDaysStr;
    private static String qaTier;
    private static int qaNsfCount;

    private static final BigDecimal WS_ITEM_FEE = new BigDecimal("29.00");
    private static final BigDecimal WS_DAILY_CAP = new BigDecimal("87.00");
    private static BigDecimal wsFee = BigDecimal.ZERO;
    private static String qfReason;

    public static void main(String[] args) throws Exception {
        String acctIn = System.getenv("DD_ACCTIN");
        String feeOut = System.getenv("DD_FEEOUT");
        if (acctIn == null || feeOut == null) {
            System.err.println("Missing DD env vars");
            System.exit(1);
        }
        acctReader = Files.newBufferedReader(Paths.get(acctIn), StandardCharsets.ISO_8859_1);
        feeWriter = Files.newBufferedWriter(Paths.get(feeOut), StandardCharsets.ISO_8859_1,
                StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING);
        m0000Main();
    }

    private static void m0000Main() throws Exception {
        // OPEN INPUT ACCT-FILE OUTPUT FEE-FILE
        m8000Read();
        while (!endOfFile) {
            m2000Assess();
        }
        acctReader.close();
        feeWriter.close();
    }

    private static void m2000Assess() throws Exception {
        wsFee = BigDecimal.ZERO;
        qfReason = "NONE";
        // EVALUATE TRUE in order
        if ("P".equals(qaTier)) {
            qfReason = "WPRM";
        } else if (qaBalance.compareTo(new BigDecimal("-10.00")) >= 0 && qaNsfCount == 0) {
            // CONTINUE - keep NONE and zero
        } else if ("S".equals(qaTier) && qaNsfCount <= 2) {
            qfReason = "WSTU";
        } else {
            m3000Calc();
        }
        // MOVE QA-ACCT-ID TO QF-ACCT-ID, MOVE WS-FEE TO QF-FEE, WRITE
        String outLine = buildFeeRecord(qaAcctId, wsFee, qfReason);
        feeWriter.write(outLine);
        feeWriter.newLine();
        m8000Read();
    }

    private static void m3000Calc() {
        // COMPUTE WS-FEE = QA-NSF-COUNT * WS-ITEM-FEE
        BigDecimal fee = WS_ITEM_FEE.multiply(BigDecimal.valueOf(qaNsfCount));
        // Truncate to 2 decimals as COBOL would when storing into S9(3)V99 (TRUNC)
        fee = trunc2(fee);
        if (qaBalance.compareTo(new BigDecimal("-10.00")) < 0) {
            // COMPUTE WS-FEE = WS-FEE - QA-BALANCE * 0.005
            BigDecimal add = qaBalance.multiply(new BigDecimal("0.005")); // negative
            fee = fee.subtract(add); // minus negative = plus
            fee = trunc2(fee);
        }
        if (fee.compareTo(WS_DAILY_CAP) > 0) {
            wsFee = WS_DAILY_CAP;
            qfReason = "CAPD";
        } else {
            // Apply TRUNC(STD) overflow handling for S9(3)V99 then move to S9(5)V99
            // For values within range just keep fee
            wsFee = truncWithPic(fee, 3);
            qfReason = "CHRG";
        }
        // If fee was capped we already assigned cap value
    }

    private static BigDecimal trunc2(BigDecimal v) {
        return v.setScale(2, RoundingMode.DOWN);
    }

    // TRUNC(STD): keep only PIC digits (integer digits = n). For S9(3)V99
    private static BigDecimal truncWithPic(BigDecimal v, int intDigits) {
        // keep sign, truncate to 2 decimals first already done
        // overflow: value keeps only lowest intDigits digits of integer part
        // This is modulo 10^intDigits for positive, similar for negative.
        BigDecimal scaled = v.setScale(2, RoundingMode.DOWN);
        boolean neg = scaled.signum() < 0;
        BigDecimal abs = scaled.abs();
        BigDecimal intPart = abs.setScale(0, RoundingMode.DOWN); // floor
        BigDecimal frac = abs.subtract(intPart); // 0.xx
        BigDecimal mod = BigDecimal.TEN.pow(intDigits);
        // keep low-order digits: intPart % mod
        BigDecimal low = intPart.remainder(mod);
        BigDecimal result = low.add(frac);
        if (neg) result = result.negate();
        return result.setScale(2, RoundingMode.DOWN);
    }

    private static String buildFeeRecord(String acctId, BigDecimal fee, String reason) {
        // QF-ACCT-ID X(10) padded/truncated as in file (as read, spaces)
        String id = padRight(acctId, 10);
        // QF-FEE S9(5)V99 SIGN LEADING SEPARATE - 8 chars: sign + 7 digits (5+2) zero padded, no dot
        String feeStr = formatSignedSeparate(fee, 5, 2);
        String rs = padRight(reason, 4);
        return id + feeStr + rs;
    }

    private static String formatSignedSeparate(BigDecimal v, int intDigits, int decDigits) {
        v = v.setScale(decDigits, RoundingMode.DOWN);
        boolean neg = v.signum() < 0;
        BigDecimal abs = v.abs();
        // total digits = intDigits+decDigits
        int total = intDigits + decDigits;
        // scale to integer: multiply by 10^decDigits
        BigDecimal scaled = abs.movePointRight(decDigits); // e.g., 29.00 -> 2900
        long iv = scaled.longValueExact(); // fits in 7 digits max 9,999,999
        String digits = String.format("%0" + total + "d", iv);
        // if total digits overflow due to TRUNC handling already, take rightmost
        if (digits.length() > total) digits = digits.substring(digits.length() - total);
        char sign = neg ? '-' : '+';
        return sign + digits;
    }

    private static void m8000Read() throws Exception {
        String line = acctReader.readLine();
        if (line == null) {
            endOfFile = true;
            return;
        }
        qaRecLine = line;
        parseQaRec(line);
    }

    private static void parseQaRec(String line) {
        // Ensure length 33, pad with spaces if shorter
        if (line.length() < 33) line = padRight(line, 33);
        qaAcctId = line.substring(0, 10);
        String balStr = line.substring(10, 22); // 12 chars sign leading separate
        qaBalance = parseSignedSeparate(balStr, 9, 2);
        qaRateStr = line.substring(22, 27); // 5 chars
        qaDaysStr = line.substring(27, 30);
        qaTier = line.substring(30, 31);
        String nsfStr = line.substring(31, 33);
        qaNsfCount = Integer.parseInt(nsfStr.trim().isEmpty() ? "0" : nsfStr);
    }

    private static BigDecimal parseSignedSeparate(String s, int intDigits, int decDigits) {
        // s = sign char + digits (no dot). e.g., +00000001000 for 10.00
        s = s.trim();
        if (s.isEmpty()) return BigDecimal.ZERO;
        char sign = s.charAt(0);
        String digits = s.substring(1).trim();
        // digits may contain leading zeros; ensure numeric
        if (digits.isEmpty()) digits = "0";
        // keep only digits
        StringBuilder b = new StringBuilder();
        for (char c : digits.toCharArray()) if (Character.isDigit(c)) b.append(c);
        digits = b.toString();
        if (digits.isEmpty()) digits = "0";
        BigDecimal val = new BigDecimal(digits);
        val = val.movePointLeft(decDigits);
        if (sign == '-') val = val.negate();
        return val;
    }

    private static String padRight(String s, int n) {
        if (s == null) s = "";
        if (s.length() > n) return s.substring(0, n);
        StringBuilder sb = new StringBuilder(s);
        while (sb.length() < n) sb.append(' ');
        return sb.toString();
    }
}
", "notes": "LINE SEQUENTIAL text handling: QA-BALANCE S9(9)V99 SIGN LEADING SEPARATE is sign + 11 digits (no decimal point) and QF-FEE is sign + 7 digits. COMPUTE truncation uses RoundingMode.DOWN to mimic COBOL without ROUNDED. TRUNC(STD) overflow keeps low-order integer digits. EVALUATE order preserves PREMIUM > boundary check > STUDENT waiver > CALC, with cap flag CAPD. File paths from DD_ACCTIN/DD_FEEOUT and ISO-8859-1 bytes as required."}
